INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13363, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "足够，完全满足需要或条件。", "primary_collocate": null, "pronunciation": "chōng fèn", "ipa": "tʂʰʊŋ˥ fən˥˩", "syllable_count": 2, "sentences": [{"text": "这次考试他准备得很充分。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的理由不够充分，我不同意。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了我们充分的时间。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们有充分的证据证明这件事。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，大家都做了充分的准备。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法有充分的根据。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的讨论很充分，大家都说了意见。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们有充分的理由相信他会成功。", "target_word": "充分", "complexity_tier": "T3", "furigana": "wǒ men yǒu chōng fèn de lǐ yóu xiāng xìn tā huì chéng gōng", "sentence_source": "generated"}, {"text": "材料不充分，我们没法做决定。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说你的检查还不够充分。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容理由、证据、准备等足够，完全满足需要或条件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884de977-ec2d-4491-87db-758e8e0f7dc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13363, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "充分", "is_correct": true, "explanation": "充分（chōng fèn）指足够、完全满足需要或条件，是本题的目标词。"}, {"text": "春分", "is_correct": false, "explanation": "春分（chūn fēn）与充分（chōng fèn）第一音节韵母不同（ūn 对 ōng），第二音节声调也不同（fēn 对 fèn），意思是春天的节气，不是足够的意思。"}, {"text": "中分", "is_correct": false, "explanation": "中分（zhōng fèn）与充分（chōng fèn）声母不同（zh 对 ch），意思是头发从中间分开。"}, {"text": "冲犯", "is_correct": false, "explanation": "冲犯（chōng fàn）与充分（chōng fèn）第二音节韵母不同（a 对 en），声调相同，意思是冒犯。"}, {"text": "成分", "is_correct": false, "explanation": "成分（chéng fèn）与充分（chōng fèn）第一音节韵母与声调不同，意思是组成部分。"}, {"text": "冲锋", "is_correct": false, "explanation": "冲锋（chōng fēng）与充分（chōng fèn）第二音节韵母与声调不同，意思是向前猛冲。"}], "explanations": {"充分": "充分（chōng fèn）指足够、完全满足需要或条件，是本题的目标词。", "春分": "春分（chūn fēn）与充分（chōng fèn）第一音节韵母不同（ūn 对 ōng），第二音节声调也不同（fēn 对 fèn），意思是春天的节气，不是足够的意思。", "中分": "中分（zhōng fèn）与充分（chōng fèn）声母不同（zh 对 ch），意思是头发从中间分开。", "冲犯": "冲犯（chōng fàn）与充分（chōng fèn）第二音节韵母不同（a 对 en），声调相同，意思是冒犯。", "成分": "成分（chéng fèn）与充分（chōng fèn）第一音节韵母与声调不同，意思是组成部分。", "冲锋": "冲锋（chōng fēng）与充分（chōng fèn）第二音节韵母与声调不同，意思是向前猛冲。"}, "sentence_index": null, "correct_answer": "充分"}, "level_3": {"options": [{"text": "充分", "is_correct": true, "explanation": "充分：准备足够、完全到位，符合句意。"}, {"text": "富裕", "is_correct": false, "explanation": "搭配：“富裕”说的是经济条件，不能用来说准备的程度。"}, {"text": "严重", "is_correct": false, "explanation": "语义：“严重”说情况或后果很糟，与“准备得很”的积极语境不合。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”形容空间大，不能用来形容准备的程度。"}], "explanations": {"充分": "充分：准备足够、完全到位，符合句意。", "富裕": "搭配：“富裕”说的是经济条件，不能用来说准备的程度。", "严重": "语义：“严重”说情况或后果很糟，与“准备得很”的积极语境不合。", "宽敞": "搭配：“宽敞”形容空间大，不能用来形容准备的程度。"}, "sentence_index": 0, "correct_answer": "充分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的汉语水平很充分。", "explanation": "这里应该用〈高〉。高说程度深；充分表示条件或准备足够，不用来说水平的高低。"}, {"text": "他的笑容很充分，大家都很喜欢。", "explanation": "这里应该用〈灿烂〉。灿烂说光彩或笑容明朗；充分说条件或准备足够，不用来形容笑容。"}, {"text": "他对家人的感情很充分。", "explanation": "这里应该用〈深厚〉。感情的程度用“深厚”来说；充分表示条件或准备足够，不用来形容感情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13363, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "充分", "is_correct": true, "explanation": "充分：讨论进行得完全到位，大家都说了意见，符合句意。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”指没什么人或活动，与“大家都说了意见”矛盾。"}, {"text": "昂贵", "is_correct": false, "explanation": "搭配：“昂贵”说价格高，不能用来形容讨论。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的身材外形，不能用来形容讨论。"}], "explanations": {"充分": "充分：讨论进行得完全到位，大家都说了意见，符合句意。", "冷清": "语义：“冷清”指没什么人或活动，与“大家都说了意见”矛盾。", "昂贵": "搭配：“昂贵”说价格高，不能用来形容讨论。", "高大": "体貌：“高大”形容人或物的身材外形，不能用来形容讨论。"}, "sentence_index": 6, "correct_answer": "充分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的研究方法很充分。", "explanation": "这里应该用〈严谨〉。严谨说做事周密认真；充分说条件或准备足够，不用来形容研究方法。"}, {"text": "这个孩子的身体很充分。", "explanation": "这里应该用〈健康〉。健康说身体状况好；充分说条件或准备足够，不用来形容身体。"}, {"text": "他是个很充分的人。", "explanation": "这里应该用〈能干〉。能干说人的能力强；充分说理由、证据、准备等事物足够，不用来形容人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13363, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个理由很很充分，我们可以去。", "corrected_sentence": "这个理由很充分，我们可以去。", "error_description": "重复程度副词：“很”只用一个，应说“很充分”，不能说“很很充分”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13363, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份证据还不够更充分，需要再查一查。", "corrected_sentence": "这份证据还不够充分，需要再查一查。", "error_description": "程度副词叠用：“不够”已表示程度不足，“更”不能与“不够”同时修饰“充分”，应删去“更”，说“还不够充分”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13364, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "污染", "is_correct": true, "explanation": "正确。「净化」使环境清洁，「污染」使环境受到杂质损害，二者意义相反。"}, {"text": "播种", "is_correct": false, "explanation": "与「净化」无反义关系；「播种」指撒种子，与清洁环境无关。"}, {"text": "旅行", "is_correct": false, "explanation": "与「净化」无反义关系；「旅行」指出游，与环境的清洁程度无关。"}, {"text": "跳舞", "is_correct": false, "explanation": "与「净化」无反义关系；「跳舞」是身体活动，与清除杂质无关。"}], "correct_answer": "污染", "explanations": {"污染": "正确。「净化」使环境清洁，「污染」使环境受到杂质损害，二者意义相反。", "播种": "与「净化」无反义关系；「播种」指撒种子，与清洁环境无关。", "旅行": "与「净化」无反义关系；「旅行」指出游，与环境的清洁程度无关。", "跳舞": "与「净化」无反义关系；「跳舞」是身体活动，与清除杂质无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b861901-a8a7-4920-a931-2ea8e81bdd82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13364, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "污染", "is_correct": true, "explanation": "正确。「净化」使环境清洁，「污染」使环境受到杂质损害，二者意义相反。"}, {"text": "烹饪", "is_correct": false, "explanation": "与「净化」无反义关系；「烹饪」指做饭，与清除杂质无关。"}, {"text": "收集", "is_correct": false, "explanation": "与「净化」无反义关系；「收集」指聚集物品，与环境的清洁程度无关。"}, {"text": "游泳", "is_correct": false, "explanation": "与「净化」无反义关系；「游泳」是身体活动，与清除杂质无关。"}], "correct_answer": "污染", "explanations": {"污染": "正确。「净化」使环境清洁，「污染」使环境受到杂质损害，二者意义相反。", "烹饪": "与「净化」无反义关系；「烹饪」指做饭，与清除杂质无关。", "收集": "与「净化」无反义关系；「收集」指聚集物品，与环境的清洁程度无关。", "游泳": "与「净化」无反义关系；「游泳」是身体活动，与清除杂质无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b861901-a8a7-4920-a931-2ea8e81bdd82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13364, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "清除杂质，使物体或环境变得纯净、清洁。", "primary_collocate": null, "pronunciation": "jìng huà", "ipa": "tɕiŋ˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "含有重金属、偶氮染料及有毒化学助剂的工业废水未经充分净化即排入河流与地下水系统，导致水体污染长期化、隐蔽化，对生物多样性及当地居民健康构成深远威胁。", "target_word": "净化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "树木可以净化空气，减少噪音，还能帮助小动物和小鸟找到家。", "target_word": "净化", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这台机器可以净化空气。", "target_word": "净化", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工厂要先净化污水，再排到河里。", "target_word": "净化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "绿色植物能净化房间里的空气。", "target_word": "净化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们家用机器净化自来水。", "target_word": "净化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "污水净化以后，鱼又回来了。", "target_word": "净化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湿地能净化水，也能保护小动物。", "target_word": "净化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用沙子和石头净化河水。", "target_word": "净化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想买一台能净化空气的机器。", "target_word": "净化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "净化了", "label": "体标"}, {"form": "净化过", "label": "体标"}, {"form": "净化器", "label": "复合"}], "register": "中性", "sense_fingerprint": "清除杂质，使空气、水等环境变纯净", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18eb6d63-0232-4cd9-8252-5118ed2ad4bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13364, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "净化", "is_correct": true, "explanation": "正确。「净化」指清除杂质，与「未经充分」「即排入河流」构成废水处理的语境。"}, {"text": "生长", "is_correct": false, "explanation": "语义：生长不能用于废水处理，「未经充分生长即排入河流」说不通。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：装饰与废水处理无关，「未经充分装饰即排入河流」不符合语境。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：欣赏不是废水处理的环节，与后面「排入河流与地下水系统」的污染语境矛盾。"}], "explanations": {"净化": "正确。「净化」指清除杂质，与「未经充分」「即排入河流」构成废水处理的语境。", "生长": "语义：生长不能用于废水处理，「未经充分生长即排入河流」说不通。", "装饰": "语义：装饰与废水处理无关，「未经充分装饰即排入河流」不符合语境。", "欣赏": "语义：欣赏不是废水处理的环节，与后面「排入河流与地下水系统」的污染语境矛盾。"}, "sentence_index": 0, "correct_answer": "净化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师先净化试卷，再发给学生。", "explanation": "这里应该用〈批改〉。试卷要批改，「净化」用于水、空气等环境，不用于试卷。"}, {"text": "司机先净化汽车，再出发。", "explanation": "这里应该用〈洗〉。洗车是去掉车身污物，「净化」用于水、空气等环境，不用于车辆。"}, {"text": "妈妈先净化桌子，再吃饭。", "explanation": "这里应该用〈擦〉。擦桌子是用布去掉表面污物，「净化」多用于水、空气，不说「净化桌子」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b861901-a8a7-4920-a931-2ea8e81bdd82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "净化", "is_correct": true, "explanation": "正确。「净化」表示去除污水中的杂质，「以后，鱼又回来了」说明水质变好。"}, {"text": "绘画", "is_correct": false, "explanation": "语义：绘画不能施于污水，「污水绘画以后」说不通。"}, {"text": "驾驶", "is_correct": false, "explanation": "语义：驾驶的对象是车辆等，不能用于污水，句子不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌不能作用于污水，与「鱼又回来了」的水质变化无关。"}], "explanations": {"净化": "正确。「净化」表示去除污水中的杂质，「以后，鱼又回来了」说明水质变好。", "绘画": "语义：绘画不能施于污水，「污水绘画以后」说不通。", "驾驶": "语义：驾驶的对象是车辆等，不能用于污水，句子不通。", "唱歌": "语义：唱歌不能作用于污水，与「鱼又回来了」的水质变化无关。"}, "sentence_index": 6, "correct_answer": "净化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈先净化面包，再切片。", "explanation": "这里应该用〈烤〉。烤面包是加热处理食物，「净化」指去除水、空气等的杂质，不用于食物加热。"}, {"text": "公司要净化产品质量，不能出问题。", "explanation": "这里应该用〈检验〉。产品质量要靠检验，「净化」指去除水、空气等的杂质，不用于质量检查。"}, {"text": "她每天净化手，然后吃饭。", "explanation": "这里应该用〈洗〉。洗手是去掉手上的污物，「净化」不用于人体部位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b861901-a8a7-4920-a931-2ea8e81bdd82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器把水净化很干净。", "corrected_sentence": "这台机器把水净化得很干净。", "error_description": "补语错误：「把水净化」后接状态补语需要用「得」，应为「净化得很干净」，不能省略「得」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b861901-a8a7-4920-a931-2ea8e81bdd82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人用过滤器把净化河水。", "corrected_sentence": "工人用过滤器净化河水。", "error_description": "把字错误：「把」字句需「把+宾语+动词」，此处「把」后直接接动词，「把净化河水」不通，应删去「把」，正确为「工人用过滤器净化河水」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b861901-a8a7-4920-a931-2ea8e81bdd82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13365, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13365, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13365, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示事情紧接着发生，相当于‘就’或‘便’", "primary_collocate": null, "pronunciation": "jí", "ipa": "tɕi˧˥", "syllable_count": 1, "sentences": [{"text": "他一回到家即打开电视。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议结束后，大家即回家了。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们收到信即回复你。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到这条消息，他即告诉了朋友。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你到了学校即给我打电话。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人一到，我们即开始吃饭。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说完，同学们即安静下来。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到铃声，学生们即进教室。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天一亮，他们即出发了。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理看完信，即同意了这个计划。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "放在动词前，表示一件事之后紧接着做另一件事，相当于就、便", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884de977-ec2d-4491-87db-758e8e0f7dc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13365, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "即", "is_correct": true, "explanation": "即（jí）表示紧接着，是本题的目标词。"}, {"text": "鸡", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是鸡。"}, {"text": "几", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个、几次。"}, {"text": "记", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是记住、记录。"}], "explanations": {"即": "即（jí）表示紧接着，是本题的目标词。", "鸡": "jī（第一声）与 jí（第二声）声调不同，意思是鸡。", "几": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个、几次。", "记": "jì（第四声）与 jí（第二声）声调不同，意思是记住、记录。"}, "sentence_index": null, "correct_answer": "即"}, "level_3": {"options": [{"text": "即", "is_correct": true, "explanation": "即：紧接着，表示回到家后马上开电视，符合句意。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”通常与否定词连用，表示一贯如此，不能直接修饰“打开电视”。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去有过的经历，与“一回到家”紧接的动作不符。"}, {"text": "差点", "is_correct": false, "explanation": "语义：“差点”表示几乎发生却没有发生，与“回家就开电视”的句意矛盾。"}], "explanations": {"即": "即：紧接着，表示回到家后马上开电视，符合句意。", "从来": "搭配：“从来”通常与否定词连用，表示一贯如此，不能直接修饰“打开电视”。", "曾经": "语义：“曾经”指过去有过的经历，与“一回到家”紧接的动作不符。", "差点": "语义：“差点”表示几乎发生却没有发生，与“回家就开电视”的句意矛盾。"}, "sentence_index": 0, "correct_answer": "即"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子听完故事，即很困。", "explanation": "这里应该用〈就〉。即表示紧接着，后面要接动作，不能接“很困”这样的状态；就可以接状态。"}, {"text": "他昨天很晚即回到家。", "explanation": "这里应该用〈才〉。才表示事情比预期晚；即表示紧接着发生，与“很晚”不能搭配。"}, {"text": "我一进门，爸爸即很高兴。", "explanation": "这里应该用〈就〉。即表示动作紧接着发生，后面要接动作，不能接“很高兴”这样的状态；就可以接状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13365, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "即", "is_correct": true, "explanation": "即（jí）表示紧接着，是本题的目标词。"}, {"text": "挤", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是挤压。"}, {"text": "季", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是季节。"}, {"text": "基", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是基础。"}], "explanations": {"即": "即（jí）表示紧接着，是本题的目标词。", "挤": "jǐ（第三声）与 jí（第二声）声调不同，意思是挤压。", "季": "jì（第四声）与 jí（第二声）声调不同，意思是季节。", "基": "jī（第一声）与 jí（第二声）声调不同，意思是基础。"}, "sentence_index": null, "correct_answer": "即"}, "level_3": {"options": [{"text": "即", "is_correct": true, "explanation": "即：紧接着，表示老师说完后同学们马上安静下来，符合句意。"}, {"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示长久不变，与“说完就安静下来”的紧接关系不符。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续，不与表示变化的“安静下来”搭配。"}, {"text": "仍然", "is_correct": false, "explanation": "语义：“仍然”表示状态延续，与“说完后安静下来”的变化不合。"}], "explanations": {"即": "即：紧接着，表示老师说完后同学们马上安静下来，符合句意。", "永远": "语义：“永远”表示长久不变，与“说完就安静下来”的紧接关系不符。", "一直": "搭配：“一直”表示持续，不与表示变化的“安静下来”搭配。", "仍然": "语义：“仍然”表示状态延续，与“说完后安静下来”的变化不合。"}, "sentence_index": 6, "correct_answer": "即"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我还没吃完饭，即去上学了。", "explanation": "这里的“即”表示紧接着发生，前面说“还没吃完饭”，就不能紧接着去上学；应说“吃完饭就去上学了”。"}, {"text": "我明天即去上海。", "explanation": "这里应该用〈就〉。即表示紧接前面已发生的动作，“明天”没有可依托的前一动作，应说“我明天就去上海”。"}, {"text": "他一直即在图书馆学习。", "explanation": "这里的“即”表示紧接着发生，与表示持续的“一直”矛盾；应去掉“即”，说“他一直在图书馆学习”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13365, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一下课就即去食堂吃饭。", "corrected_sentence": "他一下课即去食堂吃饭。", "error_description": "重复副词：“就”和“即”都表示紧接着，不能同时用，应删去“就”，说“一下课即去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13365, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一放学，我们才即去图书馆。", "corrected_sentence": "一放学，我们即去图书馆。", "error_description": "语义冲突：“才”表示事情比预期晚发生，“即”表示紧接着发生，二者意思相反，应删去“才”，说“我们即去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
