INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13366, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13366, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把液体、气体等排放到某处。", "primary_collocate": null, "pronunciation": "pái rù", "ipa": "pʰaɪ˧˥ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "含有重金属、偶氮染料及有毒化学助剂的工业废水未经充分净化即排入河流与地下水系统，导致水体污染长期化、隐蔽化，对生物多样性及当地居民健康构成深远威胁。", "target_word": "排入", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工厂把废水排入了河里。", "target_word": "排入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂不能把脏水排入大海。", "target_word": "排入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "废气排入空气，会让人生病。", "target_word": "排入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把污水排入了城市的下水道。", "target_word": "排入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣机的水通过管子排入下水道。", "target_word": "排入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前有人把脏水排入这条小河。", "target_word": "排入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车把废气排入空气中。", "target_word": "排入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要把厨房的油排入下水道。", "target_word": "排入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水可以排入旁边的大河。", "target_word": "排入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "排入了", "label": "体标"}, {"form": "排入过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把废水、废气等液体或气体排放进某个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884de977-ec2d-4491-87db-758e8e0f7dc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13366, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "排入", "is_correct": true, "explanation": "正确：废水未经充分净化就直接排放进河流与地下水系统，“排入”正合语境。"}, {"text": "净化", "is_correct": false, "explanation": "语义：前文说废水“未经充分净化”，若接“净化河流与地下水系统”，与废水未经处理的意思矛盾。"}, {"text": "检测", "is_correct": false, "explanation": "语义：“检测”是查验水质，不会使废水进入水系统，与“即……导致水体污染”的语境不符。"}, {"text": "饮用", "is_correct": false, "explanation": "搭配：“饮用”的对象应是水或饮品，不能说“饮用河流与地下水系统”。"}], "explanations": {"排入": "正确：废水未经充分净化就直接排放进河流与地下水系统，“排入”正合语境。", "净化": "语义：前文说废水“未经充分净化”，若接“净化河流与地下水系统”，与废水未经处理的意思矛盾。", "检测": "语义：“检测”是查验水质，不会使废水进入水系统，与“即……导致水体污染”的语境不符。", "饮用": "搭配：“饮用”的对象应是水或饮品，不能说“饮用河流与地下水系统”。"}, "sentence_index": 0, "correct_answer": "排入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把硬币排入投币口里。", "explanation": "这里应该用〈投入〉。硬币投进投币口用“投入”，“排入”指排放液体、气体，不指投放硬币。"}, {"text": "我把牛奶排入杯子里。", "explanation": "这里应该用〈倒入〉。牛奶是倒进容器，“排入”只用于排放废水、废气等废弃物。"}, {"text": "请把数据排入电脑。", "explanation": "这里应该用〈输入〉。数据送入电脑用“输入”，“排入”指排出去，不能指往里送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13366, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排入", "is_correct": true, "explanation": "正确：“把脏水排入这条小河”指把脏水排放进小河，符合句意。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是观赏美景，与“把脏水”明显矛盾。"}, {"text": "净化", "is_correct": false, "explanation": "搭配：“净化”的对象应是水或空气，“把脏水净化这条小河”搭配不当。"}, {"text": "清理", "is_correct": false, "explanation": "搭配：“清理”的宾语多是河道，“把脏水清理这条小河”不符合搭配习惯。"}], "explanations": {"排入": "正确：“把脏水排入这条小河”指把脏水排放进小河，符合句意。", "欣赏": "语义：“欣赏”是观赏美景，与“把脏水”明显矛盾。", "净化": "搭配：“净化”的对象应是水或空气，“把脏水净化这条小河”搭配不当。", "清理": "搭配：“清理”的宾语多是河道，“把脏水清理这条小河”不符合搭配习惯。"}, "sentence_index": 6, "correct_answer": "排入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府向银行排入了大笔资金。", "explanation": "这里应该用〈注入〉。资金投入某处用“注入”，“排入”指排放废水、废气等废弃物。"}, {"text": "把钥匙排入口袋里。", "explanation": "这里应该用〈放入〉。钥匙是放进口袋，不是排放出去，“排入”只用于排放废弃物。"}, {"text": "请在表格里排入你的姓名。", "explanation": "这里应该用〈填入〉。在表格里写上信息用“填入”，“排入”不能用于填写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13366, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厂里的废水都把排入了河里。", "corrected_sentence": "厂里的废水都排入了河里。", "error_description": "把字句误用：“废水”已在句首作主语，“排入”前不能再加“把”，应删去“把”，说“都排入了河里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13366, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "污水从管道排入进了旁边的小河。", "corrected_sentence": "污水从管道排入了旁边的小河。", "error_description": "“排入”已含“入”的意思，后面不能再加“进”。应说“排入了旁边的小河”，不说“排入进了旁边的小河”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
