INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13367, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13367, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "埋藏在地表以下岩石或土壤空隙中的水。", "primary_collocate": null, "pronunciation": "dì xià shuǐ", "ipa": "ti˥˩ ɕja˥˩ ʂweɪ˨˩˦", "syllable_count": 3, "sentences": [{"text": "含有重金属、偶氮染料及有毒化学助剂的工业废水未经充分净化即排入河流与地下水系统，导致水体污染长期化、隐蔽化，对生物多样性及当地居民健康构成深远威胁。", "target_word": "地下水", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个村子的人都喝地下水。", "target_word": "地下水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地下水藏在土壤和岩石的空隙里。", "target_word": "地下水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂的废水会污染地下水。", "target_word": "地下水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民用水泵从井里抽地下水浇地。", "target_word": "地下水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的地下水越来越少了。", "target_word": "地下水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨水慢慢渗进土里，变成地下水。", "target_word": "地下水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家每月检查一次地下水的质量。", "target_word": "地下水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过度抽取地下水会让地面下沉。", "target_word": "地下水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山下的地下水含有很多矿物质。", "target_word": "地下水", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "地下水位", "label": "复合"}, {"form": "地下水资源", "label": "复合"}], "register": "中性", "sense_fingerprint": "地下水：埋藏在地表以下岩石或土壤空隙中的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884de977-ec2d-4491-87db-758e8e0f7dc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13367, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地下水", "is_correct": true, "explanation": "正确：与“河流”并列的是埋在地下的水体系统，应为“地下水”。"}, {"text": "地表水", "is_correct": false, "explanation": "语义：河流本身就属于地表水，“河流与地表水系统”重复，且语境指地下的水体。"}, {"text": "矿泉水", "is_correct": false, "explanation": "搭配：“矿泉水系统”不是通用说法，不能与“河流”并列构成水系统。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”不属于水体系统，“河流与空气系统”搭配不通。"}], "explanations": {"地下水": "正确：与“河流”并列的是埋在地下的水体系统，应为“地下水”。", "地表水": "语义：河流本身就属于地表水，“河流与地表水系统”重复，且语境指地下的水体。", "矿泉水": "搭配：“矿泉水系统”不是通用说法，不能与“河流”并列构成水系统。", "空气": "搭配：“空气”不属于水体系统，“河流与空气系统”搭配不通。"}, "sentence_index": 0, "correct_answer": "地下水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民挖了很深的地下水。", "explanation": "这里应该用〈井〉。挖出的是井，地下水是从井里取出的水，不能被挖。"}, {"text": "他买了一只地下水。", "explanation": "这里应该用〈桶〉。水要用桶、杯、瓶等计量，“只”用于动物，不能用于水。"}, {"text": "地下水下得很大。", "explanation": "这里应该用〈雨水〉。下得很大的是雨水，地下水埋在地下，不会从天上落下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13367, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地下水", "is_correct": true, "explanation": "正确：雨水渗入土中后变成的就是地下水，符合句意。"}, {"text": "地表水", "is_correct": false, "explanation": "语义：水渗进土里后就不在地面上了，不能说“变成地表水”。"}, {"text": "蒸汽", "is_correct": false, "explanation": "语义：雨水渗入土里不会变成蒸汽，“蒸汽”是气态，与“渗进土里”不符。"}, {"text": "湖泊", "is_correct": false, "explanation": "搭配：“湖泊”指大片积水的地方，不能说雨水渗进土里“变成湖泊”。"}], "explanations": {"地下水": "正确：雨水渗入土中后变成的就是地下水，符合句意。", "地表水": "语义：水渗进土里后就不在地面上了，不能说“变成地表水”。", "蒸汽": "语义：雨水渗入土里不会变成蒸汽，“蒸汽”是气态，与“渗进土里”不符。", "湖泊": "搭配：“湖泊”指大片积水的地方，不能说雨水渗进土里“变成湖泊”。"}, "sentence_index": 6, "correct_answer": "地下水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个地下水很潮湿。", "explanation": "这里应该用〈地下室〉。“地下水”是水，不能指房间，形容房间潮湿要用“地下室”。"}, {"text": "地下水每五分钟来一班。", "explanation": "这里应该用〈地下铁〉。班次和列车属于地下铁，“地下水”不是交通工具。"}, {"text": "地下水停满了车。", "explanation": "这里应该用〈地下停车场〉。停满车的是停车场，“地下水”不能指停车场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13367, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里有很多条地下水。", "corrected_sentence": "这里有很多地下水。", "error_description": "“地下水”是不可数的水，不能用量词“条”，应说“很多地下水”，不说“很多条地下水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13367, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "专家每月都要检查地下水们的质量。", "corrected_sentence": "专家每月都要检查地下水的质量。", "error_description": "“地下水”是不可数的水，不能加“们”表示复数，应说“地下水的质量”，不说“地下水们的质量”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
