INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13375, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向公众宣布或发表（消息、命令、文件等）。", "primary_collocate": null, "pronunciation": "fā bù", "ipa": "fa˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "公司今天发布了新的产品信息。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府发布了一份重要通知。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气象台昨天发布了大雨警报。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校已经发布了考试时间。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司每个月都会发布一次工作报告。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府发布命令，要求大家少出门。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家发布了一份关于空气质量的研究报告。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把会议通知发布到公司网站上。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们发布过很多有用的消息。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新规定发布以后，很多人都在讨论。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发布了", "label": "体标"}, {"form": "发布过", "label": "体标"}, {"form": "发布会", "label": "复合"}, {"form": "發布", "label": "繁体"}], "register": "正式", "sense_fingerprint": "正式向公众宣布消息、命令、文件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18d875c5-7ca1-4d87-b422-a099d3a3d100') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13375, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发布", "is_correct": true, "explanation": "发布指正式公开宣布消息、命令或文件，与“产品信息”搭配通顺。"}, {"text": "发明", "is_correct": false, "explanation": "语义：发明的对象是物品或技术，不说“发明产品信息”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃产品信息”。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对损坏的东西，不能修理信息。"}], "explanations": {"发布": "发布指正式公开宣布消息、命令或文件，与“产品信息”搭配通顺。", "发明": "语义：发明的对象是物品或技术，不说“发明产品信息”。", "吃": "搭配：“吃”的对象是食物，不能说“吃产品信息”。", "修理": "搭配：“修理”针对损坏的东西，不能修理信息。"}, "sentence_index": 0, "correct_answer": "发布"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在厨房里发布了一顿晚饭。", "explanation": "这里应该用〈做〉。发布用于消息、命令、文件等的公开宣布，不能用于做饭。"}, {"text": "老师在班里发布了一张奖状。", "explanation": "这里应该用〈颁发〉。奖状是授予的，要用“颁发”，“发布”用于公开宣布消息。"}, {"text": "他把水果发布给了大家。", "explanation": "这里应该用〈发放〉。“发布”指向公众宣布消息或文件，不能用来分发实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13375, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发布", "is_correct": true, "explanation": "发布指正式公开发表研究报告，与句子语境吻合。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，不能说“喝报告”。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物等具体东西，不能洗报告。"}, {"text": "调节", "is_correct": false, "explanation": "语义：“调节”用于温度、流量等，不用于报告。"}], "explanations": {"发布": "发布指正式公开发表研究报告，与句子语境吻合。", "喝": "搭配：“喝”的对象是饮品，不能说“喝报告”。", "洗": "搭配：“洗”的对象是衣物等具体东西，不能洗报告。", "调节": "语义：“调节”用于温度、流量等，不用于报告。"}, "sentence_index": 6, "correct_answer": "发布"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他私下把这个秘密发布给了我一个人。", "explanation": "这里应该用〈告诉〉。“发布”是向很多人公开，只告诉一个人要用“告诉”。"}, {"text": "太阳每天都发布温暖的光。", "explanation": "这里应该用〈发出〉。“发布”用于消息、命令、文件等，不能用于光、热等。"}, {"text": "昨天这里发布了一场大火。", "explanation": "这里应该用〈发生〉。“发布”是向公众宣布消息或文件，不能用于描述事件本身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13375, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府昨天把新的通知发布。", "corrected_sentence": "政府昨天把新的通知发布了。", "error_description": "补语缺失：“把”字句中动词“发布”后需要“了”等成分。错误形式是“把通知发布”，正确形式是“把通知发布了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13375, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上个月他们发布着新规定。", "corrected_sentence": "上个月他们发布了新规定。", "error_description": "体标错误：“着”表示进行中，不能用于已完成的上个月事件。错误形式是“发布着”，正确形式是“发布了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13376, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "昂贵", "is_correct": true, "explanation": "反义：“昂贵”与“低廉”在价格上相对。"}, {"text": "宽敞", "is_correct": false, "explanation": "无反义关系：“宽敞”说空间大，与“低廉”的价格义不相对。"}, {"text": "精致", "is_correct": false, "explanation": "无反义关系：“精致”说工艺细巧，与“低廉”没有相对的关系。"}, {"text": "灵活", "is_correct": false, "explanation": "无反义关系：“灵活”说变化自如，与“低廉”的价格义没有相对的关系。"}], "correct_answer": "昂贵", "explanations": {"昂贵": "反义：“昂贵”与“低廉”在价格上相对。", "宽敞": "无反义关系：“宽敞”说空间大，与“低廉”的价格义不相对。", "精致": "无反义关系：“精致”说工艺细巧，与“低廉”没有相对的关系。", "灵活": "无反义关系：“灵活”说变化自如，与“低廉”的价格义没有相对的关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13376, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "昂贵", "is_correct": true, "explanation": "反义：“昂贵”与“低廉”在价格上相对。"}, {"text": "辽阔", "is_correct": false, "explanation": "无反义关系：“辽阔”说面积大，与“低廉”的价格义没有相对的关系。"}, {"text": "迟缓", "is_correct": false, "explanation": "无反义关系：“迟缓”说速度慢，与“低廉”没有相对的关系。"}, {"text": "凌乱", "is_correct": false, "explanation": "无反义关系：“凌乱”说杂乱无序，与“低廉”没有相对的关系。"}], "correct_answer": "昂贵", "explanations": {"昂贵": "反义：“昂贵”与“低廉”在价格上相对。", "辽阔": "无反义关系：“辽阔”说面积大，与“低廉”的价格义没有相对的关系。", "迟缓": "无反义关系：“迟缓”说速度慢，与“低廉”没有相对的关系。", "凌乱": "无反义关系：“凌乱”说杂乱无序，与“低廉”没有相对的关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13376, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容价格很低，不贵。", "primary_collocate": null, "pronunciation": "dī lián", "ipa": "ti˥ lian˧˥", "syllable_count": 2, "sentences": [{"text": "这个小吃摊的价格低廉，学生每天都来买。", "target_word": "低廉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个商场的衣服款式多，价格低廉，年轻人很喜欢。", "target_word": "低廉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的东西质量好，价格也很低廉。", "target_word": "低廉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校附近的房租很低廉，学生都爱住那儿。", "target_word": "低廉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐火车去那里，费用比飞机低廉得多。", "target_word": "低廉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种布料成本低廉，很多工厂都用它做衣服。", "target_word": "低廉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小城的生活费用低廉，退休的人愿意搬去。", "target_word": "低廉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用低廉的价格买下了这台旧电视。", "target_word": "低廉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆菜好吃，价钱又低廉，客人很多。", "target_word": "低廉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上书的价格比书店低廉，我常在网上买书。", "target_word": "低廉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "低廉：价格、成本、费用很低", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23eec3b-6256-4fda-81a7-c349d8b21264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13376, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低廉", "is_correct": true, "explanation": "低廉：价格低，与“学生每天都来买”的原因相合。"}, {"text": "昂贵", "is_correct": false, "explanation": "语义：“昂贵”说价格高，与“学生每天都来买”的原因相反。"}, {"text": "低沉", "is_correct": false, "explanation": "搭配：“低沉”形容声音或情绪，不能修饰“价格”。"}, {"text": "精密", "is_correct": false, "explanation": "搭配：“精密”形容仪器、工艺的精确，不能用来修饰“价格”。"}], "explanations": {"低廉": "低廉：价格低，与“学生每天都来买”的原因相合。", "昂贵": "语义：“昂贵”说价格高，与“学生每天都来买”的原因相反。", "低沉": "搭配：“低沉”形容声音或情绪，不能修饰“价格”。", "精密": "搭配：“精密”形容仪器、工艺的精确，不能用来修饰“价格”。"}, "sentence_index": 0, "correct_answer": "低廉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对朋友的感情很低廉，说翻脸就翻脸。", "explanation": "这里应该用〈廉价〉。低廉只用于价格、成本等，形容感情要用廉价。"}, {"text": "他的工资很低廉，每个月只够吃饭。", "explanation": "这里应该用〈微薄〉。低廉说的是价格、费用，说收入少要用微薄。"}, {"text": "这批产品质量很低廉，用不了几天就坏了。", "explanation": "这里应该用〈低劣〉。低廉只说价格，说质量差要用低劣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13376, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低廉", "is_correct": true, "explanation": "低廉：生活费用低，与“退休的人愿意搬去”的原因相合。"}, {"text": "富裕", "is_correct": false, "explanation": "搭配：“富裕”形容人或地方的经济状况，不能修饰“生活费用”。"}, {"text": "陈旧", "is_correct": false, "explanation": "搭配：“陈旧”形容东西过时，不能用来说费用。"}, {"text": "高昂", "is_correct": false, "explanation": "语义：“高昂”说费用高，与“退休的人愿意搬去”的原因相反。"}], "explanations": {"低廉": "低廉：生活费用低，与“退休的人愿意搬去”的原因相合。", "富裕": "搭配：“富裕”形容人或地方的经济状况，不能修饰“生活费用”。", "陈旧": "搭配：“陈旧”形容东西过时，不能用来说费用。", "高昂": "语义：“高昂”说费用高，与“退休的人愿意搬去”的原因相反。"}, "sentence_index": 6, "correct_answer": "低廉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为人很低廉，从不乱许诺。", "explanation": "这里应该用〈廉洁〉。低廉只说价格、费用，形容人的品行要用廉洁。"}, {"text": "他家境很低廉，供不起孩子上学。", "explanation": "这里应该用〈清贫〉。低廉说价格，说家里经济拮据要用清贫。"}, {"text": "他过日子很低廉，从不乱花钱。", "explanation": "这里应该用〈节俭〉。低廉说价格，说生活省吃俭用要用节俭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在郊区找到一家低廉地旅馆，住了一周。", "corrected_sentence": "他在郊区找到一家低廉的旅馆，住了一周。", "error_description": "错误：“低廉”修饰名词“旅馆”时，中间应用“的”，写成“地”是错的。正确：“低廉的旅馆”。“地”用来修饰动词，不修饰名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些电脑配件的价格低廉很，学生都买得起。", "corrected_sentence": "这些电脑配件的价格低廉得很，学生都买得起。", "error_description": "错误：程度补语前漏了“得”。“低廉”后应用“得”带补语“很”，说“低廉得很”，不能说“低廉很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
