INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13381, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13381, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指能够使用较长时间、不易损坏的消费品。", "primary_collocate": null, "pronunciation": "nài yòng pǐn", "ipa": "naɪ˥˩ jʊŋ˥˩ pʰin˨˩˦", "syllable_count": 3, "sentences": [{"text": "衣物从“耐用品”异化为“一次性消费品”，大量未被穿着或仅短时间使用的服装最终被填埋或焚烧，形成巨大的资源浪费。", "target_word": "耐用品", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "冰箱和洗衣机都是家里的耐用品。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "耐用品虽然贵，但是可以用很多年。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买耐用品的时候，质量比价格更重要。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店主要卖家具这类耐用品。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视是耐用品，不用常常换。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一年只买一两件耐用品。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们收入高了，就愿意买更好的耐用品。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车算不算耐用品？", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬新家以后，我们先买了几件耐用品。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "可长期使用、不易坏的消费品，如家具、家电", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b1d809e-c850-4319-8646-b0bdde226862') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13381, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耐用品", "is_correct": true, "explanation": "“耐用品”指能长期使用的消费品，与后文“一次性消费品”形成对比，说明衣物原本是耐用的。"}, {"text": "一次性用品", "is_correct": false, "explanation": "语义：“一次性用品”与后文“一次性消费品”意思相同，“从一次性用品异化为一次性消费品”自相矛盾。"}, {"text": "食品", "is_correct": false, "explanation": "语义：衣物不可能从食品异化而来，“食品”与“衣物”不属于同类。"}, {"text": "纸巾", "is_correct": false, "explanation": "语义：“纸巾”本身就是一次性用品，不曾是耐用品，不能说“从纸巾异化为一次性消费品”。"}], "explanations": {"耐用品": "“耐用品”指能长期使用的消费品，与后文“一次性消费品”形成对比，说明衣物原本是耐用的。", "一次性用品": "语义：“一次性用品”与后文“一次性消费品”意思相同，“从一次性用品异化为一次性消费品”自相矛盾。", "食品": "语义：衣物不可能从食品异化而来，“食品”与“衣物”不属于同类。", "纸巾": "语义：“纸巾”本身就是一次性用品，不曾是耐用品，不能说“从纸巾异化为一次性消费品”。"}, "sentence_index": 0, "correct_answer": "耐用品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每个月都要买很多耐用品，比如牛奶和纸巾。", "explanation": "这里应该用〈消耗品〉。牛奶和纸巾用完就没了，属于消耗品；耐用品指能长期使用的东西。"}, {"text": "这位新来的工人是我们公司的耐用品。", "explanation": "这里误把“耐用品”用来形容人。“耐用品”指能长期使用、不易损坏的消费品，只能指物品；这里是把“耐用”的特点套到了人身上，不符合该词的用法。"}, {"text": "我们每天都要给办公室买很多耐用品，比如墨粉和打印纸。", "explanation": "这里应该用〈易耗品〉。墨粉和打印纸消耗很快，需要不断补充，属于易耗品；耐用品指能长期使用的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13381, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耐用品", "is_correct": true, "explanation": "“耐用品”是可以长期使用的物品，可以用“件”来计数，句意通顺。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以买来、用“件”计数的东西。"}, {"text": "水果", "is_correct": false, "explanation": "搭配：“件”一般不用来计数水果，应说“个”或“斤”。"}, {"text": "感情", "is_correct": false, "explanation": "语义：感情不能像商品一样买来，与“买”的意思不符。"}], "explanations": {"耐用品": "“耐用品”是可以长期使用的物品，可以用“件”来计数，句意通顺。", "空气": "语义：空气不是可以买来、用“件”计数的东西。", "水果": "搭配：“件”一般不用来计数水果，应说“个”或“斤”。", "感情": "语义：感情不能像商品一样买来，与“买”的意思不符。"}, "sentence_index": 6, "correct_answer": "耐用品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上都要去超市买耐用品，比如牙膏和洗发水。", "explanation": "这里应该用〈日用品〉。牙膏、洗发水每天都要用，用得快，需要经常买，属于日用品；“耐用品”指能长期使用、不易损坏的东西。"}, {"text": "这家超市的耐用品都是新鲜的，每天早上进货。", "explanation": "这里应该用〈食品〉。〈食品〉才会新鲜、每天进货；“耐用品”指能长期使用、不易损坏的消费品，不能用“新鲜”来形容。"}, {"text": "这些耐用品用完就扔，很方便。", "explanation": "这里应该用〈一次性用品〉。用完就扔的东西是一次性用品，与“耐用”的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13381, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本耐用品都很贵。", "corrected_sentence": "这些耐用品都很贵。", "error_description": "量词错误：“本”只用于书册等，不能计量“耐用品”，应改为“这些耐用品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13381, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买的耐用品们都很好。", "corrected_sentence": "他买的耐用品都很好。", "error_description": "词尾错误：“们”只能加在指人的名词后，“耐用品”指物品，不能加“们”，应写作“耐用品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13382, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "同化", "is_correct": true, "explanation": "反义：“同化”指使事物变得相同或相似，与“异化”指变得不同相反。"}, {"text": "河流", "is_correct": false, "explanation": "无关：“河流”是地理事物，与异化的意思没有反义关系。"}, {"text": "卡车", "is_correct": false, "explanation": "无关：“卡车”是交通工具，与异化的意思没有反义关系。"}, {"text": "花瓶", "is_correct": false, "explanation": "无关：“花瓶”是器物，与异化的意思没有反义关系。"}], "correct_answer": "同化", "explanations": {"同化": "反义：“同化”指使事物变得相同或相似，与“异化”指变得不同相反。", "河流": "无关：“河流”是地理事物，与异化的意思没有反义关系。", "卡车": "无关：“卡车”是交通工具，与异化的意思没有反义关系。", "花瓶": "无关：“花瓶”是器物，与异化的意思没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6759885b-1e84-47a8-ae4a-cb1d358da159') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13382, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "同化", "is_correct": true, "explanation": "反义：“同化”指使事物变得相同或相似，与“异化”指变得不同相反。"}, {"text": "石头", "is_correct": false, "explanation": "无关：“石头”是物体，与异化的意思没有反义关系。"}, {"text": "钢琴", "is_correct": false, "explanation": "无关：“钢琴”是乐器，与异化的意思没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "无关：“窗户”是建筑部件，与异化的意思没有反义关系。"}], "correct_answer": "同化", "explanations": {"同化": "反义：“同化”指使事物变得相同或相似，与“异化”指变得不同相反。", "石头": "无关：“石头”是物体，与异化的意思没有反义关系。", "钢琴": "无关：“钢琴”是乐器，与异化的意思没有反义关系。", "窗户": "无关：“窗户”是建筑部件，与异化的意思没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6759885b-1e84-47a8-ae4a-cb1d358da159') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13382, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物在发展过程中逐渐变得与原来不同，或者失去原本的性质。", "primary_collocate": null, "pronunciation": "yì huà", "ipa": "i˥˩ xua˥˩", "syllable_count": 2, "sentences": [{"text": "这种潜在的技术异化，迫使我们必须重新审视图灵测试之后的智能评估体系：是否应建立“自主性-责任性”双轴评价框架，以衡量代理在自由决策与社会嵌入之间的平衡能力？", "target_word": "异化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "衣物从“耐用品”异化为“一次性消费品”，大量未被穿着或仅短时间使用的服装最终被填埋或焚烧，形成巨大的资源浪费。", "target_word": "异化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "过度加班会造成人的异化。", "target_word": "异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种异化现象在城市里很常见。", "target_word": "异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机让人与人之间出现了异化。", "target_word": "异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他担心孩子会发生异化，变得冷漠。", "target_word": "异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作家在小说里写了人的异化。", "target_word": "异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作变成赚钱的工具，这就是异化。", "target_word": "异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了劳动的异化。", "target_word": "异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讨论了技术带来的异化。", "target_word": "异化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "异化现象", "label": "复合词"}, {"form": "異化", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事物发展中逐渐偏离或失去原本性质的变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '793f12b2-1a45-4e9f-b63f-7c7c045ff77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13382, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "异化", "is_correct": true, "explanation": "正确。“异化”指事物逐渐变得与原来不同，与“潜在的技术……迫使我们重新审视”的隐忧语境相符。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：“寂静”形容无声，与“技术”带来隐忧、迫使人重新审视的语境不符。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：“咖啡”是饮品，“技术咖啡”不能表示抽象的变化过程。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：“窗帘”是家居用品，不能指抽象的技术变化，与“潜在的技术……”搭配不当。"}], "explanations": {"异化": "正确。“异化”指事物逐渐变得与原来不同，与“潜在的技术……迫使我们重新审视”的隐忧语境相符。", "寂静": "语义：“寂静”形容无声，与“技术”带来隐忧、迫使人重新审视的语境不符。", "咖啡": "搭配：“咖啡”是饮品，“技术咖啡”不能表示抽象的变化过程。", "窗帘": "搭配：“窗帘”是家居用品，不能指抽象的技术变化，与“潜在的技术……”搭配不当。"}, "sentence_index": 0, "correct_answer": "异化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次改革的异化使学校成绩大幅提升。", "explanation": "这里应该用〈成效〉。“异化”指事物变得与原来不同、失去原本性质，表示改革带来的好结果要用“成效”。"}, {"text": "移民要尽快异化当地的生活。", "explanation": "这里应该用〈融入〉。“异化”指事物变得与原来不同，不能表示使自己与当地相同；移民要尽快融入当地的生活。"}, {"text": "这个社区的风貌几十年来毫无变化，却已经异化了。", "explanation": "这里应该用〈保持〉。“异化”指变得与原来不同，几十年毫无变化说明没有异化，要用“保持”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6759885b-1e84-47a8-ae4a-cb1d358da159') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13382, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "异化", "is_correct": true, "explanation": "正确。“异化”指人在社会中逐渐失去本性、变得与原来不同，是小说常写的主题。"}, {"text": "乘法", "is_correct": false, "explanation": "语义：“乘法”是数学运算，与小说里写人的抽象变化无关。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，与小说里写人的内在变化不相关。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：“海拔”指地面的高度，与写人的抽象变化不相关。"}], "explanations": {"异化": "正确。“异化”指人在社会中逐渐失去本性、变得与原来不同，是小说常写的主题。", "乘法": "语义：“乘法”是数学运算，与小说里写人的抽象变化无关。", "体重": "语义：“体重”指身体的重量，与小说里写人的内在变化不相关。", "海拔": "语义：“海拔”指地面的高度，与写人的抽象变化不相关。"}, "sentence_index": 6, "correct_answer": "异化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河经过治理，水质竟然异化得清澈见底。", "explanation": "这里应该用〈改善〉。“异化”指变得与原来不同，形容水质变好要用“改善”。"}, {"text": "这种异化的传染性很强。", "explanation": "这里应该用〈疾病〉。“异化”不表示传播或传染，说传染性要用“疾病”。"}, {"text": "这座城市的文化在快速发展中异化得越来越繁荣。", "explanation": "这里应该用〈繁荣〉。“异化”指事物变得与原来不同，形容文化兴盛要用“繁荣”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6759885b-1e84-47a8-ae4a-cb1d358da159') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13382, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种很异化的技术让人担心。", "corrected_sentence": "这种异化的技术让人担心。", "error_description": "名词“异化”前面不能加程度副词“很”；应写作“这种异化的技术”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6759885b-1e84-47a8-ae4a-cb1d358da159') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13382, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种异化了让人担心。", "corrected_sentence": "这种异化让人担心。", "error_description": "名词“异化”后面不能加“了”，应写作“这种异化让人担心”；“异化了”把它误当成了动词的完成形式。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6759885b-1e84-47a8-ae4a-cb1d358da159') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
