INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13383, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指身上穿的衣服或穿衣服的动作", "primary_collocate": null, "pronunciation": "chuān zhuó", "ipa": "tʂʰwan˥ tʂwo˧˥", "syllable_count": 2, "sentences": [{"text": "出门前，他认真检查了自己的穿着。", "target_word": "穿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的穿着很整齐，看起来很精神。", "target_word": "穿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面试的时候，你的穿着要大方得体。", "target_word": "穿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看一个人的穿着，就能猜到他的工作。", "target_word": "穿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气冷了，大家的穿着都厚了很多。", "target_word": "穿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的穿着很朴素，没有名牌衣服。", "target_word": "穿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说上课时穿着要干净，不要太随便。", "target_word": "穿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方很热，人们的穿着都很轻薄。", "target_word": "穿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对穿着不太在意，从来不买新衣服。", "target_word": "穿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从他的穿着，我看出他刚从南方来。", "target_word": "穿着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "穿着打扮", "label": "复合"}], "register": "中性", "sense_fingerprint": "穿着：身上所穿的衣服，或穿衣服这件事，即衣着打扮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b1d809e-c850-4319-8646-b0bdde226862') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13383, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穿着", "is_correct": true, "explanation": "正确。“穿着”指身上的衣着，“检查自己的穿着”语义通顺。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能用于服装，“检查自己的吃”不成立。"}, {"text": "饮用", "is_correct": false, "explanation": "搭配：“饮用”只用于饮料等液体，不能用于服装。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”指使物体着火，不能用于“检查”衣着。"}], "explanations": {"穿着": "正确。“穿着”指身上的衣着，“检查自己的穿着”语义通顺。", "吃": "搭配：“吃”不能用于服装，“检查自己的吃”不成立。", "饮用": "搭配：“饮用”只用于饮料等液体，不能用于服装。", "点燃": "语义：“点燃”指使物体着火，不能用于“检查”衣着。"}, "sentence_index": 0, "correct_answer": "穿着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间的穿着很简单，但是很温馨。", "explanation": "这里应该用〈装饰〉。“穿着”指人身上所穿的衣服，房间不能有穿着。"}, {"text": "这套房子的穿着很新，设计也很好。", "explanation": "这里应该用〈装修〉。“穿着”只用于人的衣着，不能用来形容房子。"}, {"text": "这条河的穿着很清澈，鱼也很多。", "explanation": "这里应该用〈水质〉。“穿着”指人的衣着，河水不能有穿着。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13383, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穿着", "is_correct": true, "explanation": "“穿着”指衣着打扮，“上课时穿着要干净”语义通顺。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：上课时不应该带玩具，“上课时玩具要干净”语义不合常理。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“干净”一般不用来形容午饭，与“上课时”的语境不搭配。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：上课时不应该玩游戏，“上课时游戏要干净”不成立。"}], "explanations": {"穿着": "“穿着”指衣着打扮，“上课时穿着要干净”语义通顺。", "玩具": "语义：上课时不应该带玩具，“上课时玩具要干净”语义不合常理。", "午饭": "搭配：“干净”一般不用来形容午饭，与“上课时”的语境不搭配。", "游戏": "语义：上课时不应该玩游戏，“上课时游戏要干净”不成立。"}, "sentence_index": 6, "correct_answer": "穿着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的穿着很暴躁，动不动就发火。", "explanation": "这里应该用〈脾气〉。“穿着”指身上的衣服或穿衣服，衣服不能暴躁；形容人的性情要用“脾气”。"}, {"text": "这台电脑的穿着很快，很好用。", "explanation": "这里应该用〈速度〉。“穿着”不能用来说电脑的快慢，它只指衣服或穿衣的动作。"}, {"text": "这块蛋糕的穿着很甜，大家都喜欢。", "explanation": "这里应该用〈味道〉。“穿着”只指衣服或穿衣服，不能用来形容蛋糕的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13383, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的穿着了很有品味。", "corrected_sentence": "她的穿着很有品味。", "error_description": "结构错误：“穿着”作名词时后面不能直接加“了”，“她的穿着了”不成立，应写作“她的穿着很有品味”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13383, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他今天的穿着们很正式。", "corrected_sentence": "他今天的穿着很正式。", "error_description": "词尾错误：“们”只能加在指人的名词后，“穿着”是抽象名词，不能加“们”，应写作“穿着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13384, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "长时间", "is_correct": true, "explanation": "与“短时间”互为反义，指时间长度很长的一段时期。"}, {"text": "桌子", "is_correct": false, "explanation": "与“短时间”没有反义关系，“桌子”指家具。"}, {"text": "河流", "is_correct": false, "explanation": "与“短时间”没有反义关系，“河流”指水流。"}, {"text": "钥匙", "is_correct": false, "explanation": "与“短时间”没有反义关系，“钥匙”指开锁的工具。"}], "correct_answer": "长时间", "explanations": {"长时间": "与“短时间”互为反义，指时间长度很长的一段时期。", "桌子": "与“短时间”没有反义关系，“桌子”指家具。", "河流": "与“短时间”没有反义关系，“河流”指水流。", "钥匙": "与“短时间”没有反义关系，“钥匙”指开锁的工具。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13384, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "长时间", "is_correct": true, "explanation": "与“短时间”互为反义，指时间长度很长的一段时期。"}, {"text": "花园", "is_correct": false, "explanation": "与“短时间”没有反义关系，“花园”指种花草的地方。"}, {"text": "窗户", "is_correct": false, "explanation": "与“短时间”没有反义关系，“窗户”指房屋上透光的部分。"}, {"text": "书包", "is_correct": false, "explanation": "与“短时间”没有反义关系，“书包”指装书的袋子。"}], "correct_answer": "长时间", "explanations": {"长时间": "与“短时间”互为反义，指时间长度很长的一段时期。", "花园": "与“短时间”没有反义关系，“花园”指种花草的地方。", "窗户": "与“短时间”没有反义关系，“窗户”指房屋上透光的部分。", "书包": "与“短时间”没有反义关系，“书包”指装书的袋子。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13384, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指时间长度很短的一段时期。", "primary_collocate": null, "pronunciation": "duǎn shí jiān", "ipa": "twan˨˩˦ ʂɻ̩˧˥ tɕjɛn˥", "syllable_count": 3, "sentences": [{"text": "衣物从“耐用品”异化为“一次性消费品”，大量未被穿着或仅短时间使用的服装最终被填埋或焚烧，形成巨大的资源浪费。", "target_word": "短时间", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他在短时间内学会了这首歌。", "target_word": "短时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事不可能在短时间里完成。", "target_word": "短时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "短时间的休息让我又有了力气。", "target_word": "短时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "短时间的停电不影响我们开会。", "target_word": "短时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，短时间内不要跑步。", "target_word": "短时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店短时间内就卖出了一百件衣服。", "target_word": "短时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题短时间解决不了。", "target_word": "短时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车坏了，短时间修不好。", "target_word": "短时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的伤很重，短时间内好不了。", "target_word": "短时间", "complexity_tier": "T3", "furigana": "duǎn shíjiān", "sentence_source": "generated"}], "morphological_forms": [{"form": "短时间内", "label": "复合"}], "register": "中性", "sense_fingerprint": "短时间：时间长度很短的一段时期，与长时间相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b1d809e-c850-4319-8646-b0bdde226862') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13384, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "短时间", "is_correct": true, "explanation": "与“仅”搭配，表示使用时间很短，符合“未被穿着”的语境。"}, {"text": "长时间", "is_correct": false, "explanation": "语义：“长时间”指很久，与“仅”及“大量未被穿着”的语境相矛盾。"}, {"text": "长期", "is_correct": false, "explanation": "语义：“仅长期使用”说使用很久，与“仅”限定少量使用的意思矛盾。"}, {"text": "一生", "is_correct": false, "explanation": "语义：“仅一生使用”说衣服用上一辈子，与“未被穿着”和“一次性消费品”的语境相矛盾。"}], "explanations": {"短时间": "与“仅”搭配，表示使用时间很短，符合“未被穿着”的语境。", "长时间": "语义：“长时间”指很久，与“仅”及“大量未被穿着”的语境相矛盾。", "长期": "语义：“仅长期使用”说使用很久，与“仅”限定少量使用的意思矛盾。", "一生": "语义：“仅一生使用”说衣服用上一辈子，与“未被穿着”和“一次性消费品”的语境相矛盾。"}, "sentence_index": 0, "correct_answer": "短时间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场战争的短时间持续了十年。", "explanation": "这里应该用〈长时间〉。“短时间”指时间很短，不能与“持续了十年”搭配。"}, {"text": "这条河的短时间很长。", "explanation": "这里应该用〈长度〉。“短时间”是时段名词，指一段时期，不能用来说河的长度。"}, {"text": "他是一个短时间的人。", "explanation": "这里应该用〈急性子〉。“短时间”是时段名词，不能当形容词修饰人，形容性子急要用〈急性子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13384, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "短时间", "is_correct": true, "explanation": "与“就”搭配，表示店铺在很短的时间里卖出商品，符合句意。"}, {"text": "很长时间", "is_correct": false, "explanation": "语义：“很长时间内就卖出”自相矛盾，“就”强调快速，与长时间相冲突。"}, {"text": "三十年", "is_correct": false, "explanation": "语义：“三十年内就卖出”与“就”表示很快的语义相矛盾。"}, {"text": "漫长岁月", "is_correct": false, "explanation": "语域：“漫长岁月”是书面语色彩，与这句口语化的销售描述不协调，且时间过长与“就”矛盾。"}], "explanations": {"短时间": "与“就”搭配，表示店铺在很短的时间里卖出商品，符合句意。", "很长时间": "语义：“很长时间内就卖出”自相矛盾，“就”强调快速，与长时间相冲突。", "三十年": "语义：“三十年内就卖出”与“就”表示很快的语义相矛盾。", "漫长岁月": "语域：“漫长岁月”是书面语色彩，与这句口语化的销售描述不协调，且时间过长与“就”矛盾。"}, "sentence_index": 6, "correct_answer": "短时间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议的开始时间就是短时间。", "explanation": "这里应该用〈时刻〉。“短时间”指一段很短的时期，不能指某个具体的时间点，表示开始的时刻要用〈时刻〉。"}, {"text": "这件衣服的短时间是一百元。", "explanation": "这里应该用〈价格〉。“短时间”是时段名词，不能用来表示价钱。"}, {"text": "我的墙纸短时间是蓝色的。", "explanation": "这里应该用〈颜色〉。“短时间”是时段名词，不能用来说明物体的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在一个短时间里就把作业写完了。", "corrected_sentence": "他在一段短时间里就把作业写完了。", "error_description": "“短时间”前的量词应用“段”，不能用“个”：应说“一段短时间里”，不说“一个短时间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把短时间内写完了报告。", "corrected_sentence": "我们在短时间内写完了报告。", "error_description": "“短时间”是时段名词，不能作“把”的宾语；时间状语应用“在”引出，应说“我们在短时间内写完了报告。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13385, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脱", "is_correct": true, "explanation": "与“穿”互为反义，指把衣服从身上去掉。"}, {"text": "唱", "is_correct": false, "explanation": "与“穿”没有反义关系，“唱”指发出歌声。"}, {"text": "写", "is_correct": false, "explanation": "与“穿”没有反义关系，“写”指用笔记录文字。"}, {"text": "跑", "is_correct": false, "explanation": "与“穿”没有反义关系，“跑”指快速移动。"}], "correct_answer": "脱", "explanations": {"脱": "与“穿”互为反义，指把衣服从身上去掉。", "唱": "与“穿”没有反义关系，“唱”指发出歌声。", "写": "与“穿”没有反义关系，“写”指用笔记录文字。", "跑": "与“穿”没有反义关系，“跑”指快速移动。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13385, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脱", "is_correct": true, "explanation": "与“穿”互为反义，指把衣服从身上去掉。"}, {"text": "听", "is_correct": false, "explanation": "与“穿”没有反义关系，“听”指用耳朵接收声音。"}, {"text": "走", "is_correct": false, "explanation": "与“穿”没有反义关系，“走”指移动脚步。"}, {"text": "读", "is_correct": false, "explanation": "与“穿”没有反义关系，“读”指看着文字发出声音或理解文字。"}], "correct_answer": "脱", "explanations": {"脱": "与“穿”互为反义，指把衣服从身上去掉。", "听": "与“穿”没有反义关系，“听”指用耳朵接收声音。", "走": "与“穿”没有反义关系，“走”指移动脚步。", "读": "与“穿”没有反义关系，“读”指看着文字发出声音或理解文字。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13385, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西套在身上或放在身体某个部位。", "primary_collocate": null, "pronunciation": "chuān", "ipa": "tʂʰwan˥", "syllable_count": 1, "sentences": [{"text": "天气冷了，你要多穿一件衣服。", "target_word": "穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都穿校服去上学。", "target_word": "穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢穿红色的裙子。", "target_word": "穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前请先穿上鞋子。", "target_word": "穿", "complexity_tier": "T3", "furigana": "chuān", "sentence_source": "generated"}, {"text": "外面下雪，你穿上厚外套再出门。", "target_word": "穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天我常穿短裤和凉鞋。", "target_word": "穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟还不会自己穿袜子。", "target_word": "穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动的时候最好穿舒服的鞋。", "target_word": "穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件大衣太小，我穿不进去了。", "target_word": "穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把外套穿反了，大家都笑了。", "target_word": "穿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "穿了", "label": "体标"}, {"form": "穿过", "label": "体标"}, {"form": "穿着", "label": "体标"}, {"form": "穿戴", "label": "复合"}], "register": "中性", "sense_fingerprint": "穿：把衣服、鞋袜等套在身上或脚上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 3 words above tier T1 (max 2): 我常 (Zipf 3.17), 短裤 (Zipf 3.76), 凉鞋 (Zipf 3.25)']::text[], '0b1d809e-c850-4319-8646-b0bdde226862') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13385, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "穿", "is_correct": true, "explanation": "穿：chuān（第一声），把衣服、鞋袜套在身上。"}, {"text": "船", "is_correct": false, "explanation": "chuán（第二声）与 chuān（第一声）声调不同，意思是船。"}, {"text": "窗", "is_correct": false, "explanation": "chuāng 与 chuān 韵母不同（ang 与 an），意思是窗户。"}, {"text": "床", "is_correct": false, "explanation": "chuáng 与 chuān 韵母和声调都不同，意思是床。"}, {"text": "串", "is_correct": false, "explanation": "chuàn（第四声）与 chuān（第一声）声调不同，意思是串起来。"}], "explanations": {"穿": "穿：chuān（第一声），把衣服、鞋袜套在身上。", "船": "chuán（第二声）与 chuān（第一声）声调不同，意思是船。", "窗": "chuāng 与 chuān 韵母不同（ang 与 an），意思是窗户。", "床": "chuáng 与 chuān 韵母和声调都不同，意思是床。", "串": "chuàn（第四声）与 chuān（第一声）声调不同，意思是串起来。"}, "sentence_index": null, "correct_answer": "穿"}, "level_3": {"options": [{"text": "穿", "is_correct": true, "explanation": "与“多”搭配，表示多加一件衣服御寒，符合“天气冷了”的语境。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”用于帽子、手套等，不能说“戴一件衣服”。"}, {"text": "脱", "is_correct": false, "explanation": "语义：“多脱一件衣服”与“天气冷了”的语境矛盾，应当是加衣服。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”不用于衣服，不能说“摘一件衣服”。"}], "explanations": {"穿": "与“多”搭配，表示多加一件衣服御寒，符合“天气冷了”的语境。", "戴": "搭配：“戴”用于帽子、手套等，不能说“戴一件衣服”。", "脱": "语义：“多脱一件衣服”与“天气冷了”的语境矛盾，应当是加衣服。", "摘": "搭配：“摘”不用于衣服，不能说“摘一件衣服”。"}, "sentence_index": 0, "correct_answer": "穿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "出门前请先穿上帽子。", "explanation": "这里应该用〈戴〉。帽子戴在头上，要用“戴”，不用“穿”。"}, {"text": "天冷了，她穿了一条围巾。", "explanation": "这里应该用〈围〉。围巾绕在脖子上，要用“围”，不用“穿”。"}, {"text": "他穿上了一条领带去开会。", "explanation": "这里应该用〈系〉。领带系在脖子上，要用“系”，不用“穿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13385, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "穿", "is_correct": true, "explanation": "穿：chuān（第一声），把衣服、鞋袜套在身上。"}, {"text": "喘", "is_correct": false, "explanation": "chuǎn（第三声）与 chuān（第一声）声调不同，意思是喘气。"}, {"text": "传", "is_correct": false, "explanation": "chuán（第二声）与 chuān（第一声）声调不同，意思是传递。"}, {"text": "闯", "is_correct": false, "explanation": "chuǎng 与 chuān 韵母不同（ang 与 an）且声调不同，意思是冲撞、闯入。"}], "explanations": {"穿": "穿：chuān（第一声），把衣服、鞋袜套在身上。", "喘": "chuǎn（第三声）与 chuān（第一声）声调不同，意思是喘气。", "传": "chuán（第二声）与 chuān（第一声）声调不同，意思是传递。", "闯": "chuǎng 与 chuān 韵母不同（ang 与 an）且声调不同，意思是冲撞、闯入。"}, "sentence_index": null, "correct_answer": "穿"}, "level_3": {"options": [{"text": "穿", "is_correct": true, "explanation": "与“袜子”搭配，表示把袜子套在脚上，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃袜子”不合常理，与“自己”的句意不符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱袜子”没有实际意义，与句子无法搭配。"}, {"text": "吹", "is_correct": false, "explanation": "搭配：“吹”不能与“袜子”搭配，说“吹袜子”不成立。"}], "explanations": {"穿": "与“袜子”搭配，表示把袜子套在脚上，符合句意。", "吃": "语义：“吃袜子”不合常理，与“自己”的句意不符。", "唱": "语义：“唱袜子”没有实际意义，与句子无法搭配。", "吹": "搭配：“吹”不能与“袜子”搭配，说“吹袜子”不成立。"}, "sentence_index": 6, "correct_answer": "穿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把眼镜穿上，开始读书。", "explanation": "这里应该用〈戴〉。眼镜戴在脸上，要用“戴”，不用“穿”。"}, {"text": "他把伞穿在手上，走进了教室。", "explanation": "这里应该用〈拿〉。伞是拿在手里的，不是穿在身上，要用“拿”，不用“穿”。"}, {"text": "他把手表穿在手腕上，很好看。", "explanation": "这里应该用〈戴〉。手表戴在手腕上，要用“戴”，不用“穿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13385, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他穿了着一件新大衣走进了教室。", "corrected_sentence": "他穿着一件新大衣走进了教室。", "error_description": "“穿着”表示穿戴的持续状态，“了”不能插在“穿”和“着”之间，应说“穿着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13385, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妈妈给宝宝穿了上小袜子。", "corrected_sentence": "我妈妈给宝宝穿上了小袜子。", "error_description": "“穿上”是动补结构，“了”要放在“上”之后，应说“穿上了”，不能说“穿了上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13386, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坚持", "is_correct": true, "explanation": "坚持：与“放弃”构成反义，表示不放弃、一直做下去，与“弃笔从商”的意思相反。"}, {"text": "唱", "is_correct": false, "explanation": "唱：动词，但与“弃”的任何义项都不构成反义关系。"}, {"text": "写", "is_correct": false, "explanation": "写：动词，但与“弃”的任何义项都不构成反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "吃：动词，但与“弃”的任何义项都不构成反义关系。"}], "correct_answer": "坚持", "explanations": {"坚持": "坚持：与“放弃”构成反义，表示不放弃、一直做下去，与“弃笔从商”的意思相反。", "唱": "唱：动词，但与“弃”的任何义项都不构成反义关系。", "写": "写：动词，但与“弃”的任何义项都不构成反义关系。", "吃": "吃：动词，但与“弃”的任何义项都不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5b85587-eb7c-433a-aff6-83caa2061758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
