INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13386, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "放弃，不要；扔掉。", "primary_collocate": null, "pronunciation": "qì", "ipa": "tɕʰi˥˩", "syllable_count": 1, "sentences": [{"text": "这种“即穿即弃”的文化不仅放大了生产端的环境负荷，也暴露出全球供应链在可持续性治理上的结构性缺陷。", "target_word": "弃", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这双旧鞋虽然破了，但弃之可惜，我还想再穿。", "target_word": "弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种杯子用完即弃，所以垃圾越来越多。", "target_word": "弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他弃笔从商，后来开了一家小公司。", "target_word": "弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他买了跑步机，却弃而不用，放在角落里。", "target_word": "弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友有难时，她从不弃之不顾。", "target_word": "弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他弃暗投明，向警方说出了真相。", "target_word": "弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "主人把这只流浪猫弃于路边，好心人把它抱回了家。", "target_word": "弃", "complexity_tier": "T3", "furigana": "zhǔ rén bǎ zhè zhī liú làng māo qì yú lù biān, hǎo xīn rén bǎ tā bào huí le jiā.", "sentence_source": "generated"}, {"text": "下棋时，他弃卒保车，最后赢了。", "target_word": "弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旧衣服他弃如敝屣，从来不穿第二次。", "target_word": "弃", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "棄", "label": "繁体"}, {"form": "放弃", "label": "复合"}, {"form": "丢弃", "label": "复合"}, {"form": "抛弃", "label": "复合"}], "register": "书面", "sense_fingerprint": "放弃、不要、扔掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T3: contains vocabulary far above tier T3: 屣 (Zipf 1.6)']::text[], '5f7675ad-35c8-42da-8525-b50edf4a9d77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13386, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "弃", "is_correct": true, "explanation": "弃（qì，第四声）：放弃、扔掉的意思，是本词。"}, {"text": "七", "is_correct": false, "explanation": "qī（第一声）与 qì（第四声）声调不同，意思是数字“七”。"}, {"text": "起", "is_correct": false, "explanation": "qǐ（第三声）与 qì（第四声）声调不同，意思是“起来”。"}, {"text": "其", "is_correct": false, "explanation": "qí（第二声）与 qì（第四声）声调不同，意思是“其他”或“它的”。"}, {"text": "细", "is_correct": false, "explanation": "xì 与 qì 声母不同（x 与 q），意思是细小。"}, {"text": "寄", "is_correct": false, "explanation": "jì 与 qì 声母不同（j 与 q），意思是寄送。"}], "explanations": {"弃": "弃（qì，第四声）：放弃、扔掉的意思，是本词。", "七": "qī（第一声）与 qì（第四声）声调不同，意思是数字“七”。", "起": "qǐ（第三声）与 qì（第四声）声调不同，意思是“起来”。", "其": "qí（第二声）与 qì（第四声）声调不同，意思是“其他”或“它的”。", "细": "xì 与 qì 声母不同（x 与 q），意思是细小。", "寄": "jì 与 qì 声母不同（j 与 q），意思是寄送。"}, "sentence_index": null, "correct_answer": "弃"}, "level_3": {"options": [{"text": "弃", "is_correct": true, "explanation": "弃：“即穿即弃”指穿完立即丢掉，与前文“文化”“环境负荷”的语境吻合。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“即穿即穿”重复前文的“穿”，不构成表达。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“即穿即修”不成说法，修补不针对一次性使用的衣物。"}, {"text": "留", "is_correct": false, "explanation": "语义：“即穿即留”与“放大了环境负荷”的语境相悖，留下并不会加重负担。"}], "explanations": {"弃": "弃：“即穿即弃”指穿完立即丢掉，与前文“文化”“环境负荷”的语境吻合。", "穿": "语义：“即穿即穿”重复前文的“穿”，不构成表达。", "修": "搭配：“即穿即修”不成说法，修补不针对一次性使用的衣物。", "留": "语义：“即穿即留”与“放大了环境负荷”的语境相悖，留下并不会加重负担。"}, "sentence_index": 0, "correct_answer": "弃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我弃了他的名字，一时想不起来。", "explanation": "这里应该用〈忘〉。弃表示舍去、不再要，指丢开某物；记不起名字、把事情忘掉应说“忘”。"}, {"text": "我的护照弃在了出租车上，急得不行。", "explanation": "这里应该用〈丢〉。弃表示有意舍去，护照是不慎遗失，且后文说“急得不行”，应说“丢在了出租车上”。"}, {"text": "这盘菜他弃完了，一口也没剩。", "explanation": "这是“吃完”的意思，但“弃”只表示舍去，不能用来指吃完食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5b85587-eb7c-433a-aff6-83caa2061758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13386, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "弃", "is_correct": true, "explanation": "弃（qì，第四声）：舍去、扔掉的意思，是本词。"}, {"text": "启", "is_correct": false, "explanation": "qǐ（第三声）与 qì（第四声）声调不同，意思是开启。"}, {"text": "奇", "is_correct": false, "explanation": "qí（第二声）与 qì（第四声）声调不同，意思是奇怪。"}, {"text": "戏", "is_correct": false, "explanation": "xì 与 qì 声母不同（x 与 q），意思是戏剧。"}, {"text": "记", "is_correct": false, "explanation": "jì 与 qì 声母不同（j 与 q），意思是记住。"}, {"text": "次", "is_correct": false, "explanation": "cì 与 qì 声母不同（c 与 q），意思是次数。"}], "explanations": {"弃": "弃（qì，第四声）：舍去、扔掉的意思，是本词。", "启": "qǐ（第三声）与 qì（第四声）声调不同，意思是开启。", "奇": "qí（第二声）与 qì（第四声）声调不同，意思是奇怪。", "戏": "xì 与 qì 声母不同（x 与 q），意思是戏剧。", "记": "jì 与 qì 声母不同（j 与 q），意思是记住。", "次": "cì 与 qì 声母不同（c 与 q），意思是次数。"}, "sentence_index": null, "correct_answer": "弃"}, "level_3": {"options": [{"text": "弃", "is_correct": true, "explanation": "弃：“弃暗投明”是固定说法，指舍弃黑暗、投向光明。"}, {"text": "离", "is_correct": false, "explanation": "搭配：“离暗投明”不是固定说法，固定的是“弃暗投明”。"}, {"text": "逃", "is_correct": false, "explanation": "语义：“逃”指躲开、逃跑，与“投向光明”的方向不合。"}, {"text": "躲", "is_correct": false, "explanation": "配价：“躲”不能带“暗”作宾语表示投向的对象，“躲暗投明”不成立。"}], "explanations": {"弃": "弃：“弃暗投明”是固定说法，指舍弃黑暗、投向光明。", "离": "搭配：“离暗投明”不是固定说法，固定的是“弃暗投明”。", "逃": "语义：“逃”指躲开、逃跑，与“投向光明”的方向不合。", "躲": "配价：“躲”不能带“暗”作宾语表示投向的对象，“躲暗投明”不成立。"}, "sentence_index": 6, "correct_answer": "弃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书很好看，我把它弃在书架上，每天都要看。", "explanation": "这里应该用〈放〉。弃表示舍去、扔开，只是摆放在书架上应说“放”；后文说每天都要看，也与舍去的意思矛盾。"}, {"text": "这只小狗很可爱，我一直把它弃在怀里。", "explanation": "这里应该用〈抱〉。弃表示舍去、扔开，与抱在怀里、珍爱的意思相反。"}, {"text": "这封旧信我一直弃着。", "explanation": "这里应该用〈保留〉。“弃”表示舍去，与保存、留着的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5b85587-eb7c-433a-aff6-83caa2061758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13386, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那台旧收音机被他弃了仓库角落里。", "corrected_sentence": "那台旧收音机被他弃在了仓库角落里。", "error_description": "“弃”后需接表示处所的“在”，构成“弃在……”，漏掉“在”的“弃了仓库角落里”是错误的，应为“弃在了仓库角落里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5b85587-eb7c-433a-aff6-83caa2061758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13386, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本词典虽然旧了，我也不忍之弃。", "corrected_sentence": "这本词典虽然旧了，我也不忍弃之。", "error_description": "“弃”带代词宾语“之”时，“之”应置于“弃”后，构成“弃之”；“之弃”语序错误，应为“弃之”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5b85587-eb7c-433a-aff6-83caa2061758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
