INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13388, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "负荷指的是物体或设备所承担的重量、压力或工作量，也常用来比喻人所承受的责任或压力。", "primary_collocate": null, "pronunciation": "fù hè", "ipa": "fu˥˩ xɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这种“即穿即弃”的文化不仅放大了生产端的环境负荷，也暴露出全球供应链在可持续性治理上的结构性缺陷。", "target_word": "负荷", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这台旧机器的负荷太大，经常坏。", "target_word": "负荷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桥的最大负荷是五十吨。", "target_word": "负荷", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "连续加班一个月，她心理上的负荷很大。", "target_word": "负荷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电网在夏天的负荷特别高，晚上常常停电。", "target_word": "负荷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，运动要根据心脏的负荷来安排。", "target_word": "负荷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教练根据队员的情况调整训练负荷。", "target_word": "负荷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电梯超过额定负荷就会发出警报。", "target_word": "负荷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一个人干三个人的活，负荷太重了。", "target_word": "负荷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这根绳子承受不了这么大的负荷，断了。", "target_word": "负荷", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "負荷", "label": "繁体"}, {"form": "超负荷", "label": "复合"}, {"form": "负荷量", "label": "复合"}], "register": "书面", "sense_fingerprint": "物体设备或人承担的重量、压力、工作量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7675ad-35c8-42da-8525-b50edf4a9d77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13388, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "负荷", "is_correct": true, "explanation": "正确答案。负荷指物体、设备或人所承担的重量、压力或工作量。"}, {"text": "复刻", "is_correct": false, "explanation": "fù kè（第四声）与 fù hè 声母不同（k 与 h），意思是按原样重新制作，与“承担的重量”无关。"}, {"text": "复课", "is_correct": false, "explanation": "fù kè 与 fù hè 声母不同（k 与 h），意思是恢复上课，与负荷的意思不同。"}, {"text": "复测", "is_correct": false, "explanation": "fù cè 与 fù hè 声母不同（c 与 h），意思是重新测量。"}, {"text": "复合", "is_correct": false, "explanation": "fù hé（第二声）与 fù hè（第四声）末字声调不同，意思是由几部分组合而成。"}], "explanations": {"负荷": "正确答案。负荷指物体、设备或人所承担的重量、压力或工作量。", "复刻": "fù kè（第四声）与 fù hè 声母不同（k 与 h），意思是按原样重新制作，与“承担的重量”无关。", "复课": "fù kè 与 fù hè 声母不同（k 与 h），意思是恢复上课，与负荷的意思不同。", "复测": "fù cè 与 fù hè 声母不同（c 与 h），意思是重新测量。", "复合": "fù hé（第二声）与 fù hè（第四声）末字声调不同，意思是由几部分组合而成。"}, "sentence_index": null, "correct_answer": "负荷"}, "level_3": {"options": [{"text": "负荷", "is_correct": true, "explanation": "正确。“环境负荷”指环境所承受的压力与负担，与“放大”及后句的“缺陷”语境相合。"}, {"text": "收入", "is_correct": false, "explanation": "语义：“收入”指所得的钱财，“环境收入”不成立，与“放大”的语境不合。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“放大”后接影响、问题，不说“放大环境重量”。"}, {"text": "累赘", "is_correct": false, "explanation": "语域：“累赘”口语色彩较重，与这段书面论述的语域不协调。"}], "explanations": {"负荷": "正确。“环境负荷”指环境所承受的压力与负担，与“放大”及后句的“缺陷”语境相合。", "收入": "语义：“收入”指所得的钱财，“环境收入”不成立，与“放大”的语境不合。", "重量": "搭配：“放大”后接影响、问题，不说“放大环境重量”。", "累赘": "语域：“累赘”口语色彩较重，与这段书面论述的语域不协调。"}, "sentence_index": 0, "correct_answer": "负荷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每个月的房租全靠自己负荷。", "explanation": "这里应该用〈负担〉。负荷多指机器、结构或身体承受的重量和工作量，房租等经济开支要说负担。"}, {"text": "这次聚会的负荷有三十个人。", "explanation": "这里应该用〈人数〉。负荷指所承受的重量或工作量，参加聚会的人数要说「人数」。"}, {"text": "他的负荷一年增加了两碗饭。", "explanation": "这里应该用〈饭量〉。负荷指所承受的重量或工作量，一个人吃得多要说饭量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5b85587-eb7c-433a-aff6-83caa2061758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13388, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "负荷", "is_correct": true, "explanation": "正确答案。负荷指物体、设备或人所承担的重量、压力或工作量。"}, {"text": "符合", "is_correct": false, "explanation": "fú hé 与 fù hè 两个音节的声调都不同，意思是相符、吻合。"}, {"text": "复核", "is_correct": false, "explanation": "fù hé 与 fù hè 末字声调不同（第二声与第四声），意思是再次核对。"}, {"text": "复合", "is_correct": false, "explanation": "fù hé 与 fù hè 末字声调不同（第二声与第四声），意思是由几部分组合而成。"}, {"text": "附合", "is_correct": false, "explanation": "fù hé 与 fù hè 末字声调不同，意思是依附或符合，与负荷不同。"}], "explanations": {"负荷": "正确答案。负荷指物体、设备或人所承担的重量、压力或工作量。", "符合": "fú hé 与 fù hè 两个音节的声调都不同，意思是相符、吻合。", "复核": "fù hé 与 fù hè 末字声调不同（第二声与第四声），意思是再次核对。", "复合": "fù hé 与 fù hè 末字声调不同（第二声与第四声），意思是由几部分组合而成。", "附合": "fù hé 与 fù hè 末字声调不同，意思是依附或符合，与负荷不同。"}, "sentence_index": null, "correct_answer": "负荷"}, "level_3": {"options": [{"text": "负荷", "is_correct": true, "explanation": "正确。“训练负荷”指施加给队员身体的训练强度与量，与“调整”搭配，语境相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与训练无关，“调整训练颜色”句意不通。"}, {"text": "包袱", "is_correct": false, "explanation": "搭配：“调整”的对象是强度、计划，不说调整“包袱”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”是人的性情，不能作为训练的调整对象，句意不通。"}], "explanations": {"负荷": "正确。“训练负荷”指施加给队员身体的训练强度与量，与“调整”搭配，语境相合。", "颜色": "语义：“颜色”与训练无关，“调整训练颜色”句意不通。", "包袱": "搭配：“调整”的对象是强度、计划，不说调整“包袱”。", "脾气": "语义：“脾气”是人的性情，不能作为训练的调整对象，句意不通。"}, "sentence_index": 6, "correct_answer": "负荷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "室外的负荷已经有三十度了，大家都躲在树荫下。", "explanation": "这里应该用〈温度〉。负荷指所承受的重量或工作量，天气的冷热要说温度。"}, {"text": "这辆汽车的负荷每小时跑了一百公里。", "explanation": "这里应该用〈速度〉。负荷指所承受的重量或工作量，汽车的快慢要说速度。"}, {"text": "这条路的负荷有三公里长。", "explanation": "这里应该用〈长度〉。负荷指所承受的重量或工作量，路的长短要说长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5b85587-eb7c-433a-aff6-83caa2061758') ON CONF