INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13388, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "司机说这辆卡车超过了额定地负荷。", "corrected_sentence": "司机说这辆卡车超过了额定负荷。", "error_description": "错误：“额定地负荷”；正确：“额定负荷”。“额定”是修饰“负荷”的定语，二者直接相连，中间不加“地”（“地”用于动词前作状语）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5b85587-eb7c-433a-aff6-83caa2061758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13388, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的肩上压着一只负荷。", "corrected_sentence": "他的肩上压着一份负荷。", "error_description": "错误：“一只负荷”；正确：“一份负荷”。负荷是抽象的担子，量词用“份”，“只”多用于单个的动物或物品。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5b85587-eb7c-433a-aff6-83caa2061758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
