INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13396, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把责任或事情推给别人，不肯自己承担。", "primary_collocate": null, "pronunciation": "tuī wěi", "ipa": "tʰweɪ̯˥ weɪ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "品牌方往往将环保义务推诿给远端供应商，而后者在成本压力下更倾向于牺牲环境标准以维持利润。", "target_word": "推诿", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "出了问题，经理总是推诿，不肯承认错误。", "target_word": "推诿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他遇到麻烦就推诿，从不自己解决。", "target_word": "推诿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别推诿了，这件事就是你的责任。", "target_word": "推诿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个部门互相推诿，客人等了一个小时。", "target_word": "推诿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问是谁打破了窗户，他开始推诿。", "target_word": "推诿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面对投诉，公司不但不道歉，还推诿责任。", "target_word": "推诿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他推诿着不肯签字，说这不归他管。", "target_word": "推诿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不要把工作推诿给同事，这是你的任务。", "target_word": "推诿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客服一直推诿，所以顾客很生气。", "target_word": "推诿", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "推诿了", "label": "体标"}, {"form": "推诿过", "label": "体标"}, {"form": "推诿着", "label": "体标"}, {"form": "推諉", "label": "繁体"}], "register": "书面", "sense_fingerprint": "推诿：动词，把责任推给别人，不肯承担", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63014f8-71d4-4556-8cb1-49b555969f79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13396, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "推诿", "is_correct": true, "explanation": "推诿：把责任推给别人，句中指品牌方把环保义务推给供应商。"}, {"text": "承担", "is_correct": false, "explanation": "配价：“承担”不能带“给”引出的对象，“将……承担给”不成立。"}, {"text": "赠送", "is_correct": false, "explanation": "搭配：义务不能被“赠送”，与“环保义务”搭配不当。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”是不接受，不能把义务“拒绝”给别人。"}], "explanations": {"推诿": "推诿：把责任推给别人，句中指品牌方把环保义务推给供应商。", "承担": "配价：“承担”不能带“给”引出的对象，“将……承担给”不成立。", "赠送": "搭配：义务不能被“赠送”，与“环保义务”搭配不当。", "拒绝": "语义：“拒绝”是不接受，不能把义务“拒绝”给别人。"}, "sentence_index": 0, "correct_answer": "推诿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他推诿了朋友的邀请，说自己太忙。", "explanation": "这里应该用〈推辞〉。推诿指把责任推给别人，拒绝邀请要用推辞。"}, {"text": "他用力把门推诿开了。", "explanation": "这里应该用〈推开〉。推诿只用于把责任推给别人，不能指用力推门。"}, {"text": "我推诿你读这本书。", "explanation": "这里应该用〈推荐〉。推诿指把责任推给别人，向别人介绍好书要用推荐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13396, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推诿", "is_correct": true, "explanation": "推诿：把责任推给别人，句中指公司不肯担责。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”的对象是人或成绩，不能赞美“责任”。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”是对人或帮助的感情，与“责任”无法搭配。"}, {"text": "夸大", "is_correct": false, "explanation": "搭配：“夸大”针对事实或影响，不能说“夸大责任”。"}], "explanations": {"推诿": "推诿：把责任推给别人，句中指公司不肯担责。", "赞美": "搭配：“赞美”的对象是人或成绩，不能赞美“责任”。", "感谢": "语义：“感谢”是对人或帮助的感情，与“责任”无法搭配。", "夸大": "搭配：“夸大”针对事实或影响，不能说“夸大责任”。"}, "sentence_index": 6, "correct_answer": "推诿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他正在认真推诿这首诗的用词。", "explanation": "这里应该用〈推敲〉。推诿指把责任推给别人，推敲文字要用推敲。"}, {"text": "这家店正在向顾客推诿新产品。", "explanation": "这里应该用〈推销〉。推诿指把责任推给别人，向顾客卖商品要用推销。"}, {"text": "改革正在稳步推诿。", "explanation": "这里应该用〈推进〉。推诿指把责任推给别人，事情逐步发展要用推进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他总是把责任推诿同事。", "corrected_sentence": "他总是把责任推诿给同事。", "error_description": "漏掉了“给”：推诿的对象是人时要用“给”引出，应说“推诿给同事”，不能直接说“推诿同事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13396, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把问题推诿了给别人。", "corrected_sentence": "他把问题推诿给了别人。", "error_description": "“了”的位置错误：“了”应放在“给”后面，说“推诿给了别人”，不说“推诿了给别人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
