INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13398, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指向其他企业或个人提供产品或服务的企业或个人。", "primary_collocate": null, "pronunciation": "gōng yìng shāng", "ipa": "kʊŋ˥ iŋ˥˩ ʂɑŋ˥", "syllable_count": 3, "sentences": [{"text": "品牌方往往将环保义务推诿给远端供应商，而后者在成本压力下更倾向于牺牲环境标准以维持利润。", "target_word": "供应商", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家供应商每周按时给工厂送来原材料。", "target_word": "供应商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司正在比较几家供应商的价格和质量。", "target_word": "供应商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们和这家供应商已经合作了五年。", "target_word": "供应商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "供应商没有按时交货，工厂只好停工。", "target_word": "供应商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理要求供应商提供详细的质量报告。", "target_word": "供应商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅的蔬菜供应商是附近的农场。", "target_word": "供应商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的供应商把零件送到了仓库。", "target_word": "供应商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了降低成本，他们换了一家供应商。", "target_word": "供应商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机屏幕的供应商每个月都向我们供货。", "target_word": "供应商", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "供應商", "label": "繁体"}], "register": "正式", "sense_fingerprint": "向企业或个人提供产品或服务的企业或个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63014f8-71d4-4556-8cb1-49b555969f79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13398, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "客户", "is_correct": false, "explanation": "语义：客户是购买产品的一方，不向品牌方提供产品，也不会为了维持利润牺牲环境标准。"}, {"text": "供应商", "is_correct": true, "explanation": "供应商：向企业或个人提供产品或服务的一方，句中是被品牌方推诿环保义务的远端对象。"}, {"text": "员工", "is_correct": false, "explanation": "搭配：员工属于内部人员，“推诿给远端员工”与外部合作关系不搭配。"}, {"text": "消费者", "is_correct": false, "explanation": "语义：消费者是最终购买者，不承接品牌方的环保义务，也不会因成本压力牺牲环境标准。"}], "explanations": {"客户": "语义：客户是购买产品的一方，不向品牌方提供产品，也不会为了维持利润牺牲环境标准。", "供应商": "供应商：向企业或个人提供产品或服务的一方，句中是被品牌方推诿环保义务的远端对象。", "员工": "搭配：员工属于内部人员，“推诿给远端员工”与外部合作关系不搭配。", "消费者": "语义：消费者是最终购买者，不承接品牌方的环保义务，也不会因成本压力牺牲环境标准。"}, "sentence_index": 0, "correct_answer": "供应商"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的供应商每月都向我们订货。", "explanation": "这里应该用〈客户〉。供应商是向别的企业提供货物的一方，向我们订货的是客户。"}, {"text": "工厂的供应商被存放在仓库里。", "explanation": "这里应该用〈货物〉。供应商指提供货物的企业或个人，不指被存放的东西；仓库里存放的是货物。"}, {"text": "我们有一条供应商，供货很稳定。", "explanation": "这里应该用〈家〉。供应商指企业或个人，量词用家；条用于细长的东西，不能用来数供应商。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厨师", "is_correct": false, "explanation": "语义：厨师在餐厅做菜，是餐厅的员工，不是给餐厅提供蔬菜的农场。"}, {"text": "供应商", "is_correct": true, "explanation": "供应商：向企业或个人提供产品的一方，此处指给餐厅供应蔬菜的附近农场。"}, {"text": "菜单", "is_correct": false, "explanation": "搭配：菜单是列出菜品的单子，不能作为“是附近的农场”的主语，与句意不搭配。"}, {"text": "食客", "is_correct": false, "explanation": "语义：食客是来吃饭的人，不向餐厅提供蔬菜，句中说的是提供蔬菜的一方。"}], "explanations": {"厨师": "语义：厨师在餐厅做菜，是餐厅的员工，不是给餐厅提供蔬菜的农场。", "供应商": "供应商：向企业或个人提供产品的一方，此处指给餐厅供应蔬菜的附近农场。", "菜单": "搭配：菜单是列出菜品的单子，不能作为“是附近的农场”的主语，与句意不搭配。", "食客": "语义：食客是来吃饭的人，不向餐厅提供蔬菜，句中说的是提供蔬菜的一方。"}, "sentence_index": 6, "correct_answer": "供应商"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "供应商付了款，我们就发货。", "explanation": "这里应该用〈买家〉。供应商是提供货物的一方，付款买货的是买家。"}, {"text": "员工向供应商提出了加薪的要求。", "explanation": "这里应该用〈雇主〉。加薪要求应向雇主提出，供应商与员工之间没有雇佣关系。"}, {"text": "这家饭店的供应商明天要参加高考。", "explanation": "这里应该用〈学生〉。供应商是提供货物或服务的企业或个人，明天参加高考的是学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只供应商每周都来送货，很可靠。", "corrected_sentence": "这家供应商每周都来送货，很可靠。", "error_description": "错误形式为“这只供应商”，正确形式为“这家供应商”。“供应商”指企业或个人，量词应用“家”；“只”多用于动物等，这里量词错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司刚找到了一家可靠地供应商。", "corrected_sentence": "我们公司刚找到了一家可靠的供应商。", "error_description": "错误形式为“可靠地供应商”，正确形式为“可靠的供应商”。“可靠”修饰名词“供应商”作定语，应用“的”连接；“地”用于修饰动词，这里用错。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
