INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13399, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为保护生态环境和人体健康，对污染物排放、环境质量等设定的技术规范和限值。", "primary_collocate": null, "pronunciation": "huán jìng biāo zhǔn", "ipa": "xwan˧˥ tɕiŋ˥˩ pjɑʊ˥ ʈʂwən˨˩˦", "syllable_count": 4, "sentences": [{"text": "品牌方往往将环保义务推诿给远端供应商，而后者在成本压力下更倾向于牺牲环境标准以维持利润。", "target_word": "环境标准", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个城市提高了工厂的环境标准。", "target_word": "环境标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的环境标准对污水排放有严格要求。", "target_word": "环境标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂必须符合国家的环境标准才能生产。", "target_word": "环境标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的产品达到了欧洲的环境标准。", "target_word": "环境标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国的环境标准并不完全一样。", "target_word": "环境标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环境标准越高，企业花的钱就越多。", "target_word": "环境标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在制定更严格的环境标准。", "target_word": "环境标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河边的工厂没有达到环境标准。", "target_word": "环境标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校附近的空气要符合环境标准。", "target_word": "环境标准", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "環境標準", "label": "繁体"}], "register": "正式", "sense_fingerprint": "对污染物排放、环境质量等设定的技术规范和限值", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63014f8-71d4-4556-8cb1-49b555969f79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13399, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "利润", "is_correct": false, "explanation": "语义：“牺牲利润以维持利润”自相矛盾，与句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是企业可以牺牲的规定或限值，句中指的是环境规范。"}, {"text": "环境标准", "is_correct": true, "explanation": "环境标准：为保护生态环境和人体健康设定的技术规范和限值，正是企业为维持利润而牺牲的对象。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“牺牲”常接“环境”“健康”等，“颜色”不能被牺牲来维持利润。"}], "explanations": {"利润": "语义：“牺牲利润以维持利润”自相矛盾，与句意不通。", "天气": "语义：天气不是企业可以牺牲的规定或限值，句中指的是环境规范。", "环境标准": "环境标准：为保护生态环境和人体健康设定的技术规范和限值，正是企业为维持利润而牺牲的对象。", "颜色": "搭配：“牺牲”常接“环境”“健康”等，“颜色”不能被牺牲来维持利润。"}, "sentence_index": 0, "correct_answer": "环境标准"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的环境标准是一米八，比别人高很多。", "explanation": "这里应该用〈身高〉。环境标准是污染排放和环境质量的技术规范，不能用来说人的身高。"}, {"text": "我的环境标准下班后去打篮球了。", "explanation": "这里应该用〈同事〉。环境标准是技术规范，不指人；下班后去打篮球的是人。"}, {"text": "政府发布了一台新的环境标准。", "explanation": "这里应该用〈项〉。环境标准作为规范，量词用项；台是用于机器的量词，不能数标准。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13399, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "语义：身高是人的身体尺寸，“身高越高，企业花的钱就越多”说不通。"}, {"text": "环境标准", "is_correct": true, "explanation": "环境标准：为保护环境设定的技术规范和限值，标准越严，企业花的钱就越多。"}, {"text": "鞋码", "is_correct": false, "explanation": "搭配：“越高”用于程度可以变化的指标，“鞋码”通常说“大”或“小”，不说“越高”。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是人的生理指标，与企业花钱无关，句意说的是规范的严格程度。"}], "explanations": {"身高": "语义：身高是人的身体尺寸，“身高越高，企业花的钱就越多”说不通。", "环境标准": "环境标准：为保护环境设定的技术规范和限值，标准越严，企业花的钱就越多。", "鞋码": "搭配：“越高”用于程度可以变化的指标，“鞋码”通常说“大”或“小”，不说“越高”。", "体温": "语义：体温是人的生理指标，与企业花钱无关，句意说的是规范的严格程度。"}, "sentence_index": 6, "correct_answer": "环境标准"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生要达到环境标准才能毕业。", "explanation": "这里应该用〈考试标准〉。环境标准指保护生态环境的技术规范，学生毕业要达到的是考试标准。"}, {"text": "运动员要符合环境标准。", "explanation": "这里应该用〈体重标准〉。运动员需要符合的是体重等身体条件，环境标准只用于污染排放和环境质量。"}, {"text": "政府发布了一把新的环境标准。", "explanation": "这里应该用〈项〉。环境标准的量词是项；把是用于有柄物件的量词，不能数规范。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13399, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府正在修订一双新的环境标准。", "corrected_sentence": "政府正在修订一项新的环境标准。", "error_description": "错误形式为“一双新的环境标准”，正确形式为“一项新的环境标准”。“环境标准”是规范，量词应用“项”；“双”用于成对的东西，这里量词错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13399, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂正在执行新地环境标准。", "corrected_sentence": "这家工厂正在执行新的环境标准。", "error_description": "错误形式为“新地环境标准”，正确形式为“新的环境标准”。“新”作定语修饰名词“环境标准”，应用“的”连接；“地”用于修饰动词，这里用错。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13400, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亏损", "is_correct": true, "explanation": "亏损与利润相对，指经营收入抵不上成本、亏了钱。"}, {"text": "工资", "is_correct": false, "explanation": "工资是付给劳动者的报酬，与利润没有反义关系。"}, {"text": "房租", "is_correct": false, "explanation": "房租是租房所付的钱，与利润没有反义关系。"}, {"text": "桌子", "is_correct": false, "explanation": "桌子是家具，与利润没有任何反义或近义关系。"}], "correct_answer": "亏损", "explanations": {"亏损": "亏损与利润相对，指经营收入抵不上成本、亏了钱。", "工资": "工资是付给劳动者的报酬，与利润没有反义关系。", "房租": "房租是租房所付的钱，与利润没有反义关系。", "桌子": "桌子是家具，与利润没有任何反义或近义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13400, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亏损", "is_correct": true, "explanation": "亏损与利润相对，指经营收入抵不上成本、亏了钱。"}, {"text": "手续费", "is_correct": false, "explanation": "手续费是办理业务所付的费用，与利润没有反义关系。"}, {"text": "信封", "is_correct": false, "explanation": "信封是装信的纸袋，与利润没有任何反义或近义关系。"}, {"text": "雨伞", "is_correct": false, "explanation": "雨伞是遮雨的用具，与利润没有任何反义或近义关系。"}], "correct_answer": "亏损", "explanations": {"亏损": "亏损与利润相对，指经营收入抵不上成本、亏了钱。", "手续费": "手续费是办理业务所付的费用，与利润没有反义关系。", "信封": "信封是装信的纸袋，与利润没有任何反义或近义关系。", "雨伞": "雨伞是遮雨的用具，与利润没有任何反义或近义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13400, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "利润是指企业或个人在经营活动中，收入减去成本后的剩余金额。", "primary_collocate": null, "pronunciation": "lì rùn", "ipa": "li˥˩ ʐwən˥˩", "syllable_count": 2, "sentences": [{"text": "品牌方往往将环保义务推诿给远端供应商，而后者在成本压力下更倾向于牺牲环境标准以维持利润。", "target_word": "利润", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司今年的利润比去年增加了一倍。", "target_word": "利润", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原材料涨价，企业的利润越来越少。", "target_word": "利润", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收入减去成本，剩下的就是利润。", "target_word": "利润", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店每个月的利润只有几千元。", "target_word": "利润", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把大部分利润用来研发新产品。", "target_word": "利润", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为了提高利润，减少了员工人数。", "target_word": "利润", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格战让整个行业的利润下降了。", "target_word": "利润", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年的利润超过了两千万元。", "target_word": "利润", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "利润不高，老板也不想扩大生产。", "target_word": "利润", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "净利润", "label": "复合"}, {"form": "利润率", "label": "复合"}, {"form": "利潤", "label": "繁体"}], "register": "正式", "sense_fingerprint": "经营活动中收入减去成本后的剩余金额", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63014f8-71d4-4556-8cb1-49b555969f79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13400, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "利润", "is_correct": true, "explanation": "利润指经营后剩下的钱，“以维持利润”是企业在成本压力下的目标，语义通顺。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重与企业经营无关，“以维持体重”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“维持”不搭配“颜色”，此处应是经营上的目标。"}, {"text": "学历", "is_correct": false, "explanation": "搭配：“维持学历”不符合句中企业追求的经营目标，语境也不合。"}], "explanations": {"利润": "利润指经营后剩下的钱，“以维持利润”是企业在成本压力下的目标，语义通顺。", "体重": "语义：体重与企业经营无关，“以维持体重”说不通。", "颜色": "搭配：“维持”不搭配“颜色”，此处应是经营上的目标。", "学历": "搭配：“维持学历”不符合句中企业追求的经营目标，语境也不合。"}, "sentence_index": 0, "correct_answer": "利润"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "银行每个月都给存款的人付利润。", "explanation": "这里应该用〈利息〉。存款的报酬叫利息，利润是企业经营后剩下的钱，不能付给存款人。"}, {"text": "这家公司这个月赚了一只利润。", "explanation": "这里应该用〈笔〉。利润作为一笔钱用“笔”计量，“只”多用于动物，不用于利润。"}, {"text": "政府增加了利润。", "explanation": "这里应该用〈税收〉。政府的收入来自征税，利润是企业经营的剩余，政府不能“增加利润”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13400, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "利润", "is_correct": true, "explanation": "利润是经营后的剩余，“为了提高利润”与裁减员工的语境相符，语义通顺。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的身体指标，与企业提高收益、裁员的语境不符。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“提高”不搭配“桌子”，桌子不是可以提高的对象。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：厨房不是可以“提高”的对象，此处应是经营收益。"}], "explanations": {"利润": "利润是经营后的剩余，“为了提高利润”与裁减员工的语境相符，语义通顺。", "身高": "语义：身高是人的身体指标，与企业提高收益、裁员的语境不符。", "桌子": "搭配：“提高”不搭配“桌子”，桌子不是可以提高的对象。", "厨房": "搭配：厨房不是可以“提高”的对象，此处应是经营收益。"}, "sentence_index": 6, "correct_answer": "利润"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "央行决定把利润调高了。", "explanation": "这里应该用〈利率〉。利率由央行或银行调整，利润是经营结果，不能被“调高”。"}, {"text": "老板给员工涨了利润。", "explanation": "这里应该用〈薪水〉。涨的是薪水，利润是企业经营后的剩余，不能“涨”给员工。"}, {"text": "公司因为违规被罚了利润。", "explanation": "这里应该用〈罚款〉。被罚的是款项，利润不是可以被罚的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13400, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司去年赚了一条利润。", "corrected_sentence": "这家公司去年赚了一笔利润。", "error_description": "量词错误：利润是一笔钱，应用“笔”计量。写成“条”是错误，“条”用于细长的东西，不用于钱款。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13400, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店每个月有一颗不小的利润。", "corrected_sentence": "这家店每个月有一笔不小的利润。", "error_description": "量词错误：利润应用“笔”计量。“颗”用于小而圆的东西，写成“颗”是错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
