INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13402, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "困局指难以解脱的困难境地或僵局。", "primary_collocate": null, "pronunciation": "kùn jú", "ipa": "kʰwən˥˩ tɕy˧˥", "syllable_count": 2, "sentences": [{"text": "要破解这一困局，必须从系统层面重构时尚产业的生态逻辑。", "target_word": "困局", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这家小公司陷入了资金困局。", "target_word": "困局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想走出生活的困局。", "target_word": "困局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国谈判陷入困局，没有结果。", "target_word": "困局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在找走出困局的办法。", "target_word": "困局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个困局已经持续了三年。", "target_word": "困局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济困局让很多人失去了工作。", "target_word": "困局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用新办法打破了公司的困局。", "target_word": "困局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个行业遇到了很大的困局。", "target_word": "困局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对困局，他没有放弃。", "target_word": "困局", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个困局", "label": "量词"}], "register": "书面", "sense_fingerprint": "难以摆脱的困难境地或僵局", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0f4af5-86fa-4104-a89d-57a274fcc82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13402, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "困局", "is_correct": true, "explanation": "“困局”指难以摆脱的困境，与“破解”搭配，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不是需要破解的困难处境。"}, {"text": "掌声", "is_correct": false, "explanation": "搭配：“破解”可以用于困局、谜题，不能与“掌声”搭配。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指买卖中的数额，与“困局”的困难处境不符。"}], "explanations": {"困局": "“困局”指难以摆脱的困境，与“破解”搭配，符合句意。", "天气": "语义：“天气”是自然现象，不是需要破解的困难处境。", "掌声": "搭配：“破解”可以用于困局、谜题，不能与“掌声”搭配。", "价格": "语义：“价格”指买卖中的数额，与“困局”的困难处境不符。"}, "sentence_index": 0, "correct_answer": "困局"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他吃下了那个困局。", "explanation": "这里应该用〈药〉。“吃”后接药、饭等可以吃的东西，“困局”是抽象的处境，不能吃。"}, {"text": "他用新困局解决了这个问题。", "explanation": "这里应该用〈办法〉。“用……解决问题”要用办法、工具等手段，“困局”是难以摆脱的处境，不能用来解决问题。"}, {"text": "这起困局造成了三人受伤。", "explanation": "这里应该用〈事故〉。“事故”会造成人员伤亡，“困局”是处境，不能导致人受伤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49bcd84-e272-4083-8df6-9c755c7d11bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "困局", "is_correct": true, "explanation": "“困局”指难以摆脱的困境，与“经济”搭配，指经济上的困难，符合句意。"}, {"text": "乐曲", "is_correct": false, "explanation": "语义：“乐曲”是音乐作品，与“让人失去工作”的经济含义不符。"}, {"text": "彩虹", "is_correct": false, "explanation": "语义：“彩虹”是自然景象，不能造成失业。"}, {"text": "作品", "is_correct": false, "explanation": "搭配：“经济”修饰的应是问题、危机等，“作品”不能与之搭配。"}], "explanations": {"困局": "“困局”指难以摆脱的困境，与“经济”搭配，指经济上的困难，符合句意。", "乐曲": "语义：“乐曲”是音乐作品，与“让人失去工作”的经济含义不符。", "彩虹": "语义：“彩虹”是自然景象，不能造成失业。", "作品": "搭配：“经济”修饰的应是问题、危机等，“作品”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "困局"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给朋友添了不少困局。", "explanation": "这里应该用〈麻烦〉。“麻烦”指给人带来的困扰，“困局”指难以摆脱的处境，不能说“添”。"}, {"text": "研究终于取得了困局。", "explanation": "这里应该用〈进展〉。“进展”指事情向前推进的成果，“困局”是停滞不前的处境，不能说“取得”。"}, {"text": "他按困局完成了工作。", "explanation": "这里应该用〈计划〉。“按计划”指依照安排行事，“困局”是抽象的处境，不能用来“按”行事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49bcd84-e272-4083-8df6-9c755c7d11bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司陷入了一只困局。", "corrected_sentence": "这家公司陷入了一个困局。", "error_description": "量词错误：“只”用于动物等，“困局”应用“个”。正确应为“陷入了一个困局”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49bcd84-e272-4083-8df6-9c755c7d11bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只经济困局影响了很多家庭。", "corrected_sentence": "这种经济困局影响了很多家庭。", "error_description": "量词错误：“只”用于动物等单个的东西，“困局”应用量词“种”。正确应为“这种经济困局”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49bcd84-e272-4083-8df6-9c755c7d11bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
