INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13403, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "使某事物变得公开、可见或易于理解的过程或结果。", "primary_collocate": null, "pronunciation": "tòu míng huà", "ipa": "tʰou˥˩ miŋ˧˥ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "首先，推动供应链透明化，建立可追溯的生产信息平台，使每一件纺织品的水足迹与污染排放数据可查可验，是实现问责制的基础。", "target_word": "透明化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "政府要推动预算透明化。", "target_word": "透明化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格透明化让客人更放心。", "target_word": "透明化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司信息透明化是大家的要求。", "target_word": "透明化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校想实现食堂账目的透明化。", "target_word": "透明化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "透明化能减少很多误会。", "target_word": "透明化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选举过程的透明化很重要。", "target_word": "透明化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院收费透明化，病人就不会担心。", "target_word": "透明化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们需要工作流程的透明化。", "target_word": "透明化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民希望看到管理的透明化。", "target_word": "透明化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "信息、过程变得公开可查的过程或结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0f4af5-86fa-4104-a89d-57a274fcc82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13403, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "透明化", "is_correct": true, "explanation": "名词，指使供应链信息公开可查的过程，与后文“可追溯”“可查可验”相符。"}, {"text": "污染", "is_correct": false, "explanation": "语义：“污染”是负面结果，与“是实现问责制的基础”这一目标相反，句意不通。"}, {"text": "纺织品", "is_correct": false, "explanation": "配价：“推动”后要接过程或行为，“纺织品”是产品，不能被推动。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”与供应链和问责制无关，放入空位后句子不成立。"}], "explanations": {"透明化": "名词，指使供应链信息公开可查的过程，与后文“可追溯”“可查可验”相符。", "污染": "语义：“污染”是负面结果，与“是实现问责制的基础”这一目标相反，句意不通。", "纺织品": "配价：“推动”后要接过程或行为，“纺织品”是产品，不能被推动。", "天气": "语义：“天气”与供应链和问责制无关，放入空位后句子不成立。"}, "sentence_index": 0, "correct_answer": "透明化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这只猫透明化了。", "explanation": "「透明化」指使信息、过程公开或易于理解，不能用于动物。"}, {"text": "这顿晚饭每天都透明化。", "explanation": "「透明化」用于信息、账目、过程等，不能用来说食物。"}, {"text": "窗外的大树每天都透明化。", "explanation": "「透明化」用于信息、账目、过程等，不能用于植物等自然物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49bcd84-e272-4083-8df6-9c755c7d11bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13403, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "透明化", "is_correct": true, "explanation": "名词，指选举过程向公众公开、可以监督的状态或过程，句意通顺。"}, {"text": "口味", "is_correct": false, "explanation": "语义：“口味”说的是味觉，与选举过程无关，句子无法成立。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：饮品与选举程序没有关系，放入空位后句子没有意义。"}, {"text": "餐桌", "is_correct": false, "explanation": "语义：“餐桌”是家具，与选举过程无关，放入空位后句子不成立。"}], "explanations": {"透明化": "名词，指选举过程向公众公开、可以监督的状态或过程，句意通顺。", "口味": "语义：“口味”说的是味觉，与选举过程无关，句子无法成立。", "咖啡": "语义：饮品与选举程序没有关系，放入空位后句子没有意义。", "餐桌": "语义：“餐桌”是家具，与选举过程无关，放入空位后句子不成立。"}, "sentence_index": 6, "correct_answer": "透明化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们把这盘青菜透明化了。", "explanation": "「透明化」指使信息、过程公开或易于理解，不能用于蔬菜这类实物。"}, {"text": "这只小鸟一直在透明化。", "explanation": "「透明化」不能用于动物，句子的主语是小鸟，说法不通。"}, {"text": "他把这辆自行车透明化了。", "explanation": "「透明化」不能用于交通工具这类实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49bcd84-e272-4083-8df6-9c755c7d11bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13403, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府努力推进预算很透明化。", "corrected_sentence": "政府努力推进预算透明化。", "error_description": "错误在于“很”修饰了名词性的“透明化”。“透明化”指使预算公开的过程，不能受程度副词修饰；“很透明”是形容词用法。正确说法是“推进预算透明化”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49bcd84-e272-4083-8df6-9c755c7d11bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13403, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医院收费已经实现很透明化。", "corrected_sentence": "医院收费已经实现透明化。", "error_description": "语法错误：“很”只能修饰形容词“透明”，不能修饰名词性的“透明化”。“透明化”是名词，应直接说“实现透明化”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49bcd84-e272-4083-8df6-9c755c7d11bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
