INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13404, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个能查看和验证产品生产过程信息的在线系统", "primary_collocate": null, "pronunciation": "píng tái", "ipa": "pʰiŋ˧˥ tʰai˧˥", "syllable_count": 2, "sentences": [{"text": "扫一下盒子上的码，就能进入产品信息平台。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个平台上，你可以查到牛奶是怎么生产的。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司做了一个平台，让客人看到每一步生产过程。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我登录平台，看了这袋米的生产日期。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平台上记着这批鸡蛋从农场到商店的每一步。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在平台上输入编号，马上看到了产品的来源。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个平台由政府管理，信息都是真的。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈先用手机在平台上查了这块肉的来源。", "target_word": "平台", "complexity_tier": "T3", "furigana": "píng tái", "sentence_source": "generated"}, {"text": "工厂每天把生产的数据放到平台上。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平台上查不到这个编号，说明产品可能是假的。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "网络平台", "label": "复合"}], "register": "中性", "sense_fingerprint": "可查询产品生产信息的在线系统", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53f15428-b18b-410e-8301-878efd0cd378') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13404, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平台", "is_correct": true, "explanation": "平台指可以查看产品信息的在线系统，这里说「进入产品信息」，符合语境。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是种花的地方，不能用来查产品信息，「进入产品信息花园」说不通。"}, {"text": "盒子", "is_correct": false, "explanation": "语义：盒子是装东西的容器，扫码后进入的是在线系统，不是盒子。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不是在线信息系统，「进入产品信息厨房」说不通。"}], "explanations": {"平台": "平台指可以查看产品信息的在线系统，这里说「进入产品信息」，符合语境。", "花园": "语义：花园是种花的地方，不能用来查产品信息，「进入产品信息花园」说不通。", "盒子": "语义：盒子是装东西的容器，扫码后进入的是在线系统，不是盒子。", "厨房": "语义：厨房是做饭的地方，不是在线信息系统，「进入产品信息厨房」说不通。"}, "sentence_index": 0, "correct_answer": "平台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我扫了盒子上的平台，看到了这袋米的生产日期。", "explanation": "这里应该用「码」。扫的是二维码，平台是可以登录的系统，不能用「扫」。"}, {"text": "这个平台很甜，大家都想尝一尝。", "explanation": "这里应该用「糖」或「蛋糕」。平台是查询信息的系统，没有味道；「甜」只能形容食物。"}, {"text": "我把平台折成纸飞机，飞到了超市。", "explanation": "这里应该用「纸」。平台是电子系统，不能折成纸飞机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13404, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平台", "is_correct": true, "explanation": "平台指在线的信息系统，由政府管理，信息可靠，符合句中的语境。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是用来插花的，不能由政府管理发布产品信息。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具是给孩子玩的，不是信息系统，不能说「信息都是真的」。"}, {"text": "帽子", "is_correct": false, "explanation": "语义：帽子是戴在头上的物品，不是信息系统，「由政府管理，信息都是真的」说不通。"}], "explanations": {"平台": "平台指在线的信息系统，由政府管理，信息可靠，符合句中的语境。", "花瓶": "语义：花瓶是用来插花的，不能由政府管理发布产品信息。", "玩具": "语义：玩具是给孩子玩的，不是信息系统，不能说「信息都是真的」。", "帽子": "语义：帽子是戴在头上的物品，不是信息系统，「由政府管理，信息都是真的」说不通。"}, "sentence_index": 6, "correct_answer": "平台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民在平台上养了很多鸡。", "explanation": "这里应该用「农场」。农场是养鸡的地方，平台是查询系统，不能养鸡。"}, {"text": "我用平台给猫盖了一床被子。", "explanation": "这里应该用「毯子」。平台是查询系统，不能当被子盖。"}, {"text": "我们在平台里刷了牙，然后去睡觉了。", "explanation": "这里应该用「浴室」或「洗手间」。平台不是房间，不能用来刷牙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13404, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我平台上登录，查到了这块鸡蛋的来源。", "corrected_sentence": "我在平台上登录，查到了这块鸡蛋的来源。", "error_description": "错误：「我平台上登录」，正确：「我在平台上登录」。表示在某个地方做动作时，地点前要加介词「在」，缺了「在」语句不通，本地人不会这样说。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13404, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一条平台可以查到很多产品的信息。", "corrected_sentence": "一个平台可以查到很多产品的信息。", "error_description": "错误：「一条平台」，正确：「一个平台」。平台应用量词「个」，「条」用于细长的东西，不能用来数平台。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
