INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13405, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指所有的单个个体，强调没有例外。", "primary_collocate": null, "pronunciation": "měi yí jiàn", "ipa": "mei̯˨˩˦ i˧˥ tɕjɛn˥˩", "syllable_count": 3, "sentences": [{"text": "首先，推动供应链透明化，建立可追溯的生产信息平台，使每一件纺织品的水足迹与污染排放数据可查可验，是实现问责制的基础。", "target_word": "每一件", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "当每一件廉价T恤背后都映射出干涸的河流与受污的土壤，我们不得不重新审视时尚的真正成本。", "target_word": "每一件", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家店的每一件衣服都很便宜。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我们的每一件礼物都包得很漂亮。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师检查了桌上的每一件作品。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里每一件旧家具都有一个故事。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很爱惜自己的每一件玩具。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人要仔细检查每一件产品。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家时，每一件行李都要写上名字。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里的每一件文物都很珍贵。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "每一件：逐个指称，强调无例外", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0f4af5-86fa-4104-a89d-57a274fcc82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13405, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "每一件", "is_correct": true, "explanation": "正确答案，指逐个指称的每一个事物，强调没有例外。"}, {"text": "没一件", "is_correct": false, "explanation": "没 méi（第二声）与 每 měi（第三声）声调不同，「没一件」意思是「没有一件」。"}, {"text": "每一间", "is_correct": false, "explanation": "间 jiān（第一声）与 件 jiàn（第四声）声调不同，「每一间」指每个房间。"}, {"text": "每一届", "is_correct": false, "explanation": "届 jiè 与 件 jiàn 韵母不同（少一个 n），「每一届」指每一次或每一期。"}], "explanations": {"每一件": "正确答案，指逐个指称的每一个事物，强调没有例外。", "没一件": "没 méi（第二声）与 每 měi（第三声）声调不同，「没一件」意思是「没有一件」。", "每一间": "间 jiān（第一声）与 件 jiàn（第四声）声调不同，「每一间」指每个房间。", "每一届": "届 jiè 与 件 jiàn 韵母不同（少一个 n），「每一届」指每一次或每一期。"}, "sentence_index": null, "correct_answer": "每一件"}, "level_3": {"options": [{"text": "每一件", "is_correct": true, "explanation": "代词，逐个指称纺织品，强调没有例外，与后文“每一件纺织品”相符。"}, {"text": "每一位", "is_correct": false, "explanation": "搭配：“位”用于人，不能修饰“纺织品”。"}, {"text": "每一杯", "is_correct": false, "explanation": "搭配：“杯”用于液体或容器，纺织品不能用它计量。"}, {"text": "每一辈", "is_correct": false, "explanation": "语义：“辈”指世代或辈分，与逐件说明纺织品水足迹的句意不合。"}], "explanations": {"每一件": "代词，逐个指称纺织品，强调没有例外，与后文“每一件纺织品”相符。", "每一位": "搭配：“位”用于人，不能修饰“纺织品”。", "每一杯": "搭配：“杯”用于液体或容器，纺织品不能用它计量。", "每一辈": "语义：“辈”指世代或辈分，与逐件说明纺织品水足迹的句意不合。"}, "sentence_index": 0, "correct_answer": "每一件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈给我们的每一只礼物都包得很漂亮。", "explanation": "这里应该用〈件〉。「只」用于动物或成对的物品，「礼物」要用「件」。"}, {"text": "每一件同学都来参加了聚会。", "explanation": "这里应该用〈个〉。「件」用于物品，指人要用「个」或「位」。"}, {"text": "这家农场的每一件牛都很健康。", "explanation": "这里应该用〈头〉。「头」用于牛、猪等牲畜；「件」用于物品，不能用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49bcd84-e272-4083-8df6-9c755c7d11bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13405, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每一件", "is_correct": true, "explanation": "代词，逐个指称他的玩具，强调没有例外，与“爱惜”的语境相符。"}, {"text": "每一株", "is_correct": false, "explanation": "搭配：“株”用于植物，玩具不能用它计量。"}, {"text": "每一场", "is_correct": false, "explanation": "语义：“场”指比赛或活动，句子说的是爱惜玩具，不成立。"}, {"text": "每一座", "is_correct": false, "explanation": "搭配：“座”用于山、建筑等大型物体，不用于玩具。"}], "explanations": {"每一件": "代词，逐个指称他的玩具，强调没有例外，与“爱惜”的语境相符。", "每一株": "搭配：“株”用于植物，玩具不能用它计量。", "每一场": "语义：“场”指比赛或活动，句子说的是爱惜玩具，不成立。", "每一座": "搭配：“座”用于山、建筑等大型物体，不用于玩具。"}, "sentence_index": 6, "correct_answer": "每一件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "博物馆里的每一本展品都很珍贵。", "explanation": "这里应该用〈件〉。「本」用于书籍，展品要用「件」。"}, {"text": "博物馆里的每一台文物都很珍贵。", "explanation": "这里应该用〈件〉。「台」用于机器、仪器等；文物要用「件」。"}, {"text": "博物馆里的每一株古董都很珍贵。", "explanation": "这里应该用〈件〉。「株」用于植物，古董要用「件」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49bcd84-e272-4083-8df6-9c755c7d11bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13405, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每一件衣服们都要仔细检查。", "corrected_sentence": "每一件衣服都要仔细检查。", "error_description": "错误在于“衣服”后多加了“们”。“们”只用于指人，衣服不能加“们”。应说“每一件衣服都要仔细检查”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49bcd84-e272-4083-8df6-9c755c7d11bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13405, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每一件行李要都检查。", "corrected_sentence": "每一件行李都要检查。", "error_description": "语序错误：副词“都”应放在“要”之前，说成“要都检查”不通顺。应说“每一件行李都要检查”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49bcd84-e272-4083-8df6-9c755c7d11bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
