INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13410, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指没有水分或缺乏水分。", "primary_collocate": null, "pronunciation": "wú shuǐ", "ipa": "u˧˥ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "其次，推广节水型印染技术、闭环水循环系统与无水染色工艺，能在不牺牲效率的前提下显著降低单位产出的水资源消耗。", "target_word": "无水", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "做这个实验要用无水的乙醇，否则结果不准。", "target_word": "无水", "complexity_tier": "T3", "furigana": "zuò zhè ge shí yàn yào yòng wú shuǐ de yǐ chún fǒu zé jié guǒ bù zhǔn", "sentence_source": "generated"}, {"text": "这种药粉开封后必须保持无水，否则会结块。", "target_word": "无水", "complexity_tier": "T3", "furigana": "zhè zhǒng yào fěn kāi fēng hòu bì xū bǎo chí wú shuǐ fǒu zé huì jié kuài", "sentence_source": "generated"}, {"text": "硫酸铜变成白色粉末，说明已经是无水的了。", "target_word": "无水", "complexity_tier": "T3", "furigana": "liú suān tóng biàn chéng bái sè fěn mò shuō míng yǐ jīng shì wú shuǐ de le", "sentence_source": "generated"}, {"text": "催化剂使用前必须是无水的，否则效果会下降。", "target_word": "无水", "complexity_tier": "T3", "furigana": "cuī huà jì shǐ yòng qián bì xū shì wú shuǐ de fǒu zé xiào guǒ huì xià jiàng", "sentence_source": "generated"}, {"text": "老师说，用无水的氯化钙可以吸收空气中的水分。", "target_word": "无水", "complexity_tier": "T3", "furigana": "lǎo shī shuō yòng wú shuǐ de lǜ huà gài kě yǐ xī shōu kōng qì zhōng de shuǐ fèn", "sentence_source": "generated"}, {"text": "实验前要保证瓶子是无水的。", "target_word": "无水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种粉末保持无水，才能放很久。", "target_word": "无水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过脱水处理，这种晶体就变成了无水的。", "target_word": "无水", "complexity_tier": "T3", "furigana": "jīng guò tuō shuǐ chǔ lǐ zhè zhǒng jīng tǐ jiù biàn chéng le wú shuǐ de", "sentence_source": "generated"}, {"text": "他把样品放进干燥器，等到无水后再称重。", "target_word": "无水", "complexity_tier": "T3", "furigana": "tā bǎ yàng pǐn fàng jìn gān zào qì děng dào wú shuǐ hòu zài chēng zhòng", "sentence_source": "generated"}], "morphological_forms": [{"form": "无水乙醇", "label": "复合"}], "register": "中性", "sense_fingerprint": "不含水分、干燥的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e6b670f-7507-4a9d-adc5-f33d2a882a9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13410, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无水", "is_correct": true, "explanation": "正确：wú shuǐ，意思是没有水分。"}, {"text": "污水", "is_correct": false, "explanation": "wū（第一声）与 wú（第二声）声调不同，意思是污水。"}, {"text": "雾水", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是雾水。"}, {"text": "无税", "is_correct": false, "explanation": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是无税。"}], "explanations": {"无水": "正确：wú shuǐ，意思是没有水分。", "污水": "wū（第一声）与 wú（第二声）声调不同，意思是污水。", "雾水": "wù（第四声）与 wú（第二声）声调不同，意思是雾水。", "无税": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是无税。"}, "sentence_index": null, "correct_answer": "无水"}, "level_3": {"options": [{"text": "无水", "is_correct": true, "explanation": "正确：无水指不含水分，与“节水型”“闭环水循环”和“降低水资源消耗”的语境相符。"}, {"text": "高耗水", "is_correct": false, "explanation": "语义：“高耗水”与“节水型”“降低水资源消耗”直接矛盾。"}, {"text": "粗放", "is_correct": false, "explanation": "语义：“粗放”指浪费资源，与“节水”和“降低消耗”的目标相反。"}, {"text": "有毒", "is_correct": false, "explanation": "搭配：“工艺”多与“先进”“环保”等词搭配，“有毒”不宜直接修饰工艺，搭配不当。"}], "explanations": {"无水": "正确：无水指不含水分，与“节水型”“闭环水循环”和“降低水资源消耗”的语境相符。", "高耗水": "语义：“高耗水”与“节水型”“降低水资源消耗”直接矛盾。", "粗放": "语义：“粗放”指浪费资源，与“节水”和“降低消耗”的目标相反。", "有毒": "搭配：“工艺”多与“先进”“环保”等词搭配，“有毒”不宜直接修饰工艺，搭配不当。"}, "sentence_index": 0, "correct_answer": "无水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个西瓜很甜，咬开后果肉却很无水。", "explanation": "这里应该用〈多汁〉。西瓜果肉含水很多，“无水”指完全不含水分，说果肉无水与西瓜的特点矛盾；形容水分多要说多汁。"}, {"text": "这批果汁经过加热后已经无水了。", "explanation": "这里应该用〈浓缩〉。“无水”指物质完全不含水分，果汁是溶液，蒸发后应说“浓缩”，不能说无水。"}, {"text": "他的头脑很无水，反应总是慢半拍。", "explanation": "这里应该用〈迟钝〉。“无水”指物质完全不含水分，不能用来形容头脑；形容反应慢要说迟钝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13410, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无水", "is_correct": true, "explanation": "正确：无水的瓶子才能保证实验条件，“是…的”结构成立。"}, {"text": "湿", "is_correct": false, "explanation": "语义：湿的瓶子会影响实验，与“保证”的要求相反。"}, {"text": "脏", "is_correct": false, "explanation": "语义：脏的瓶子会污染实验，与“保证”的要求矛盾。"}, {"text": "易碎", "is_correct": false, "explanation": "搭配：“保证”的宾语应是状态，“易碎”是性质，不能与“保证瓶子是…”搭配。"}], "explanations": {"无水": "正确：无水的瓶子才能保证实验条件，“是…的”结构成立。", "湿": "语义：湿的瓶子会影响实验，与“保证”的要求相反。", "脏": "语义：脏的瓶子会污染实验，与“保证”的要求矛盾。", "易碎": "搭配：“保证”的宾语应是状态，“易碎”是性质，不能与“保证瓶子是…”搭配。"}, "sentence_index": 6, "correct_answer": "无水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "刚从河里捞上来的鱼，已经很无水了。", "explanation": "这里应该用〈湿漉漉〉。“无水”指完全不含水分，刚捞上来的鱼含水很多，说无水与之矛盾；形容带水的状态要说湿漉漉。"}, {"text": "这瓶矿泉水无水，可以直接喝。", "explanation": "这里应该用〈纯净〉。“无水”指完全不含水分，矿泉水本身就是水，说无水与其含义矛盾；应说纯净或干净。"}, {"text": "这块湿毛巾已经无水了，可以用了。", "explanation": "这里应该用〈干透〉。“无水”指完全不含水分，湿毛巾含有水分，应说干透，不能用无水描述湿物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13410, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批试剂必须是无水地，才能用于实验。", "corrected_sentence": "这批试剂必须是无水的，才能用于实验。", "error_description": "结构助词错误：错误形式为“是无水地”，正确形式为“是无水的”。“是…的”结构中修饰成分要用“的”，“地”用于修饰动词，不能用于这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13410, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "样品已经无水过了，可以称重了。", "corrected_sentence": "样品已经无水了，可以称重了。", "error_description": "动态助词错误：错误形式为“无水过了”，正确形式为“无水了”。“无水”是形容词，表示状态，不能加“过”表示经历。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
