INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13414, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "纤维是细而长的丝状物质，是构成纺织品的基本材料。", "primary_collocate": null, "pronunciation": "xiān wéi", "ipa": "ɕjɛn˥ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "纺织品的生产，尤其是棉质与合成纤维的加工，本质上是一个极度依赖水资源的工业流程。", "target_word": "纤维", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "同时，发展生物可降解纤维、提升废旧纺织品回收再利用技术，亦是缓解资源压力的重要路径。", "target_word": "纤维", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "棉花里有很多细长的纤维。", "target_word": "纤维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种布是用化学纤维做的。", "target_word": "纤维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人把纤维纺成细线。", "target_word": "纤维", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "蚕丝是一种天然纤维。", "target_word": "纤维", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "合成纤维的衣服干得很快。", "target_word": "纤维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "麻的纤维很长，也很结实。", "target_word": "纤维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂每天加工几吨纤维。", "target_word": "纤维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "显微镜下可以看到一根纤维，又细又长。", "target_word": "纤维", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "合成纤维", "label": "复合"}, {"form": "纤维素", "label": "复合"}, {"form": "纖維", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "构成纺织品的细长丝状基本材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e6b670f-7507-4a9d-adc5-f33d2a882a9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13414, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "纤维", "is_correct": true, "explanation": "纤维：细长的丝状物质，读音 xiān wéi 与听到的音一致，是正确答案。"}, {"text": "咸味", "is_correct": false, "explanation": "xián wèi（咸味）与 xiān wéi 两个音节的声调都不同，意思是咸的味道。"}, {"text": "显微", "is_correct": false, "explanation": "xiǎn wēi（显微）与 xiān wéi 两个音节的声调都不同，意思是极小、需显微镜才能看清。"}, {"text": "县委", "is_correct": false, "explanation": "xiàn wěi（县委）与 xiān wéi 两个音节的声调都不同，意思是县一级的党委。"}], "explanations": {"纤维": "纤维：细长的丝状物质，读音 xiān wéi 与听到的音一致，是正确答案。", "咸味": "xián wèi（咸味）与 xiān wéi 两个音节的声调都不同，意思是咸的味道。", "显微": "xiǎn wēi（显微）与 xiān wéi 两个音节的声调都不同，意思是极小、需显微镜才能看清。", "县委": "xiàn wěi（县委）与 xiān wéi 两个音节的声调都不同，意思是县一级的党委。"}, "sentence_index": null, "correct_answer": "纤维"}, "level_3": {"options": [{"text": "纤维", "is_correct": true, "explanation": "纤维：与“棉质”并列，是合成的纺织原料，符合句意。"}, {"text": "水泥", "is_correct": false, "explanation": "语义：水泥不是纺织品，与“棉质”“纺织品”的语境不符。"}, {"text": "线头", "is_correct": false, "explanation": "搭配：“线头”指线的末端，不能作为“合成……的加工”的原料。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶是植物器官，不是纺织工业的原料。"}], "explanations": {"纤维": "纤维：与“棉质”并列，是合成的纺织原料，符合句意。", "水泥": "语义：水泥不是纺织品，与“棉质”“纺织品”的语境不符。", "线头": "搭配：“线头”指线的末端，不能作为“合成……的加工”的原料。", "树叶": "语义：树叶是植物器官，不是纺织工业的原料。"}, "sentence_index": 0, "correct_answer": "纤维"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一根纤维，回家做了件衬衫。", "explanation": "这里应该用〈布料〉。纤维是构成纺织品的细丝状原料，单根纤维做不成衬衫，应说布料。"}, {"text": "他用一根纤维夹菜。", "explanation": "这里应该用〈筷子〉。纤维是细丝状的原料，不能用来夹菜，应说筷子。"}, {"text": "他把粗纤维系在车上。", "explanation": "这里应该用〈绳子〉。纤维是细丝状的原料，不是做好的绳子，不能直接拿来系车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13414, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "纤维", "is_correct": true, "explanation": "纤维：细长的丝状物质，读音 xiān wéi 与听到的音一致，是正确答案。"}, {"text": "鲜味", "is_correct": false, "explanation": "xiān wèi（鲜味）与 xiān wéi 只有第二音节声调不同（第四声与第二声），意思是鲜美的味道。"}, {"text": "现为", "is_correct": false, "explanation": "xiàn wéi（现为）与 xiān wéi 只有第一音节声调不同（第四声与第一声），意思是“现在是”。"}, {"text": "相违", "is_correct": false, "explanation": "xiāng wéi（相违）与 xiān wéi 的韵尾不同（ng 与 n），意思是相违背。"}], "explanations": {"纤维": "纤维：细长的丝状物质，读音 xiān wéi 与听到的音一致，是正确答案。", "鲜味": "xiān wèi（鲜味）与 xiān wéi 只有第二音节声调不同（第四声与第二声），意思是鲜美的味道。", "现为": "xiàn wéi（现为）与 xiān wéi 只有第一音节声调不同（第四声与第一声），意思是“现在是”。", "相违": "xiāng wéi（相违）与 xiān wéi 的韵尾不同（ng 与 n），意思是相违背。"}, "sentence_index": null, "correct_answer": "纤维"}, "level_3": {"options": [{"text": "纤维", "is_correct": true, "explanation": "纤维：与“合成”搭配，是做衣服的原料，符合句意。"}, {"text": "棉花", "is_correct": false, "explanation": "搭配：“合成”一般不修饰天然的棉花，“合成棉花的衣服”不能这样说。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是纺织材料，与“衣服”“干得很快”的语境不合。"}, {"text": "粉笔", "is_correct": false, "explanation": "语义：粉笔是书写用品，不能用来做衣服，与句意矛盾。"}], "explanations": {"纤维": "纤维：与“合成”搭配，是做衣服的原料，符合句意。", "棉花": "搭配：“合成”一般不修饰天然的棉花，“合成棉花的衣服”不能这样说。", "石头": "语义：石头不是纺织材料，与“衣服”“干得很快”的语境不合。", "粉笔": "语义：粉笔是书写用品，不能用来做衣服，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "纤维"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "显微镜下可以看到一滴纤维，又细又长。", "explanation": "这里应该用〈根〉。滴用于液体，纤维是固体细丝，不能说一滴纤维。"}, {"text": "显微镜下可以看到一粒纤维，又细又长。", "explanation": "这里应该用〈根〉。粒用于颗粒状的东西，不用于细长的纤维。"}, {"text": "显微镜下可以看到一张纤维，又细又长。", "explanation": "这里应该用〈根〉。张用于纸、桌子等扁平的东西，不用于细丝状的纤维。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在地上捡起了一个纤维。", "corrected_sentence": "我在地上捡起了一根纤维。", "error_description": "错误形式：一个纤维；正确形式：一根纤维。“纤维”是细长的丝状物，量词应用“根”，“个”是通用量词，不能用于这类细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把纤维拉了断。", "corrected_sentence": "工人把纤维拉断了。", "error_description": "错误形式：拉了断；正确形式：拉断了。结果补语“断”应紧跟动词“拉”，“了”放在补语之后，不能插在动词和补语之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
