INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13417, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不使用某种事物，尤其指过程中完全不需要水", "primary_collocate": null, "pronunciation": "wú", "ipa": "u˧˥", "syllable_count": 1, "sentences": [{"text": "这种洗衣机采用无水清洗技术，衣物不易损伤。", "target_word": "无", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "这种洗车方法无水，沙漠里也能用。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位厨师做菜时无水，只用蔬菜自己的汁。", "target_word": "无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种厕所无水也能用，干旱地区很需要。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种无水清洁剂喷在表面上，用纸巾一擦就干净。", "target_word": "无", "complexity_tier": "T3", "furigana": "zhè zhǒng wú shuǐ qīng jié jì pēn zài biǎo miàn shang, yòng zhǐ jīn yí cā jiù gān jìng.", "sentence_source": "generated"}, {"text": "这套设备无水运行，不怕沙漠里缺水。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种无水染色工艺已经用于生产高档面料。", "target_word": "无", "complexity_tier": "T3", "furigana": "zhè zhǒng wú shuǐ rǎn sè gōng yì yǐ jīng yòng yú shēng chǎn gāo dàng miàn liào.", "sentence_source": "generated"}, {"text": "营地缺水，我们只好使用无水洗手液。", "target_word": "无", "complexity_tier": "T3", "furigana": "yíng dì quē shuǐ, wǒ men zhǐ hǎo shǐ yòng wú shuǐ xǐ shǒu yè.", "sentence_source": "generated"}, {"text": "工厂改用无水印染后，不再排放污水。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店提供无水洗车，很受沙漠附近居民欢迎。", "target_word": "无", "complexity_tier": "T3", "furigana": "zhè jiā diàn tí gōng wú shuǐ xǐ chē, hěn shòu shā mò fù jìn jū mín huān yíng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "無", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "无：不用某物，尤指过程中完全不用水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: 3 words above tier T1 (max 2): 做菜 (Zipf 3.17), 只用 (Zipf 3.86), 汁 (Zipf 3.74)','sentence 6 above tier T1: 3 words above tier T1 (max 2): 染色 (Zipf 3.58), 高档 (Zipf 3.94), 面料 (Zipf 3.51)','sentence 7 above tier T1: 3 words above tier T1 (max 2): 缺水 (Zipf 3.44), 洗手 (Zipf 3.63), 液 (Zipf 3.9)','sentence 8 above tier T1: 3 words above tier T1 (max 2): 改用 (Zipf 3.83), 水印 (Zipf 3.34), 染 (Zipf 3.91)']::text[], '7728ca8c-cc31-47be-a40d-da0fcf2ae697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13417, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无", "is_correct": true, "explanation": "无 wú，意思是不用某种东西，尤指过程中完全不需要水。"}, {"text": "五", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是数字五。"}, {"text": "午", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是中午。"}, {"text": "舞", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是跳舞。"}, {"text": "物", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是东西、事物。"}, {"text": "雾", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是雾气。"}], "explanations": {"无": "无 wú，意思是不用某种东西，尤指过程中完全不需要水。", "五": "wǔ（第三声）与 wú（第二声）声调不同，意思是数字五。", "午": "wǔ（第三声）与 wú（第二声）声调不同，意思是中午。", "舞": "wǔ（第三声）与 wú（第二声）声调不同，意思是跳舞。", "物": "wù（第四声）与 wú（第二声）声调不同，意思是东西、事物。", "雾": "wù（第四声）与 wú（第二声）声调不同，意思是雾气。"}, "sentence_index": null, "correct_answer": "无"}, "level_3": {"options": [{"text": "无", "is_correct": true, "explanation": "无：“无水清洗技术”表示不用水的清洗方式，修饰“技术”，句意通顺。"}, {"text": "停", "is_correct": false, "explanation": "语义：“停水”指供水中断，不能修饰“清洗技术”，句意不通。"}, {"text": "漏", "is_correct": false, "explanation": "语义：“漏水”指水从缝隙渗出，不是清洗技术的特点，句意不通。"}, {"text": "断", "is_correct": false, "explanation": "搭配：“断”单独不能修饰“清洗技术”，句意不通。"}], "explanations": {"无": "无：“无水清洗技术”表示不用水的清洗方式，修饰“技术”，句意通顺。", "停": "语义：“停水”指供水中断，不能修饰“清洗技术”，句意不通。", "漏": "语义：“漏水”指水从缝隙渗出，不是清洗技术的特点，句意不通。", "断": "搭配：“断”单独不能修饰“清洗技术”，句意不通。"}, "sentence_index": 0, "correct_answer": "无"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座小村无路，车子开不进去。", "explanation": "这里的“无”表示“没有”（路），不是“不使用某种东西”。本词要表达的是过程中不需要水，此句用法不符。"}, {"text": "这张桌子无腿，站不稳。", "explanation": "这里的“无”表示“没有”（腿），与本词“不使用某种东西”的意思不同。"}, {"text": "这块地无树，夏天很热。", "explanation": "这里的“无”表示“没有”（树），与本词“不使用某种东西”的意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13417, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "无", "is_correct": true, "explanation": "无 wú，意思是不用某种东西，尤指过程中完全不需要水。"}, {"text": "武", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是武术、武力。"}, {"text": "误", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是错误、耽误。"}, {"text": "屋", "is_correct": false, "explanation": "wū（第一声）与 wú（第二声）声调不同，意思是房屋。"}, {"text": "乌", "is_correct": false, "explanation": "wū（第一声）与 wú（第二声）声调不同，意思是乌鸦、黑色。"}, {"text": "务", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是事务、务必。"}], "explanations": {"无": "无 wú，意思是不用某种东西，尤指过程中完全不需要水。", "武": "wǔ（第三声）与 wú（第二声）声调不同，意思是武术、武力。", "误": "wù（第四声）与 wú（第二声）声调不同，意思是错误、耽误。", "屋": "wū（第一声）与 wú（第二声）声调不同，意思是房屋。", "乌": "wū（第一声）与 wú（第二声）声调不同，意思是乌鸦、黑色。", "务": "wù（第四声）与 wú（第二声）声调不同，意思是事务、务必。"}, "sentence_index": null, "correct_answer": "无"}, "level_3": {"options": [{"text": "无", "is_correct": true, "explanation": "无：“无水”表示不用水，修饰“染色工艺”，句意通顺。"}, {"text": "泼", "is_correct": false, "explanation": "搭配：“泼水”是倾倒水的动作，不能直接修饰“染色工艺”，句意不通。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧水”是加热水的动作，不能作“染色工艺”的定语。"}, {"text": "撒", "is_correct": false, "explanation": "搭配：“撒水”是洒水的动作，不能直接修饰“染色工艺”，句意不通。"}], "explanations": {"无": "无：“无水”表示不用水，修饰“染色工艺”，句意通顺。", "泼": "搭配：“泼水”是倾倒水的动作，不能直接修饰“染色工艺”，句意不通。", "烧": "搭配：“烧水”是加热水的动作，不能作“染色工艺”的定语。", "撒": "搭配：“撒水”是洒水的动作，不能直接修饰“染色工艺”，句意不通。"}, "sentence_index": 6, "correct_answer": "无"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间教室无黑板，老师只能用嘴讲。", "explanation": "这里的“无”表示“没有”（黑板），不是“不使用某种东西”。本词要表达的是不需要水，此句用法不符。"}, {"text": "他家无沙发，客人只能站着。", "explanation": "这里的“无”表示“没有”（沙发），与本词“不使用某种东西”的意思不同。"}, {"text": "这片草地无花，颜色很单调。", "explanation": "这里的“无”表示“没有”（花），与本词“不使用某种东西”的意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13417, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器水无也能运行，很省事。", "corrected_sentence": "这台机器无水也能运行，很省事。", "error_description": "“无”与“水”语序颠倒。应说“无水”（不用水），“水无”不成词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13417, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家洗车店一直无了水洗车，客人很满意。", "corrected_sentence": "这家洗车店一直无水洗车，客人很满意。", "error_description": "“无”后面不能加“了”。“无”是动词，不带“了”表示完成；应说“一直无水洗车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
