INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13418, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人们对消费行为持有的态度、看法和习惯的总和。", "primary_collocate": null, "pronunciation": "xiāo fèi guān niàn", "ipa": "ɕiɑʊ˥ feɪ˥˩ kuan˥ njɛn˥˩", "syllable_count": 4, "sentences": [{"text": "然而，技术革新若无消费观念的同步转变，终将举步维艰。", "target_word": "消费观念", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "年轻人的消费观念和父母很不一样。", "target_word": "消费观念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的消费观念很简单：不需要的东西不买。", "target_word": "消费观念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的消费观念能让人不乱花钱。", "target_word": "消费观念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的消费观念是从家里学来的。", "target_word": "消费观念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在很多人的消费观念变了。", "target_word": "消费观念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "广告会影响人们的消费观念。", "target_word": "消费观念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "父母应该帮孩子树立正确的消费观念。", "target_word": "消费观念", "complexity_tier": "T3", "furigana": "fù mǔ yīng gāi bāng hái zi shù lì zhèng què de xiāo fèi guān niàn。", "sentence_source": "generated"}, {"text": "他有健康的消费观念，从不借钱买东西。", "target_word": "消费观念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不同国家的人，消费观念也不同。", "target_word": "消费观念", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "消費觀念", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人们对消费所持的态度、看法和习惯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f3ad525-ec43-4f5b-948b-9899e9b8bc3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13418, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“天气”与人们的消费态度无关，不能说“天气的同步转变”"}, {"text": "消费观念", "is_correct": true, "explanation": "“消费观念”指人们对消费的态度和看法，与“同步转变”相符"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与这句书面语的语体不协调"}, {"text": "八卦", "is_correct": false, "explanation": "语义：“八卦”指闲言碎语，不能与消费态度同步转变"}], "explanations": {"天气": "语义：“天气”与人们的消费态度无关，不能说“天气的同步转变”", "消费观念": "“消费观念”指人们对消费的态度和看法，与“同步转变”相符", "玩意儿": "语域：“玩意儿”是口语说法，与这句书面语的语体不协调", "八卦": "语义：“八卦”指闲言碎语，不能与消费态度同步转变"}, "sentence_index": 0, "correct_answer": "消费观念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的消费观念比上个月增加了三千元。", "explanation": "这里应该用〈消费金额〉。观念指看法，花费的数额要用〈消费金额〉"}, {"text": "这个城市的消费观念比其他地区高很多。", "explanation": "这里应该用〈消费水平〉。观念是看法，不能用“高”来比较，花钱多少要用〈消费水平〉"}, {"text": "他有一只健康的消费观念。", "explanation": "量词错误：消费观念应搭配〈种〉，〈只〉多用于动物或成对事物中的一个。这里应该用〈种〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13418, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "语义：广告不能影响身高，句子语义不通"}, {"text": "嗓音", "is_correct": false, "explanation": "语义：广告与嗓音无关，句子语义不通"}, {"text": "货色", "is_correct": false, "explanation": "语域：“货色”是口语且带贬义，与这句客观的陈述语体不协调"}, {"text": "消费观念", "is_correct": true, "explanation": "“消费观念”指人们对消费的看法，广告可以影响它"}], "explanations": {"身高": "语义：广告不能影响身高，句子语义不通", "嗓音": "语义：广告与嗓音无关，句子语义不通", "货色": "语域：“货色”是口语且带贬义，与这句客观的陈述语体不协调", "消费观念": "“消费观念”指人们对消费的看法，广告可以影响它"}, "sentence_index": 6, "correct_answer": "消费观念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天在超市买了很多消费观念。", "explanation": "这里把消费观念当作商品来买。买的对象应是〈商品〉，消费观念是看法，不能被买"}, {"text": "我们在消费观念里讨论了今晚的晚饭。", "explanation": "这里把消费观念误当作讨论的场所。讨论应在〈会议室〉或〈餐厅〉进行，消费观念是抽象的看法"}, {"text": "他每天早上都把消费观念当早饭吃。", "explanation": "这里把消费观念当作食物来吃。吃的应是〈食物〉，消费观念是看法"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13418, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一块健康的消费观念。", "corrected_sentence": "这是一种健康的消费观念。", "error_description": "量词错误：“消费观念”应搭配“种”，“块”用于块状的东西，不能说“一块消费观念”，应说“一种健康的消费观念”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13418, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子有一种很健康消费观念。", "corrected_sentence": "这个孩子有一种很健康的消费观念。", "error_description": "结构错误：“很健康”修饰名词时要加“的”，应说“很健康的消费观念”，不能省略“的”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
