INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13419, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想法、态度或行为从一种状态变为另一种", "primary_collocate": null, "pronunciation": "zhuǎn biàn", "ipa": "tʂwan˨˩˦ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "然而，技术革新若无消费观念的同步转变，终将举步维艰。", "target_word": "转变", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "他对这件事的态度转变了。", "target_word": "转变", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师的话让我转变了想法。", "target_word": "转变", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈的看法慢慢转变了。", "target_word": "转变", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要转变学习方法。", "target_word": "转变", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "经过这次教训，他的行为转变了很多。", "target_word": "转变", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "父母的观念需要转变。", "target_word": "转变", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从反对转变为支持。", "target_word": "转变", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "很多人的消费习惯正在转变。", "target_word": "转变", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的态度转变得很快。", "target_word": "转变", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "转变了", "label": "完成体"}, {"form": "转变过", "label": "经历体"}, {"form": "转变着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "想法、态度、观念或行为发生改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b7c4d2-eae5-47dc-9765-446b23df0243') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13419, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转变", "is_correct": true, "explanation": "「转变」指观念由一种状态变为另一种，与「消费观念的同步转变」相符。"}, {"text": "转动", "is_correct": false, "explanation": "语义：「转动」指物体旋转，不能用来指观念的变化。"}, {"text": "转身", "is_correct": false, "explanation": "搭配：「转身」指人的身体动作，不能与「同步」和「观念」搭配。"}, {"text": "转手", "is_correct": false, "explanation": "语义：「转手」指把东西卖给别人，与观念的变化无关。"}], "explanations": {"转变": "「转变」指观念由一种状态变为另一种，与「消费观念的同步转变」相符。", "转动": "语义：「转动」指物体旋转，不能用来指观念的变化。", "转身": "搭配：「转身」指人的身体动作，不能与「同步」和「观念」搭配。", "转手": "语义：「转手」指把东西卖给别人，与观念的变化无关。"}, "sentence_index": 0, "correct_answer": "转变"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他转变了注意力，不再想那件事。", "explanation": "这里应该用〈转移〉。注意力的指向调换用转移；转变用于看法、态度或观念由一种变为另一种。"}, {"text": "他转变了自己的错误。", "explanation": "这里应该用〈改正〉。错误是需要纠正的具体问题，用改正；转变用于看法、态度的根本变化。"}, {"text": "他转变了台灯的亮度。", "explanation": "这里应该用〈调节〉。转变指想法、态度或行为的根本变化，台灯亮度的高低调整应用调节。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ae8a38d-474d-4287-90a5-7a2e2072e722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13419, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转变", "is_correct": true, "explanation": "「转变」指观念由一种状态变为另一种，与「父母的观念需要」相符。"}, {"text": "转播", "is_correct": false, "explanation": "搭配：「转播」指播送信号，不能与「观念」搭配。"}, {"text": "转弯", "is_correct": false, "explanation": "语义：「转弯」指改变行进方向，观念没有行进方向可言。"}, {"text": "转售", "is_correct": false, "explanation": "语义：「转售」指把买来的东西再卖出，与观念无关。"}], "explanations": {"转变": "「转变」指观念由一种状态变为另一种，与「父母的观念需要」相符。", "转播": "搭配：「转播」指播送信号，不能与「观念」搭配。", "转弯": "语义：「转弯」指改变行进方向，观念没有行进方向可言。", "转售": "语义：「转售」指把买来的东西再卖出，与观念无关。"}, "sentence_index": 6, "correct_answer": "转变"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个学期她的作业量转变得很快。", "explanation": "这里应该用〈增加〉。转变指看法、态度等由一种变为另一种，作业量的增多是数量变化，应用增加。"}, {"text": "昨天班上转变了一件大事。", "explanation": "这里应该用〈发生〉。转变指事物本身的变化，外来事件的出现应说发生。"}, {"text": "他转变了两个人的座位。", "explanation": "这里应该用〈调换〉。转变指想法、态度或行为的根本变化，两人座位的互换应用调换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ae8a38d-474d-4287-90a5-7a2e2072e722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13419, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父亲的看法从反对转变在支持。", "corrected_sentence": "父亲的看法从反对转变为支持。", "error_description": "「从……转变为……」中，结果要用「为」引出，这里误用「在」，应改为「为」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ae8a38d-474d-4287-90a5-7a2e2072e722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13419, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从懒散转变认真。", "corrected_sentence": "他从懒散转变为认真。", "error_description": "「从……转变为……」中，结果要用「为」引出，这里漏掉了「为」，句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ae8a38d-474d-4287-90a5-7a2e2072e722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13420, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一帆风顺", "is_correct": true, "explanation": "“一帆风顺”指进展顺利，与“举步维艰”形成反义。"}, {"text": "循规蹈矩", "is_correct": false, "explanation": "“循规蹈矩”指按规矩办事，与“举步维艰”的进展困难没有反义关系。"}, {"text": "谨小慎微", "is_correct": false, "explanation": "“谨小慎微”形容过分小心，与“举步维艰”的困难程度无反义关系。"}, {"text": "落落大方", "is_correct": false, "explanation": "“落落大方”形容举止自然，与“举步维艰”的困难义无关。"}], "correct_answer": "一帆风顺", "explanations": {"一帆风顺": "“一帆风顺”指进展顺利，与“举步维艰”形成反义。", "循规蹈矩": "“循规蹈矩”指按规矩办事，与“举步维艰”的进展困难没有反义关系。", "谨小慎微": "“谨小慎微”形容过分小心，与“举步维艰”的困难程度无反义关系。", "落落大方": "“落落大方”形容举止自然，与“举步维艰”的困难义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13420, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一帆风顺", "is_correct": true, "explanation": "“一帆风顺”指进展顺利，与“举步维艰”形成反义。"}, {"text": "心平气和", "is_correct": false, "explanation": "“心平气和”形容情绪平稳，与“举步维艰”的进展困难无反义关系。"}, {"text": "胸有成竹", "is_correct": false, "explanation": "“胸有成竹”指事先有把握，与“举步维艰”的困难义无关。"}, {"text": "从容不迫", "is_correct": false, "explanation": "“从容不迫”指不慌不忙，与“举步维艰”的困难义无反义关系。"}], "correct_answer": "一帆风顺", "explanations": {"一帆风顺": "“一帆风顺”指进展顺利，与“举步维艰”形成反义。", "心平气和": "“心平气和”形容情绪平稳，与“举步维艰”的进展困难无反义关系。", "胸有成竹": "“胸有成竹”指事先有把握，与“举步维艰”的困难义无关。", "从容不迫": "“从容不迫”指不慌不忙，与“举步维艰”的困难义无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13420, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容走路困难，也比喻事情进展不顺利，遇到很多困难。", "primary_collocate": null, "pronunciation": "jǔ bù wéi jiān", "ipa": "tɕy˨˩˦ pu˥˩ weɪ˧˥ tɕjɛn˥˥", "syllable_count": 4, "sentences": [{"text": "然而，技术革新若无消费观念的同步转变，终将举步维艰。", "target_word": "举步维艰", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公司资金断了，新项目举步维艰。", "target_word": "举步维艰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有客户的支持，小店经营得举步维艰。", "target_word": "举步维艰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场不好，这家工厂一直举步维艰。", "target_word": "举步维艰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "缺少资金和人才，改革举步维艰。", "target_word": "举步维艰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谈判陷入僵局，双方合作举步维艰。", "target_word": "举步维艰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后山路很滑，老人走得举步维艰。", "target_word": "举步维艰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原材料涨价，许多小企业举步维艰。", "target_word": "举步维艰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有政策支持，这项研究举步维艰。", "target_word": "举步维艰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失去了订单，他的生意举步维艰。", "target_word": "举步维艰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "成语，走路艰难，比喻事情进展不顺、困难重重", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c294d4a5-cb8b-4cb8-85ca-1526f4c5d197') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13420, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "举步维艰", "is_correct": true, "explanation": "与“终将”及“若无…的同步转变”的困难语境相符，指进展困难，符合句意。"}, {"text": "一帆风顺", "is_correct": false, "explanation": "语义：“一帆风顺”说明进展顺利，与“若无…的同步转变”推出的困境结果相反。"}, {"text": "蒸蒸日上", "is_correct": false, "explanation": "语义：“蒸蒸日上”形容兴旺发展，与句中隐含的困难相矛盾。"}, {"text": "健步如飞", "is_correct": false, "explanation": "搭配：“健步如飞”描写人走路很快，主语“技术革新”不能这样形容。"}], "explanations": {"举步维艰": "与“终将”及“若无…的同步转变”的困难语境相符，指进展困难，符合句意。", "一帆风顺": "语义：“一帆风顺”说明进展顺利，与“若无…的同步转变”推出的困境结果相反。", "蒸蒸日上": "语义：“蒸蒸日上”形容兴旺发展，与句中隐含的困难相矛盾。", "健步如飞": "搭配：“健步如飞”描写人走路很快，主语“技术革新”不能这样形容。"}, "sentence_index": 0, "correct_answer": "举步维艰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅开业以来顾客盈门，生意举步维艰。", "explanation": "语义：“举步维艰”形容困难、进展不顺，此处误用为“顺利兴旺”的意思，与语境颠倒。"}, {"text": "他的步伐轻快有力，走得举步维艰。", "explanation": "语义：“举步维艰”形容行走困难，此处误用为“轻快有力”的意思，与语境颠倒。"}, {"text": "他在赛场上一路领先，举步维艰地冲向了终点。", "explanation": "语义：“举步维艰”形容困难、进展不顺，此处误用为“轻快迅速”的意思，与语境颠倒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "举步维艰", "is_correct": true, "explanation": "雨后山路很滑，老人行走困难，与句意吻合。"}, {"text": "轻而易举", "is_correct": false, "explanation": "语义：“轻而易举”指很容易，与“雨后山路很滑”的困难条件矛盾。"}, {"text": "一往无前", "is_correct": false, "explanation": "语义：“一往无前”形容勇往直前，不符合老人在湿滑路上行走的情形。"}, {"text": "游刃有余", "is_correct": false, "explanation": "搭配：“游刃有余”多用于处理事务，不用于描写走路。"}], "explanations": {"举步维艰": "雨后山路很滑，老人行走困难，与句意吻合。", "轻而易举": "语义：“轻而易举”指很容易，与“雨后山路很滑”的困难条件矛盾。", "一往无前": "语义：“一往无前”形容勇往直前，不符合老人在湿滑路上行走的情形。", "游刃有余": "搭配：“游刃有余”多用于处理事务，不用于描写走路。"}, "sentence_index": 6, "correct_answer": "举步维艰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚拿到驾照，开车超车时举步维艰地超过了前车。", "explanation": "语义：“举步维艰”形容困难、进展不顺，此处误用为“顺利利落”的意思，用来形容顺利完成的动作，意思颠倒。"}, {"text": "这位老人身体硬朗，每天晨跑时都举步维艰。", "explanation": "语义：“举步维艰”形容行走困难，此处误用为“轻快矫健、行走自如”的意思，与语境颠倒。"}, {"text": "这次改革进展顺利，各项政策推进得举步维艰。", "explanation": "语义：“举步维艰”表示困难、受阻，此处误用为“一帆风顺”的意思，与语境颠倒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工地泥泞，工人们走地举步维艰。", "corrected_sentence": "工地泥泞，工人们走得举步维艰。", "error_description": "错误：“走地举步维艰”。正确：“走得举步维艰”。“举步维艰”作“走”的补语，补语前应用“得”，“地”用于状语，不能用于此处。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "连日暴雨后，年迈的邻居下楼时走举步维艰。", "corrected_sentence": "连日暴雨后，年迈的邻居下楼时走得举步维艰。", "error_description": "错误：“走举步维艰”。正确：“走得举步维艰”。补语前须用“得”，漏掉“得”则不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
