INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13421, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13421, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公共政策是指由政府或其他公共机构制定和实施的，旨在解决公共问题、达成公共目标的一系列行动方案、法律、法规或措施。", "primary_collocate": null, "pronunciation": "gōng gòng zhèng cè", "ipa": "kʊŋ˥ kʊŋ˥˩ ʈʂɤŋ˥˩ tsʰɤ˥˩", "syllable_count": 4, "sentences": [{"text": "唯有通过教育与公共政策引导，培育“少而精”的理性消费文化，抵制过度消费的符号化冲动，方能在需求侧为资源减负创造空间。", "target_word": "公共政策", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "好的公共政策能让更多人过上好日子。", "target_word": "公共政策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府正在研究新的公共政策。", "target_word": "公共政策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项公共政策帮助老人解决看病难的问题。", "target_word": "公共政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共政策的目的是解决大家共同的问题。", "target_word": "公共政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家认为，公共政策要听取市民的意见。", "target_word": "公共政策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项公共政策要照顾住在农村的人。", "target_word": "公共政策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "制定公共政策时，政府要先做调查。", "target_word": "公共政策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公共政策要考虑穷人的需要，不能只想富人。", "target_word": "公共政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项公共政策实施以后，城市的空气好多了。", "target_word": "公共政策", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}], "register": "书面语", "sense_fingerprint": "公共政策：政府或公共机构为解决公共问题而制定实施的方案、法规和措施", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7728ca8c-cc31-47be-a40d-da0fcf2ae697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13421, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公共政策", "is_correct": true, "explanation": "公共政策：指政府制定的方案，可以“引导”消费文化，符合句意。"}, {"text": "公共交通", "is_correct": false, "explanation": "语义：公共交通是交通设施，不能用来引导“理性消费文化”，句意不通。"}, {"text": "公共场所", "is_correct": false, "explanation": "搭配：“引导”一般与“政策、教育、舆论”等搭配，不与场所搭配。"}, {"text": "公共厕所", "is_correct": false, "explanation": "语义：公共厕所与培育消费文化无关，句意不通。"}], "explanations": {"公共政策": "公共政策：指政府制定的方案，可以“引导”消费文化，符合句意。", "公共交通": "语义：公共交通是交通设施，不能用来引导“理性消费文化”，句意不通。", "公共场所": "搭配：“引导”一般与“政策、教育、舆论”等搭配，不与场所搭配。", "公共厕所": "语义：公共厕所与培育消费文化无关，句意不通。"}, "sentence_index": 0, "correct_answer": "公共政策"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府修建了很多公共政策。", "explanation": "这里应该用〈公共设施〉。“修建”用于道路、建筑等实体设施，公共政策是方案和措施，不能修建。"}, {"text": "公共政策要保持安静，不能大声说话。", "explanation": "这里应该用〈公共场所〉。“保持安静、不大声说话”是对人或场所的要求，公共政策是方案，不能做这样的主体。"}, {"text": "我每天乘坐公共政策上班。", "explanation": "这里应该用〈公共交通〉。“乘坐”用于交通工具，公共政策不是交通工具，不能乘坐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13421, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公共政策", "is_correct": true, "explanation": "公共政策：作主语，可以“照顾”农村的人，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人或机构，不能“照顾住在农村的人”，句意不通。"}, {"text": "河流", "is_correct": false, "explanation": "配价：“照顾”要求有施事的人或机构作主语，“河流”不能照顾人。"}, {"text": "土地", "is_correct": false, "explanation": "语义：土地不能“照顾”人，句意说不通。"}], "explanations": {"公共政策": "公共政策：作主语，可以“照顾”农村的人，符合句意。", "天气": "语义：天气不是人或机构，不能“照顾住在农村的人”，句意不通。", "河流": "配价：“照顾”要求有施事的人或机构作主语，“河流”不能照顾人。", "土地": "语义：土地不能“照顾”人，句意说不通。"}, "sentence_index": 6, "correct_answer": "公共政策"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们学习了一只公共政策。", "explanation": "这里应该用量词“项”。“只”用于动物或成对物品中的一个，不用于政策，应说“一项公共政策”。"}, {"text": "会议讨论了一粒公共政策。", "explanation": "这里应该用量词“项”。“粒”用于米、沙等颗粒状物，不用于政策，应说“一项公共政策”。"}, {"text": "政府通过了一座公共政策。", "explanation": "这里应该用量词“项”。“座”用于山、桥、建筑等大型固定物，不用于政策，应说“一项公共政策”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13421, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府正在制定一本公共政策。", "corrected_sentence": "政府正在制定一项公共政策。", "error_description": "“公共政策”的量词用错了：“本”多用于书籍、册子，公共政策应用“项”，应说“一项公共政策”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13421, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "多亏了这项公共政策，城市的空气了好多了。", "corrected_sentence": "多亏了这项公共政策，城市的空气好多了。", "error_description": "“了”位置错误：“了”应只出现在句末，“空气了好多了”中间的“了”多余。正确说法是“城市的空气好多了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
