INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13422, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "培养、教育，使生物或事物成长、发展。", "primary_collocate": null, "pronunciation": "péi yù", "ipa": "pʰeɪ˧˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "唯有通过教育与公共政策引导，培育“少而精”的理性消费文化，抵制过度消费的符号化冲动，方能在需求侧为资源减负创造空间。", "target_word": "培育", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "农业专家成功培育了新的水稻品种。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校应该培育学生的创新精神。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学培育了许多优秀的科学家。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想培育更多的高新技术企业。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在大棚里培育蔬菜的新品种。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用爱心培育着每一个孩子。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司重视培育年轻的技术人才。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家培育出了一种抗旱的小麦。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的家庭环境有助于培育孩子的品格。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "培育了", "label": "体标"}, {"form": "培育过", "label": "体标"}, {"form": "培育着", "label": "体标"}], "register": "书面语", "sense_fingerprint": "培养教育，使生物或事物（人才、品种、风气）成长发展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c294d4a5-cb8b-4cb8-85ca-1526f4c5d197') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13422, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "培育", "is_correct": true, "explanation": "“唯有通过…引导”的语境要求用“培育”，表示使文化逐步形成，符合句意。"}, {"text": "摧毁", "is_correct": false, "explanation": "语义：句中说通过教育与政策“引导”，“摧毁”与此语义相反。"}, {"text": "驱散", "is_correct": false, "explanation": "搭配：“驱散”多用于阴霾、疑虑，不说驱散“文化”。"}, {"text": "消失", "is_correct": false, "explanation": "配价：“消失”是不及物动词，不能带“文化”作宾语。"}], "explanations": {"培育": "“唯有通过…引导”的语境要求用“培育”，表示使文化逐步形成，符合句意。", "摧毁": "语义：句中说通过教育与政策“引导”，“摧毁”与此语义相反。", "驱散": "搭配：“驱散”多用于阴霾、疑虑，不说驱散“文化”。", "消失": "配价：“消失”是不及物动词，不能带“文化”作宾语。"}, "sentence_index": 0, "correct_answer": "培育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上都培育一杯热咖啡。", "explanation": "语义：“培育”只用于使生物或人才成长，此处误用为“冲泡、制作”的意思，咖啡不能这样培育。"}, {"text": "这家工厂培育了大量的螺丝钉。", "explanation": "语义：“培育”只用于使生物或人才成长，此处误用为“批量生产”的意思，把工业产品当作可以培育的对象。"}, {"text": "我们今天培育了一场大雨。", "explanation": "语义：“培育”只用于使生物或人才成长，此处误用为“人为促成、造出”的意思，天气不能这样培育。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13422, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "培育", "is_correct": true, "explanation": "老师用爱心培养孩子，符合“培育”使人成长的语义，与句意吻合。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：“驱赶”指赶走，与“用爱心”的积极语境相反。"}, {"text": "消耗", "is_correct": false, "explanation": "搭配：“消耗”多指精力、资源，不用于“消耗孩子”。"}, {"text": "扑灭", "is_correct": false, "explanation": "搭配：“扑灭”多用于火、疫情，不能用于孩子。"}], "explanations": {"培育": "老师用爱心培养孩子，符合“培育”使人成长的语义，与句意吻合。", "驱赶": "语义：“驱赶”指赶走，与“用爱心”的积极语境相反。", "消耗": "搭配：“消耗”多指精力、资源，不用于“消耗孩子”。", "扑灭": "搭配：“扑灭”多用于火、疫情，不能用于孩子。"}, "sentence_index": 6, "correct_answer": "培育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在考场上培育了很高的分数。", "explanation": "语义：此处误用为“取得、获得”的意思，“培育”只用于使生物或人才成长，成绩不能这样培育。"}, {"text": "这家公司每月都培育大量的资金。", "explanation": "语义：此处误用为“积累、筹集”的意思，“培育”只用于使生物或人才成长，钱款不能这样培育。"}, {"text": "这座城市培育了一座新的大桥。", "explanation": "语义：此处误用为“建造、修建”的意思，“培育”只表示使生物或人才成长，不能用于建筑工程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "园艺师培育了出一种抗病的月季。", "corrected_sentence": "园艺师培育出了一种抗病的月季。", "error_description": "错误：“培育了出”。正确：“培育出了”。结果补语“出”应紧跟动词，“了”置于“出”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他花了五年时间，终于培育出着一种抗虫的玉米。", "corrected_sentence": "他花了五年时间，终于培育出了一种抗虫的玉米。", "error_description": "错误：“培育出着”。正确：“培育出了”。“培育出”表示动作完成，应用“了”，“着”表示持续状态，不能用于此处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13423, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13423, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13423, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容数量虽少，但质量很高。", "primary_collocate": null, "pronunciation": "shǎo ér jīng", "ipa": "ʂaʊ˨˩˦ aɚ˧˥ tɕiŋ˥˥", "syllable_count": 3, "sentences": [{"text": "唯有通过教育与公共政策引导，培育“少而精”的理性消费文化，抵制过度消费的符号化冲动，方能在需求侧为资源减负创造空间。", "target_word": "少而精", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家餐厅的菜单少而精，每道菜都很好吃。", "target_word": "少而精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所小学的师资少而精，每位老师都很有经验。", "target_word": "少而精", "complexity_tier": "T3", "furigana": "zhè suǒ xiǎo xué de shī zī shǎo ér jīng, měi wèi lǎo shī dōu hěn yǒu jīng yàn。", "sentence_source": "generated"}, {"text": "老师说，学习词语要少而精，不要贪多。", "target_word": "少而精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个书店的书少而精，本本都值得读。", "target_word": "少而精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的广告应该少而精，不能太啰嗦。", "target_word": "少而精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的产品少而精，每款都设计得很用心。", "target_word": "少而精", "complexity_tier": "T3", "furigana": "zhè jiā gōng sī de chǎn pǐn shǎo ér jīng, měi kuǎn dōu shè jì de hěn yòng xīn。", "sentence_source": "generated"}, {"text": "展览的作品少而精，件件都有特点。", "target_word": "少而精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的课程少而精，学生学得很轻松。", "target_word": "少而精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买衣服只买少而精的，不乱花钱。", "target_word": "少而精", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "数量少但质量高，强调宁少勿滥", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c294d4a5-cb8b-4cb8-85ca-1526f4c5d197') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13423, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "少而精", "is_correct": true, "explanation": "原句中的词，指数量少而质量高，与“培育理性消费”的要求一致。"}, {"text": "奢侈", "is_correct": false, "explanation": "语义：“奢侈”与“理性消费”相反，放在这里语义矛盾。"}, {"text": "铺张", "is_correct": false, "explanation": "语义：“铺张”指浪费排场，与“理性消费文化”的培育目标冲突。"}, {"text": "盲目", "is_correct": false, "explanation": "搭配：“盲目”可以修饰消费，但与“理性”并用自相矛盾，不能修饰“理性消费文化”。"}], "explanations": {"少而精": "原句中的词，指数量少而质量高，与“培育理性消费”的要求一致。", "奢侈": "语义：“奢侈”与“理性消费”相反，放在这里语义矛盾。", "铺张": "语义：“铺张”指浪费排场，与“理性消费文化”的培育目标冲突。", "盲目": "搭配：“盲目”可以修饰消费，但与“理性”并用自相矛盾，不能修饰“理性消费文化”。"}, "sentence_index": 0, "correct_answer": "少而精"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的年龄少而精，今年才二十岁。", "explanation": "这里把“少而精”误当成了“年轻”的意思，但它只用于形容数量少而质量高的事物，年龄是客观数字，没有“精”与否之分。"}, {"text": "这场比赛我们输了两局，真是少而精。", "explanation": "这里把“少”理解成“输得少”，但“少而精”的“精”要求质量高，输球属于负面结果，不能用来夸赞。"}, {"text": "这座城市的人口少而精，去年又增加了五十万。", "explanation": "这里误把“少而精”当成了只说数量少的“少”，用在人口这类总量上。“精”指质量高，人口并不存在这种评价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13423, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "少而精", "is_correct": true, "explanation": "原句中的词，描述产品数量少而质量高，与“每款都设计得很用心”一致。"}, {"text": "粗糙", "is_correct": false, "explanation": "语义：“粗糙”与“每款都设计得很用心”矛盾。"}, {"text": "随意", "is_correct": false, "explanation": "搭配：“随意”多形容态度或穿着，不用来形容一家公司的产品。"}, {"text": "低劣", "is_correct": false, "explanation": "语义：“低劣”与“每款都设计得很用心”矛盾。"}], "explanations": {"少而精": "原句中的词，描述产品数量少而质量高，与“每款都设计得很用心”一致。", "粗糙": "语义：“粗糙”与“每款都设计得很用心”矛盾。", "随意": "搭配：“随意”多形容态度或穿着，不用来形容一家公司的产品。", "低劣": "语义：“低劣”与“每款都设计得很用心”矛盾。"}, "sentence_index": 6, "correct_answer": "少而精"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的感冒少而精，已经病了一周。", "explanation": "这里把“少而精”误当成了“病情轻”的意思，但它只说数量少而质量高，不能用来形容疾病。"}, {"text": "这次旅行我们走马观花，去了二十个城市，真是少而精。", "explanation": "这里误把“少而精”当成了“广泛、数量多”的意思，但它只表示数量少而质量高，不能用于走马观花式的旅行。"}, {"text": "这家公司的亏损少而精，去年一年亏了两亿。", "explanation": "这里把“少”理解成“亏得少”，但“精”指质量高，亏损两亿是负面结果，不能用“少而精”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13423, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家面包店的品种很少而精，每款都很好吃。", "corrected_sentence": "这家面包店的品种少而精，每款都很好吃。", "error_description": "错误：“很少而精”。正确：“少而精”。“少而精”是固定格式，中间不能插入程度副词“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13423, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司只做被少而精的产品，每款都设计得很用心。", "corrected_sentence": "这家公司只做少而精的产品，每款都设计得很用心。", "error_description": "错误：“被少而精”。正确：删去“被”，作“少而精的产品”。“少而精”是形容词，不能用“被”构成被动式。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13424, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "支持", "is_correct": true, "explanation": "反义：“支持”与“抵制”相对，表示赞同、拥护。"}, {"text": "修建", "is_correct": false, "explanation": "修建是建造、修造，与“抵制”没有反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "研究是探求、考察，与“抵制”没有反义关系。"}, {"text": "整理", "is_correct": false, "explanation": "整理是使有条理，与“抵制”没有反义关系。"}], "correct_answer": "支持", "explanations": {"支持": "反义：“支持”与“抵制”相对，表示赞同、拥护。", "修建": "修建是建造、修造，与“抵制”没有反义关系。", "研究": "研究是探求、考察，与“抵制”没有反义关系。", "整理": "整理是使有条理，与“抵制”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13424, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "支持", "is_correct": true, "explanation": "反义：“支持”与“抵制”相对，表示赞同、拥护。"}, {"text": "观察", "is_correct": false, "explanation": "观察是仔细察看，与“抵制”没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论是交换意见，与“抵制”没有反义关系。"}, {"text": "收藏", "is_correct": false, "explanation": "收藏是保存、搜集，与“抵制”没有反义关系。"}], "correct_answer": "支持", "explanations": {"支持": "反义：“支持”与“抵制”相对，表示赞同、拥护。", "观察": "观察是仔细察看，与“抵制”没有反义关系。", "讨论": "讨论是交换意见，与“抵制”没有反义关系。", "收藏": "收藏是保存、搜集，与“抵制”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13424, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示拒绝接受或反对某种行为、商品、活动等。", "primary_collocate": null, "pronunciation": "dǐ zhì", "ipa": "ti˨˩˦ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "唯有通过教育与公共政策引导，培育“少而精”的理性消费文化，抵制过度消费的符号化冲动，方能在需求侧为资源减负创造空间。", "target_word": "抵制", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "很多人抵制这家公司的产品。", "target_word": "抵制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要抵制不良的网络游戏。", "target_word": "抵制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "消费者联合起来抵制涨价。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校号召学生抵制考试作弊。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直抵制着垃圾食品的诱惑。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民抵制过这种不文明的行为。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人坚决抵制虚假广告。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都抵制在公共场所吸烟的行为。", "target_word": "抵制", "complexity_tier": "T3", "furigana": "dà jiā dōu dǐ zhì zài gōng gòng chǎng suǒ xī yān de xíng wéi。", "sentence_source": "generated"}, {"text": "老师教孩子抵制坏习惯的影响。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抵制了", "label": "体标"}, {"form": "抵制着", "label": "体标"}, {"form": "抵制过", "label": "体标"}], "register": "中性", "sense_fingerprint": "拒绝并反对不良行为、商品或活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c294d4a5-cb8b-4cb8-85ca-1526f4c5d197') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13424, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抵制", "is_correct": true, "explanation": "本词，读作 dǐ zhì，表示拒绝或反对某种行为、商品或活动。"}, {"text": "地质", "is_correct": false, "explanation": "dì（第四声）与 dǐ（第三声）声调不同，意思是地球的构造与变化，即地质。"}, {"text": "体制", "is_correct": false, "explanation": "tǐ 与 dǐ 声母不同（t 与 d），意思是组织的结构或制度，即体制。"}, {"text": "地支", "is_correct": false, "explanation": "dì 与 dǐ 声调不同，zhī 与 zhì 声调也不同，意思是地支，即十二地支。"}], "explanations": {"抵制": "本词，读作 dǐ zhì，表示拒绝或反对某种行为、商品或活动。", "地质": "dì（第四声）与 dǐ（第三声）声调不同，意思是地球的构造与变化，即地质。", "体制": "tǐ 与 dǐ 声母不同（t 与 d），意思是组织的结构或制度，即体制。", "地支": "dì 与 dǐ 声调不同，zhī 与 zhì 声调也不同，意思是地支，即十二地支。"}, "sentence_index": null, "correct_answer": "抵制"}, "level_3": {"options": [{"text": "抵制", "is_correct": true, "explanation": "原句中的词，表示拒绝、反对过度消费的冲动，与前后的目的一致。"}, {"text": "放纵", "is_correct": false, "explanation": "语义：“放纵”与“培育理性消费”的目标相反。"}, {"text": "助长", "is_correct": false, "explanation": "语义：“助长”是促使不良倾向发展，与“方能……创造空间”的语义相矛盾。"}, {"text": "迎合", "is_correct": false, "explanation": "搭配：“迎合”的对象是他人的喜好或市场需求，不用于内在的符号化冲动。"}], "explanations": {"抵制": "原句中的词，表示拒绝、反对过度消费的冲动，与前后的目的一致。", "放纵": "语义：“放纵”与“培育理性消费”的目标相反。", "助长": "语义：“助长”是促使不良倾向发展，与“方能……创造空间”的语义相矛盾。", "迎合": "搭配：“迎合”的对象是他人的喜好或市场需求，不用于内在的符号化冲动。"}, "sentence_index": 0, "correct_answer": "抵制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题我们必须尽快抵制。", "explanation": "这里应该用〈应对〉。“抵制”用于拒绝不良行为或商品，问题要说“应对”。"}, {"text": "为了安全，我们要抵制火灾的发生。", "explanation": "这里应该用〈防止〉。“抵制”用于拒绝不良行为或商品，火灾这类事故应说“防止”。"}, {"text": "这份合同需要用房子来抵制贷款。", "explanation": "这里应该用〈抵押〉。“抵制”表示拒绝、反对，不表示用财物作担保。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13424, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "抵制", "is_correct": true, "explanation": "本词，读作 dǐ zhì，表示拒绝或反对某种行为、商品或活动。"}, {"text": "地址", "is_correct": false, "explanation": "dì（第四声）与 dǐ（第三声）声调不同，zhǐ 与 zhì 声调也不同，意思是地址。"}, {"text": "体质", "is_correct": false, "explanation": "tǐ 与 dǐ 声母不同（t 与 d），意思是人的身体素质，即体质。"}, {"text": "低值", "is_correct": false, "explanation": "dī 与 dǐ 声调不同，zhí 与 zhì 声调也不同，意思是价值低，即低值。"}], "explanations": {"抵制": "本词，读作 dǐ zhì，表示拒绝或反对某种行为、商品或活动。", "地址": "dì（第四声）与 dǐ（第三声）声调不同，zhǐ 与 zhì 声调也不同，意思是地址。", "体质": "tǐ 与 dǐ 声母不同（t 与 d），意思是人的身体素质，即体质。", "低值": "dī 与 dǐ 声调不同，zhí 与 zhì 声调也不同，意思是价值低，即低值。"}, "sentence_index": null, "correct_answer": "抵制"}, "level_3": {"options": [{"text": "抵制", "is_correct": true, "explanation": "原句中的词，表示反对不文明的行为，与句子的评价一致。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”与“不文明的行为”的评价相反。"}, {"text": "赞赏", "is_correct": false, "explanation": "语义：“赞赏”与“不文明”的评价矛盾。"}, {"text": "配合", "is_correct": false, "explanation": "搭配：“配合”的对象多为工作、活动，不接“行为”这类对象。"}], "explanations": {"抵制": "原句中的词，表示反对不文明的行为，与句子的评价一致。", "欢迎": "语义：“欢迎”与“不文明的行为”的评价相反。", "赞赏": "语义：“赞赏”与“不文明”的评价矛盾。", "配合": "搭配：“配合”的对象多为工作、活动，不接“行为”这类对象。"}, "sentence_index": 6, "correct_answer": "抵制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他饿坏了，一口气抵制了三碗米饭。", "explanation": "这里应该用〈吃〉。“抵制”表示拒绝、反对，不表示进食。"}, {"text": "他用汽车抵制了一笔欠款。", "explanation": "这里应该用〈抵偿〉。“抵制”表示拒绝、反对，不表示用财物还债。"}, {"text": "列车终于抵制了目的地。", "explanation": "这里应该用〈抵达〉。“抵制”表示拒绝、反对，不表示到达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应该抵制于浪费粮食的做法。", "corrected_sentence": "我们应该抵制浪费粮食的做法。", "error_description": "错误形式：多加介词“于”。正确形式：“抵制”是及物动词，后面直接接宾语，不说“抵制于……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生们抵制把虚假信息，不转发。", "corrected_sentence": "学生们抵制虚假信息，不转发。", "error_description": "错误形式：在“虚假信息”前多加“把”。正确形式：“抵制虚假信息”。“抵制”可直接接宾语，不能再加“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
