INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13425, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用符号来表示某物，或者把事物用符号的形式表达出来。", "primary_collocate": null, "pronunciation": "fú hào huà", "ipa": "fu˧˥ xɑʊ˥˩ xuɑ˥˩", "syllable_count": 3, "sentences": [{"text": "唯有通过教育与公共政策引导，培育“少而精”的理性消费文化，抵制过度消费的符号化冲动，方能在需求侧为资源减负创造空间。", "target_word": "符号化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "文字是语言符号化的结果。", "target_word": "符号化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画里有很多符号化的表达。", "target_word": "符号化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "符号化让复杂的想法变得简单。", "target_word": "符号化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图是对地形的符号化。", "target_word": "符号化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张地图把河流符号化了，用蓝线表示。", "target_word": "符号化", "complexity_tier": "T3", "furigana": "zhè zhāng dì tú bǎ hé liú fú hào huà le, yòng lán xiàn biǎo shì", "sentence_source": "generated"}, {"text": "老师解释了什么是符号化。", "target_word": "符号化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "符号化可以帮助我们记住信息。", "target_word": "符号化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交通标志是道路信息的符号化。", "target_word": "符号化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种符号化的设计很容易看懂。", "target_word": "符号化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "符號化", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用符号表示事物的过程或结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c294d4a5-cb8b-4cb8-85ca-1526f4c5d197') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13425, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "符号化", "is_correct": true, "explanation": "正确。句中“符号化冲动”指借助符号化形式表达的欲望，与前文“抵制过度消费”的语境相合。"}, {"text": "数学", "is_correct": false, "explanation": "语义：「抵制过度消费的数学冲动」语义不通，“数学”与消费文化无关。"}, {"text": "理性", "is_correct": false, "explanation": "语义：“理性”与“冲动”意思相反，「理性冲动」自相矛盾，且前文已有“理性消费文化”，重复且不合语境。"}, {"text": "体育", "is_correct": false, "explanation": "搭配：“体育冲动”不是常见说法，不能用来修饰“过度消费”所引发的欲望。"}], "explanations": {"符号化": "正确。句中“符号化冲动”指借助符号化形式表达的欲望，与前文“抵制过度消费”的语境相合。", "数学": "语义：「抵制过度消费的数学冲动」语义不通，“数学”与消费文化无关。", "理性": "语义：“理性”与“冲动”意思相反，「理性冲动」自相矛盾，且前文已有“理性消费文化”，重复且不合语境。", "体育": "搭配：“体育冲动”不是常见说法，不能用来修饰“过度消费”所引发的欲望。"}, "sentence_index": 0, "correct_answer": "符号化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "数学课上，我们使用了很多符号化。", "explanation": "这里应该用〈符号〉。符号是可数的具体标记，可以说“很多符号”；“符号化”表示把事物变成符号的过程，不能用“很多”来计数。"}, {"text": "我们把这张照片符号化，贴在墙上。", "explanation": "这里应该用〈打印〉。符号化指用符号表示事物，不指把图像输出到纸上。"}, {"text": "他把这份文件符号化了，电脑里找不到了。", "explanation": "这里应该用〈删除〉。符号化指用符号表示或表达事物，不指把文件从电脑中清除。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13425, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "符号化", "is_correct": true, "explanation": "正确。“用箭头和圆圈”把复杂的流程转为符号，正是“符号化”的义项，与“学生一下子就看懂了”相合。"}, {"text": "装订", "is_correct": false, "explanation": "语义：装订指把纸张装在一起，与用箭头和圆圈讲解流程无关。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：冷冻指降低温度，与讲解流程、让人看懂无关。"}, {"text": "录音", "is_correct": false, "explanation": "语义：录音指录制声音，与用箭头和圆圈讲解流程不相符。"}], "explanations": {"符号化": "正确。“用箭头和圆圈”把复杂的流程转为符号，正是“符号化”的义项，与“学生一下子就看懂了”相合。", "装订": "语义：装订指把纸张装在一起，与用箭头和圆圈讲解流程无关。", "冷冻": "语义：冷冻指降低温度，与讲解流程、让人看懂无关。", "录音": "语义：录音指录制声音，与用箭头和圆圈讲解流程不相符。"}, "sentence_index": 6, "correct_answer": "符号化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的符号化很有特色，读起来很顺。", "explanation": "这里应该用〈翻译〉。符号化指用符号表示事物，不指把一种语言转换成另一种语言，不能用来形容译文的特色。"}, {"text": "老师把黑板上的错字符号化了，让我们看得更清楚。", "explanation": "这里应该用〈擦掉〉。符号化指用符号表示或表达事物，不指把字迹去除。"}, {"text": "交通符号化很醒目。", "explanation": "这里应该用〈标志〉。“标志”是可以看见的具体标记，可以说“很醒目”；“符号化”指过程，不能用来描述醒目程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13425, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们做了一个符号化处理。", "corrected_sentence": "我们做了一次符号化处理。", "error_description": "量词错误：“符号化”指一次转换过程，计次时应用“次”，不用“个”。正确形式是“做了一次符号化处理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13425, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张图把道路符号化，司机一看就懂。", "corrected_sentence": "这张图把道路符号化了，司机一看就懂。", "error_description": "错误形式：漏掉“了”，写成“把道路符号化”。正确形式：“把道路符号化了”。“把”字句的谓语动词后要有补语或“了”等成分，只说“把道路符号化”不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13426, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理智", "is_correct": true, "explanation": "正确。“理智”指理性的判断，与“冲动”（突然涌起的欲望）在词义上相对。"}, {"text": "天空", "is_correct": false, "explanation": "“天空”是自然事物，与“冲动”的任何义项都没有反义关系。"}, {"text": "树叶", "is_correct": false, "explanation": "“树叶”是植物的部分，与“冲动”的任何义项都没有反义关系。"}, {"text": "课本", "is_correct": false, "explanation": "“课本”是学习用品，与“冲动”的任何义项都没有反义关系。"}], "correct_answer": "理智", "explanations": {"理智": "正确。“理智”指理性的判断，与“冲动”（突然涌起的欲望）在词义上相对。", "天空": "“天空”是自然事物，与“冲动”的任何义项都没有反义关系。", "树叶": "“树叶”是植物的部分，与“冲动”的任何义项都没有反义关系。", "课本": "“课本”是学习用品，与“冲动”的任何义项都没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13426, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理性", "is_correct": true, "explanation": "正确。“理性”指依据理智进行的判断，与“冲动”（突然涌起的欲望）在词义上相对。"}, {"text": "河流", "is_correct": false, "explanation": "“河流”是自然地理事物，与“冲动”的任何义项都没有反义关系。"}, {"text": "草原", "is_correct": false, "explanation": "“草原”是地貌类型，与“冲动”的任何义项都没有反义关系。"}, {"text": "地震", "is_correct": false, "explanation": "“地震”是自然灾害，与“冲动”的任何义项都没有反义关系。"}], "correct_answer": "理性", "explanations": {"理性": "正确。“理性”指依据理智进行的判断，与“冲动”（突然涌起的欲望）在词义上相对。", "河流": "“河流”是自然地理事物，与“冲动”的任何义项都没有反义关系。", "草原": "“草原”是地貌类型，与“冲动”的任何义项都没有反义关系。", "地震": "“地震”是自然灾害，与“冲动”的任何义项都没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13426, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "情感或欲望突然涌起，使人来不及仔细思考就采取行动。", "primary_collocate": null, "pronunciation": "chōng dòng", "ipa": "ʈʂʰʊŋ˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "唯有通过教育与公共政策引导，培育“少而精”的理性消费文化，抵制过度消费的符号化冲动，方能在需求侧为资源减负创造空间。", "target_word": "冲动", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "看到新手机，他有买的冲动。", "target_word": "冲动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有一种想哭的冲动。", "target_word": "冲动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她控制不住自己的冲动。", "target_word": "冲动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西时要克制冲动。", "target_word": "冲动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到好消息，我有想跳起来的冲动。", "target_word": "冲动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一时的冲动让他说了很多错话。", "target_word": "冲动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里有一股想回家的冲动。", "target_word": "冲动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青春期的孩子常常有冲动。", "target_word": "冲动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我抵挡不住吃蛋糕的冲动。", "target_word": "冲动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股冲动", "label": "量词"}, {"form": "衝動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "突然涌起、想立刻行动的情感或欲望", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c294d4a5-cb8b-4cb8-85ca-1526f4c5d197') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13426, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "冲动", "is_correct": true, "explanation": "正确答案：冲动（chōng dòng）。"}, {"text": "充当", "is_correct": false, "explanation": "chōng dāng 与 chōng dòng 的第二音节韵母不同（āng 与 òng），意思是担任，与“突然涌起的欲望”无关。"}, {"text": "冲淡", "is_correct": false, "explanation": "chōng dàn 与 chōng dòng 的第二音节韵母不同（an 与 ong），意思是使浓度降低。"}, {"text": "抽动", "is_correct": false, "explanation": "chōu dòng 与 chōng dòng 的第一音节韵母不同（ou 与 ong），意思是快速地拉动或抽搐。"}], "explanations": {"冲动": "正确答案：冲动（chōng dòng）。", "充当": "chōng dāng 与 chōng dòng 的第二音节韵母不同（āng 与 òng），意思是担任，与“突然涌起的欲望”无关。", "冲淡": "chōng dàn 与 chōng dòng 的第二音节韵母不同（an 与 ong），意思是使浓度降低。", "抽动": "chōu dòng 与 chōng dòng 的第一音节韵母不同（ou 与 ong），意思是快速地拉动或抽搐。"}, "sentence_index": null, "correct_answer": "冲动"}, "level_3": {"options": [{"text": "冲动", "is_correct": true, "explanation": "正确。“符号化冲动”指由符号化形式引发的欲望，与前文“抵制过度消费”相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「符号化天气」语义不通，与消费文化的语境无关。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“符号化”不修饰“窗户”这类具体物品，“符号化窗户”不成说法。"}, {"text": "课本", "is_correct": false, "explanation": "语义：「符号化课本」与前文所说的消费心理无关，语义不通。"}], "explanations": {"冲动": "正确。“符号化冲动”指由符号化形式引发的欲望，与前文“抵制过度消费”相合。", "天气": "语义：「符号化天气」语义不通，与消费文化的语境无关。", "窗户": "搭配：“符号化”不修饰“窗户”这类具体物品，“符号化窗户”不成说法。", "课本": "语义：「符号化课本」与前文所说的消费心理无关，语义不通。"}, "sentence_index": 0, "correct_answer": "冲动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他心里忽然冒出一只冲动，想马上离开。", "explanation": "这里应该用〈股〉。冲动作为情绪或欲望，量词用“一股”；“只”多用于动物或单个小物件，不能修饰冲动。"}, {"text": "他养成了早起的冲动。", "explanation": "这里应该用〈习惯〉。“养成”搭配“习惯”；冲动是突然涌起、持续很短的情绪，不能说“养成冲动”。"}, {"text": "我的冲动是成为一名医生。", "explanation": "这里应该用〈愿望〉。冲动指突然涌起、想立刻行动的情绪，持续时间短，不能用来表示长期的目标。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13426, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "冲动", "is_correct": true, "explanation": "正确答案：冲动（chōng dòng）。"}, {"text": "出动", "is_correct": false, "explanation": "chū dòng 与 chōng dòng 的第一音节韵母不同（u 与 ong），意思是派出人员或设备。"}, {"text": "虫洞", "is_correct": false, "explanation": "chóng dòng 与 chōng dòng 只有第一音节声调不同（一声与二声），意思是连接宇宙两处的通道。"}, {"text": "冲荡", "is_correct": false, "explanation": "chōng dàng 与 chōng dòng 的第二音节韵母不同（ang 与 ong），意思是冲刷、荡涤。"}], "explanations": {"冲动": "正确答案：冲动（chōng dòng）。", "出动": "chū dòng 与 chōng dòng 的第一音节韵母不同（u 与 ong），意思是派出人员或设备。", "虫洞": "chóng dòng 与 chōng dòng 只有第一音节声调不同（一声与二声），意思是连接宇宙两处的通道。", "冲荡": "chōng dàng 与 chōng dòng 的第二音节韵母不同（ang 与 ong），意思是冲刷、荡涤。"}, "sentence_index": null, "correct_answer": "冲动"}, "level_3": {"options": [{"text": "冲动", "is_correct": true, "explanation": "正确。“一时的冲动让他说了很多错话”，“冲动”指突然涌起的情绪。"}, {"text": "数字", "is_correct": false, "explanation": "语义：「一时的数字让他说了很多错话」语义不通，数字不能使人说话。"}, {"text": "石头", "is_correct": false, "explanation": "语义：「一时的石头让他说了很多错话」语义不通，与人的情绪无关。"}, {"text": "地址", "is_correct": false, "explanation": "配价：“让他说错话”的主语应是情绪、行为或人，“地址”不能使人说话。"}], "explanations": {"冲动": "正确。“一时的冲动让他说了很多错话”，“冲动”指突然涌起的情绪。", "数字": "语义：「一时的数字让他说了很多错话」语义不通，数字不能使人说话。", "石头": "语义：「一时的石头让他说了很多错话」语义不通，与人的情绪无关。", "地址": "配价：“让他说错话”的主语应是情绪、行为或人，“地址”不能使人说话。"}, "sentence_index": 6, "correct_answer": "冲动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他学会了游泳的冲动。", "explanation": "这里应该用〈技能〉。“学会”搭配“技能”；冲动是突然涌起的情绪，不能用“学会”来表示。"}, {"text": "他的心里藏着一颗冲动，想去吃蛋糕。", "explanation": "这里应该用〈股〉。“颗”用于粒状、圆形的小东西，不能修饰抽象的冲动。"}, {"text": "我的冲动是明年换工作。", "explanation": "这里应该用〈打算〉。“冲动”指突然涌起、想立刻行动的情绪，不能表示经过考虑后的安排。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13426, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他心里有一条冲动想回家。", "corrected_sentence": "他心里有一股冲动想回家。", "error_description": "量词错误：“冲动”作为情绪或欲望，量词应用“股”；“条”多用于细长的东西，不能修饰冲动。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13426, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他心里涌起一股冲动了，想马上离开。", "corrected_sentence": "他心里涌起一股冲动，想马上离开。", "error_description": "语法标记错误：“了”加在名词“冲动”后，表示完成的变化，不符合句意。“冲动”是名词，不能带“了”。正确形式是“涌起一股冲动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
