INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13427, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13427, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示只有在某种条件或情况下，才能达到某种结果或实现某种目的。", "primary_collocate": null, "pronunciation": "fāng néng", "ipa": "fɑŋ˥ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "唯有通过教育与公共政策引导，培育“少而精”的理性消费文化，抵制过度消费的符号化冲动，方能在需求侧为资源减负创造空间。", "target_word": "方能", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "只有坚持练习，方能真正学好汉语。", "target_word": "方能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学会倾听别人，方能得到别人的信任。", "target_word": "方能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唯有付出努力，方能取得好成绩。", "target_word": "方能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做人诚实守信，方能赢得尊重。", "target_word": "方能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多读书，多思考，方能增长见识。", "target_word": "方能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身体健康，方能安心工作。", "target_word": "方能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过反复试验，方能确定结果。", "target_word": "方能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心中有目标，方能走得更远。", "target_word": "方能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先把基础打牢，方能一步步向前。", "target_word": "方能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "书面副词，表示满足前提条件之后才能实现结果，常与“只有、唯有”呼应", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc48de5a-e0a4-461a-9d2c-5287d6870dbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13427, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方能", "is_correct": true, "explanation": "正确：「方能」表示只有满足前面的条件才能实现结果，与句首的「唯有」呼应。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：「竟然」表示出乎意料，与「唯有……」引出的条件句不合。"}, {"text": "果然", "is_correct": false, "explanation": "语义：「果然」表示证实先前的预料，而此处是条件句，只是设想，无法证实。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：「唯有」之后要接尚未实现的条件结果，「已经」表示已经发生，二者不能搭配。"}], "explanations": {"方能": "正确：「方能」表示只有满足前面的条件才能实现结果，与句首的「唯有」呼应。", "竟然": "语义：「竟然」表示出乎意料，与「唯有……」引出的条件句不合。", "果然": "语义：「果然」表示证实先前的预料，而此处是条件句，只是设想，无法证实。", "已经": "搭配：「唯有」之后要接尚未实现的条件结果，「已经」表示已经发生，二者不能搭配。"}, "sentence_index": 0, "correct_answer": "方能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他十点方能起床。", "explanation": "这里应该用〈才〉。「才」可以表示时间晚，「方能」只表示满足条件后才能做某事，不能表示“迟、晚”。"}, {"text": "只要有钥匙，方能进门。", "explanation": "这里应该用〈就〉。「只要……就……」表示充分条件，「方能」表示必要条件，二者语义冲突。"}, {"text": "我今天很累，方能早点睡。", "explanation": "这里应该用〈所以〉。「方能」表示条件关系，不能表示因果，说因果要用「所以」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13427, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方能", "is_correct": true, "explanation": "正确：「方能」表示只有身体健康这一条件满足，才能安心工作。"}, {"text": "反而", "is_correct": false, "explanation": "语义：「反而」表示与预期相反，而「身体健康」正是安心工作顺理成章的前提，二者不合。"}, {"text": "却", "is_correct": false, "explanation": "搭配：「却」需要前文有转折语境，此句前后是条件关系，没有转折，不能搭配。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：「偏偏」表示有意与常理相反，与「身体健康」这种正常前提不合。"}], "explanations": {"方能": "正确：「方能」表示只有身体健康这一条件满足，才能安心工作。", "反而": "语义：「反而」表示与预期相反，而「身体健康」正是安心工作顺理成章的前提，二者不合。", "却": "搭配：「却」需要前文有转折语境，此句前后是条件关系，没有转折，不能搭配。", "偏偏": "语义：「偏偏」表示有意与常理相反，与「身体健康」这种正常前提不合。"}, "sentence_index": 6, "correct_answer": "方能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天方能早起。", "explanation": "这里应该用〈总是〉。「方能」表示只有满足条件才能实现结果，不能表示经常性、习惯性的动作。"}, {"text": "太阳方能从西边升起。", "explanation": "这里应该用〈不会〉。「方能」要求先满足某个条件才能实现结果，句中没有任何条件，所述是自然规律，应该用「不会」否定。"}, {"text": "懒惰方能导致失败。", "explanation": "这里应该用〈必然〉。「方能」表示条件，表示必然的结果要用「必然」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13427, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "只有坚持，才方能成功。", "corrected_sentence": "只有坚持，方能成功。", "error_description": "错误：「方能」前又加了「才」，两者都表示“只有……才……”，叠用多余。正确：「只有坚持，方能成功。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13427, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学好基础，方能了进步。", "corrected_sentence": "学好基础，方能进步。", "error_description": "错误：「方能」是副词，后面不能直接加「了」。正确：「学好基础，方能进步。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
