INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13430, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "可以发展或行动的余地或机会", "primary_collocate": null, "pronunciation": "kōng jiān", "ipa": "kʰʊŋ˥ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "唯有通过教育与公共政策引导，培育“少而精”的理性消费文化，抵制过度消费的符号化冲动，方能在需求侧为资源减负创造空间。", "target_word": "空间", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公司要给年轻人更多成长的空间。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司还有很大的发展空间。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "价格已经很低，没有再降的空间了。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢你给了我自己选择的空间。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他觉得在这里没有进步的空间。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个行业的上升空间很大。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理给了新人犯错的空间。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份工作让我有很多学习的空间。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行说利率还有调整的空间。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "空間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "发展或行动的余地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1880ae27-277a-4733-a3c1-9b641a61ba6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13430, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空间", "is_correct": true, "explanation": "正确。“空间”指可以发展或行动的余地，这里说为资源减负留出余地。"}, {"text": "眼神", "is_correct": false, "explanation": "搭配：“创造”不接“眼神”，“创造眼神”说不通。"}, {"text": "性格", "is_correct": false, "explanation": "语义：为资源减负不能“创造性格”，与句意无关。"}, {"text": "体重", "is_correct": false, "explanation": "语义：资源减负与体重无关，“创造体重”说不通。"}], "explanations": {"空间": "正确。“空间”指可以发展或行动的余地，这里说为资源减负留出余地。", "眼神": "搭配：“创造”不接“眼神”，“创造眼神”说不通。", "性格": "语义：为资源减负不能“创造性格”，与句意无关。", "体重": "语义：资源减负与体重无关，“创造体重”说不通。"}, "sentence_index": 0, "correct_answer": "空间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆列车的空间很快。", "explanation": "这里应该用〈速度〉。空间指可以行动的余地，不能用来形容快慢；说列车快要用“速度”。"}, {"text": "他终于等到了这次空间。", "explanation": "这里应该用〈机会〉。空间指可以行动的余地，不能说“这次空间”；指一次难得的时机要用“机会”。"}, {"text": "他的空间很低落。", "explanation": "这里应该用〈心情〉。空间指可以发展或行动的余地，不能用来形容人的情绪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d451d-6a39-4ba8-96b4-5dde3e13b1bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13430, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空间", "is_correct": true, "explanation": "正确。“空间”指可以发展的余地，这里说行业的上升余地大。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：行业的上升不能用“颜色”来衡量，“上升颜色很大”说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：行业的上升与气味无关，“上升味道很大”说不通。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“上升”不搭配“寿命”，“上升寿命”不是常见说法。"}], "explanations": {"空间": "正确。“空间”指可以发展的余地，这里说行业的上升余地大。", "颜色": "语义：行业的上升不能用“颜色”来衡量，“上升颜色很大”说不通。", "味道": "语义：行业的上升与气味无关，“上升味道很大”说不通。", "寿命": "搭配：“上升”不搭配“寿命”，“上升寿命”不是常见说法。"}, "sentence_index": 6, "correct_answer": "空间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这朵花的空间很鲜艳。", "explanation": "这里应该用〈颜色〉。空间不能用来形容颜色的鲜艳程度；说花的颜色鲜艳要用“颜色”。"}, {"text": "这台机器的空间还很长。", "explanation": "这里应该用〈寿命〉。空间不表示使用年限，说机器还能用多久要用“寿命”。"}, {"text": "她的空间已经三十岁了。", "explanation": "这里应该用〈年龄〉。空间指可以行动的余地或机会，不能用来说人的岁数；说人多大了要用“年龄”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d451d-6a39-4ba8-96b4-5dde3e13b1bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事情还有一张商量的空间。", "corrected_sentence": "这件事情还有一点商量的空间。", "error_description": "量词错误：“张”用于纸张、桌子等平面的东西，不用于抽象的“余地”义，这里应说“一点商量的空间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d451d-6a39-4ba8-96b4-5dde3e13b1bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个方案还有改进的的空间。", "corrected_sentence": "这个方案还有改进的空间。", "error_description": "修饰语“改进的”后只需一个“的”。原句“改进的的空间”多了一个“的”，正确说法是“这个方案还有改进的空间”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d451d-6a39-4ba8-96b4-5dde3e13b1bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
