INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13431, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容资源丰富，用不完。", "primary_collocate": null, "pronunciation": "qǔ zhī bù jìn", "ipa": "tɕʰy˨˩˦ ʈʂɻ̩˥ pu˥˩ tɕin˥˩", "syllable_count": 4, "sentences": [{"text": "水资源并非取之不尽的背景性资源，而是维系文明存续的流动命脉。", "target_word": "取之不尽", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "大海里的宝藏好像取之不尽。", "target_word": "取之不尽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳能是一种取之不尽的能源。", "target_word": "取之不尽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以前人们以为森林是取之不尽的。", "target_word": "取之不尽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风能取之不尽，用起来也很干净。", "target_word": "取之不尽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "潮汐能取之不尽，是一种清洁的能源。", "target_word": "取之不尽", "complexity_tier": "T3", "furigana": "cháo xī néng qǔ zhī bú jìn, shì yī zhǒng qīng jié de néng yuán.", "sentence_source": "generated"}, {"text": "这座图书馆的藏书取之不尽，足够几代人阅读。", "target_word": "取之不尽", "complexity_tier": "T3", "furigana": "zhè zuò tú shū guǎn de cáng shū qǔ zhī bú jìn, zú gòu jǐ dài rén yuè dú.", "sentence_source": "generated"}, {"text": "大自然给我们的资源并不是取之不尽的。", "target_word": "取之不尽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的水取之不尽，村里人从来不缺水。", "target_word": "取之不尽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的想象力好像取之不尽。", "target_word": "取之不尽", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "取之不尽的", "label": "定语形式"}, {"form": "取之不尽，用之不竭", "label": "固定搭配"}], "register": "书面语", "sense_fingerprint": "资源丰富，怎么用都用不完", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7728ca8c-cc31-47be-a40d-da0fcf2ae697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13431, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取之不尽", "is_correct": true, "explanation": "正确：与“并非……而是……”的否定结构相合，句意是水资源并非用不完的背景资源。"}, {"text": "易碎", "is_correct": false, "explanation": "语义：“易碎”形容物品，不能修饰“水资源”，句意不通。"}, {"text": "快乐", "is_correct": false, "explanation": "搭配：“快乐”形容人的情绪，不能修饰“背景性资源”。"}, {"text": "木制", "is_correct": false, "explanation": "语义：“水资源”不是木材，“木制”与“水”冲突。"}], "explanations": {"取之不尽": "正确：与“并非……而是……”的否定结构相合，句意是水资源并非用不完的背景资源。", "易碎": "语义：“易碎”形容物品，不能修饰“水资源”，句意不通。", "快乐": "搭配：“快乐”形容人的情绪，不能修饰“背景性资源”。", "木制": "语义：“水资源”不是木材，“木制”与“水”冲突。"}, "sentence_index": 0, "correct_answer": "取之不尽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个箱子取之不尽。", "explanation": "这里应该用〈装不下〉。取之不尽只形容资源用不完，不能用来形容箱子之类的容器。"}, {"text": "他的话取之不尽。", "explanation": "这里应该用〈滔滔不绝〉。取之不尽只形容资源丰富，不用于形容说话连续不断。"}, {"text": "这些学生取之不尽。", "explanation": "这里应该用〈很多〉。取之不尽形容物资，指人数多时不说“取之不尽”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13431, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取之不尽", "is_correct": true, "explanation": "正确：与后句“足够几代人阅读”呼应，说明藏书用不完。"}, {"text": "稀少", "is_correct": false, "explanation": "语义：“稀少”与“足够几代人阅读”相矛盾，藏书不可能既少又够用。"}, {"text": "残缺", "is_correct": false, "explanation": "语义：“残缺”说明藏书不完整，与“足够几代人阅读”相悖。"}, {"text": "寂静", "is_correct": false, "explanation": "搭配：“寂静”形容环境或声音，不能修饰“藏书”。"}], "explanations": {"取之不尽": "正确：与后句“足够几代人阅读”呼应，说明藏书用不完。", "稀少": "语义：“稀少”与“足够几代人阅读”相矛盾，藏书不可能既少又够用。", "残缺": "语义：“残缺”说明藏书不完整，与“足够几代人阅读”相悖。", "寂静": "搭配：“寂静”形容环境或声音，不能修饰“藏书”。"}, "sentence_index": 6, "correct_answer": "取之不尽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对你的感激取之不尽。", "explanation": "这里应该用〈感激不尽〉。取之不尽形容资源用不完，不用于表达情感；对别人的帮助感谢到极点应说“感激不尽”。"}, {"text": "她的性情取之不尽。", "explanation": "这里应该用〈善变〉。取之不尽只用于资源，不用于形容性格或性情。"}, {"text": "他的不幸取之不尽。", "explanation": "这里应该用〈接二连三〉。取之不尽形容资源用不完，不能用来说不幸的事；不幸接连出现应说“接二连三”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13431, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片森林里有取之不尽木材。", "corrected_sentence": "这片森林里有取之不尽的木材。", "error_description": "错误形式：“取之不尽木材”，漏掉定语标记“的”。正确形式：“取之不尽的木材”。取之不尽作定语修饰名词时必须加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13431, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片海域的鱼很取之不尽，渔民常年打不完。", "corrected_sentence": "这片海域的鱼取之不尽，渔民常年打不完。", "error_description": "错误形式：“很取之不尽”，给取之不尽加了程度副词“很”。正确形式：“取之不尽”直接作谓语，不加“很”。取之不尽是四字格，一般不接“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
