INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13434, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指水分完全消失，变得没有水。", "primary_collocate": null, "pronunciation": "gān hé", "ipa": "kan˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "当每一件廉价T恤背后都映射出干涸的河流与受污的土壤，我们不得不重新审视时尚的真正成本。", "target_word": "干涸", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "河水干涸，鱼没有水。", "target_word": "干涸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夏天太热，小河慢慢干涸了。", "target_word": "干涸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这口井已经干涸很多年了。", "target_word": "干涸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "长期没有下雨，田边的水塘全都干涸了。", "target_word": "干涸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙漠里的泉水干涸后，动物只好离开。", "target_word": "干涸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为过度用水，这条河每年春天都会干涸。", "target_word": "干涸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他蹲在干涸的池塘边，想找几条小鱼。", "target_word": "干涸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "干涸的土地上，一棵草也没有。", "target_word": "干涸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大湖干涸过两次，现在又有水了。", "target_word": "干涸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "干涸了", "label": "体标（了）"}, {"form": "干涸过", "label": "体标（过）"}, {"form": "乾涸", "label": "繁体"}], "register": "中性", "sense_fingerprint": "河湖、水井、水塘等的水分完全消失，变得没有水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '434c0685-b138-4d57-a528-8792d79dfc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13434, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干涸", "is_correct": true, "explanation": "正确：干涸修饰河流，指水分完全消失，与句中「映射出」的环境破坏相合。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」说人或物的体形，不用来形容河流。"}, {"text": "繁茂", "is_correct": false, "explanation": "搭配：「繁茂」多用于草木，不用来形容河流。"}, {"text": "挺拔", "is_correct": false, "explanation": "体貌：「挺拔」说树木或人的身形，不用来形容河流。"}], "explanations": {"干涸": "正确：干涸修饰河流，指水分完全消失，与句中「映射出」的环境破坏相合。", "高大": "体貌：「高大」说人或物的体形，不用来形容河流。", "繁茂": "搭配：「繁茂」多用于草木，不用来形容河流。", "挺拔": "体貌：「挺拔」说树木或人的身形，不用来形容河流。"}, "sentence_index": 0, "correct_answer": "干涸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这束花放了一周，慢慢干涸了。", "explanation": "这里应该用〈枯萎〉。枯萎用于花草失去生机；干涸只用于河、湖、井等水体没有水。"}, {"text": "他的皮肤因为缺水已经干涸了。", "explanation": "这里应该用〈干燥〉。干燥说皮肤、空气缺少水分；干涸只说河、湖、井等水体没有水，不用于皮肤。"}, {"text": "这块蛋糕放了两天，已经干涸了。", "explanation": "这里应该用〈干硬〉。干硬说食物失去水分变硬；干涸只用于河、湖、井等水体没有水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13434, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干涸", "is_correct": true, "explanation": "正确：「每年春天都会」说明这条河的情况，与「因为过度用水」的因果相合，干涸最合适。"}, {"text": "上涨", "is_correct": false, "explanation": "语义：「过度用水」会让水减少，「每年春天都会上涨」与句中的因果矛盾。"}, {"text": "充盈", "is_correct": false, "explanation": "语域：「充盈」偏书面，与这句口语化的叙述不协调，且与「过度用水」的因果不符。"}, {"text": "沸腾", "is_correct": false, "explanation": "搭配：「沸腾」指液体受热翻滚，不用来描述河流在春天的状况。"}], "explanations": {"干涸": "正确：「每年春天都会」说明这条河的情况，与「因为过度用水」的因果相合，干涸最合适。", "上涨": "语义：「过度用水」会让水减少，「每年春天都会上涨」与句中的因果矛盾。", "充盈": "语域：「充盈」偏书面，与这句口语化的叙述不协调，且与「过度用水」的因果不符。", "沸腾": "搭配：「沸腾」指液体受热翻滚，不用来描述河流在春天的状况。"}, "sentence_index": 6, "correct_answer": "干涸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火慢慢干涸了，屋里越来越冷。", "explanation": "这里应该用〈熄灭〉。熄灭说火、光失去光亮或热；干涸只用于水分完全消失的水体。"}, {"text": "他的听力已经干涸了。", "explanation": "这里应该用〈减退〉。听力等能力逐渐变弱用减退；干涸只说水分完全消失。"}, {"text": "这座城市的路灯已经干涸了。", "explanation": "这里应该用〈坏了〉。坏可用于机器、设备；干涸只用于水分完全消失的水体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏天太热，河水干涸的很快。", "corrected_sentence": "夏天太热，河水干涸得很快。", "error_description": "错误在于补语标记。表示程度的补语要用「得」，不能用「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13434, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条河前年就被干涸了。", "corrected_sentence": "那条河前年就干涸了。", "error_description": "错误在于使用了「被」字被动句。干涸是不及物动词，没有受事者，不能用「被」，应说「干涸了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13435, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13435, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13435, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "受到污染或玷污", "primary_collocate": null, "pronunciation": "shòu wū", "ipa": "ʂou˥˩ u˥", "syllable_count": 2, "sentences": [{"text": "当每一件廉价T恤背后都映射出干涸的河流与受污的土壤，我们不得不重新审视时尚的真正成本。", "target_word": "受污", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工厂排出废水，河水很快就受污了。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受污的土壤种不出好粮食。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河受污多年，鱼都死光了。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的河流受污以后，鱼虾越来越少。", "target_word": "受污", "complexity_tier": "T3", "furigana": "zhè zuò chéngshì de héliú shòuwū yǐhòu, yúxiā yuèláiyuè shǎo.", "sentence_source": "generated"}, {"text": "湖水受污，岸边再也没有人游泳。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家检查了受污的井水。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的沙滩受污后，游客少了很多。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的名声因为那件事而受污。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一旦水源受污，全城的人都会生病。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "受到污染或玷污，指环境或名声受损", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc48de5a-e0a4-461a-9d2c-5287d6870dbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13435, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受污", "is_correct": true, "explanation": "正确：“受污的土壤”指被污染的土壤，与“干涸的河流”“时尚的真正成本”的批判语境吻合。"}, {"text": "灌溉", "is_correct": false, "explanation": "语义：“灌溉的土壤”指被浇水的土地，与污染成本的批判语境相反。"}, {"text": "施肥", "is_correct": false, "explanation": "搭配：“施肥”针对田地或庄稼，不能与“映射出干涸的河流与”对举构成这一批判语境。"}, {"text": "净化", "is_correct": false, "explanation": "语义：“净化”与“受污”意思相反，“净化的土壤”会与整句的污染批判矛盾。"}], "explanations": {"受污": "正确：“受污的土壤”指被污染的土壤，与“干涸的河流”“时尚的真正成本”的批判语境吻合。", "灌溉": "语义：“灌溉的土壤”指被浇水的土地，与污染成本的批判语境相反。", "施肥": "搭配：“施肥”针对田地或庄稼，不能与“映射出干涸的河流与”对举构成这一批判语境。", "净化": "语义：“净化”与“受污”意思相反，“净化的土壤”会与整句的污染批判矛盾。"}, "sentence_index": 0, "correct_answer": "受污"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子吃了变质的食物，受污了。", "explanation": "这里应该用〈中毒〉。受污指物体或环境被污染，不用来指人吃了坏东西而中毒。"}, {"text": "听到这个消息，他的心情受污了。", "explanation": "这里应该用〈受影响〉。受污指受到污染，不用来指心情被影响。"}, {"text": "他的体重这几个月明显受污了。", "explanation": "这里应该用〈增加〉或〈减轻〉。受污指受到污染，不用来说体重的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13435, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受污", "is_correct": true, "explanation": "正确：“受污的井水”指被污染的井水，与“专家检查”的语境吻合。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：“哭泣”是人的动作，不能修饰井水，句子无法成立。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是人发出的声音，不能修饰井水，与“检查”的对象不合。"}, {"text": "熬夜", "is_correct": false, "explanation": "搭配：“熬夜”是不及物的动作，不能修饰井水，与“检查了”之后的名词搭配不当。"}], "explanations": {"受污": "正确：“受污的井水”指被污染的井水，与“专家检查”的语境吻合。", "哭泣": "语义：“哭泣”是人的动作，不能修饰井水，句子无法成立。", "咳嗽": "语义：“咳嗽”是人发出的声音，不能修饰井水，与“检查”的对象不合。", "熬夜": "搭配：“熬夜”是不及物的动作，不能修饰井水，与“检查了”之后的名词搭配不当。"}, "sentence_index": 6, "correct_answer": "受污"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片湿地受污后变得更干净了。", "explanation": "这里应该用〈净化〉。受污指受到污染，句中“变得更干净”与它的意思相反。"}, {"text": "他的表情这次明显受污了。", "explanation": "这里应该用〈变化〉。受污指受到污染或玷污，不用来说表情的变化。"}, {"text": "他的收入这个月受污了不少。", "explanation": "这里应该用〈减少〉或〈增加〉。受污指受到污染，不用来说收入的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13435, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片湿地受污很厉害，鸟类都飞走了。", "corrected_sentence": "这片湿地受污得很厉害，鸟类都飞走了。", "error_description": "补语错误：“受污”后带程度补语，要用“得”连接，应说“受污得很厉害”，不说“受污很厉害”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13435, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条小溪被受污了，鱼虾都不见了。", "corrected_sentence": "这条小溪受污了，鱼虾都不见了。", "error_description": "错误：「受」本身已表被动，前面不能再加「被」，属于赘余。正确：「这条小溪受污了，鱼虾都不见了。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13437, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
