INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13438, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13438, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "经济学是研究社会如何管理有限资源，进行生产、分配和消费的学科。", "primary_collocate": null, "pronunciation": "jīng jì xué", "ipa": "tɕiŋ˥ tɕi˥˩ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "这不仅是一场关于清洁技术的革新，更是一场涉及伦理、经济学与生态哲学的深层对话：在增长的极限与美的短暂性之间，人类是否能够构建一种既尊重自然律动又不失审美尊严的可持续美学？", "target_word": "经济学", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我哥哥在大学学经济学。", "target_word": "经济学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "经济学研究资源怎样分配。", "target_word": "经济学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她对经济学很有兴趣，常常看相关的书。", "target_word": "经济学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济学老师今天讲了价格和需求。", "target_word": "经济学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本经济学书太难，我看不懂。", "target_word": "经济学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学了经济学以后，他更会管钱了。", "target_word": "经济学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济学告诉我们，资源总是有限的。", "target_word": "经济学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想考经济学的研究生。", "target_word": "经济学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "经济学里有一个常见的词，叫需求。", "target_word": "经济学", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "经济学家", "label": "复合"}], "register": "中性", "sense_fingerprint": "经济学：研究资源的生产、分配和消费的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cad2001-2aa4-4510-ac23-f965c31811d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13438, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经济学", "is_correct": true, "explanation": "“经济学”是研究资源生产、分配和消费的学科，与“伦理”“生态哲学”并列，语义吻合。"}, {"text": "服装", "is_correct": false, "explanation": "语义：服装不是学科，无法与“伦理”“生态哲学”并列为学科。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：“烹饪”不宜与“伦理、…与生态哲学”并列，列举的应是学科名称。"}, {"text": "美食", "is_correct": false, "explanation": "语义：美食是饮食，不是学科，与“伦理”“生态哲学”不构成并列。"}], "explanations": {"经济学": "“经济学”是研究资源生产、分配和消费的学科，与“伦理”“生态哲学”并列，语义吻合。", "服装": "语义：服装不是学科，无法与“伦理”“生态哲学”并列为学科。", "烹饪": "搭配：“烹饪”不宜与“伦理、…与生态哲学”并列，列举的应是学科名称。", "美食": "语义：美食是饮食，不是学科，与“伦理”“生态哲学”不构成并列。"}, "sentence_index": 0, "correct_answer": "经济学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家的经济学总产值每年增长百分之五。", "explanation": "这里应该用〈经济〉。“经济学”是学科名，不能计算产值或增长率；说国家的经济增长要用“经济”。"}, {"text": "这个地区的经济学人均收入很高。", "explanation": "这里应该用〈经济〉。“经济学”是学科名，不能说人均收入；说地区的经济水平要用“经济”。"}, {"text": "这本书讲了三碗经济学。", "explanation": "“经济学”作学科时不用“碗”作量词；讲授的内容应以“门”或“种”来计数，这里的量词用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13438, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经济学", "is_correct": true, "explanation": "“学了经济学”之后“更会管钱”，前后语义直接相连。"}, {"text": "体育", "is_correct": false, "explanation": "语义：学体育与“更会管钱”之间没有语义联系，句子的因果不成立。"}, {"text": "美术", "is_correct": false, "explanation": "搭配：“学了美术”之后“更会管钱”的说法不通，与“管钱”的语境脱节。"}, {"text": "园艺", "is_correct": false, "explanation": "语义：园艺与管理钱财无关，无法引出“更会管钱”的结果。"}], "explanations": {"经济学": "“学了经济学”之后“更会管钱”，前后语义直接相连。", "体育": "语义：学体育与“更会管钱”之间没有语义联系，句子的因果不成立。", "美术": "搭配：“学了美术”之后“更会管钱”的说法不通，与“管钱”的语境脱节。", "园艺": "语义：园艺与管理钱财无关，无法引出“更会管钱”的结果。"}, "sentence_index": 6, "correct_answer": "经济学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位经济学很聪明，大家都很佩服他。", "explanation": "这里应该用〈经济学家〉。“经济学”是学科名，指人时要说“经济学家”。"}, {"text": "这家公司今年的经济学业绩很好。", "explanation": "这里应该用〈经济〉。“经济学”是学科名，说公司的经济效益、业绩要用“经济”。"}, {"text": "他研究了一把经济学。", "explanation": "“经济学”作学科时不用“把”作量词，这里的量词与它不搭，应说“一门”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13438, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹大学学的是一本经济学。", "corrected_sentence": "我妹妹大学学的是一门经济学。", "error_description": "“经济学”作学科时量词应用“门”，写成“一本经济学”量词用错，应改为“一门经济学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13438, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老师教过经济学过二十年。", "corrected_sentence": "这位老师教过经济学二十年。", "error_description": "“过”表示经历，已紧跟在动词“教”之后，句末又多出一个“过”，重复了，应删去，写作“教过经济学二十年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
