INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13439, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13439, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两人或多人互相交谈。", "primary_collocate": null, "pronunciation": "duì huà", "ipa": "tuei˥˩ xua˥˩", "syllable_count": 2, "sentences": [{"text": "这不仅是一场关于清洁技术的革新，更是一场涉及伦理、经济学与生态哲学的深层对话：在增长的极限与美的短暂性之间，人类是否能够构建一种既尊重自然律动又不失审美尊严的可持续美学？", "target_word": "对话", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "两国领导人进行了一次友好的对话。", "target_word": "对话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和学生之间需要多一些对话。", "target_word": "对话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母与孩子的对话越来越少。", "target_word": "对话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场对话持续了两个小时。", "target_word": "对话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同文化之间的对话很重要。", "target_word": "对话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方通过对话解决了问题。", "target_word": "对话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司和员工开始了平等的对话。", "target_word": "对话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有对话，才能减少误会。", "target_word": "对话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民和政府的对话明天举行。", "target_word": "对话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场对话", "label": "量词"}], "register": "通用", "sense_fingerprint": "两方或多方之间的交谈与沟通", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc48de5a-e0a4-461a-9d2c-5287d6870dbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13439, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”指闲话，口语色彩强，与这段学术化的哲学论述不协调。"}, {"text": "面料", "is_correct": false, "explanation": "搭配：“一场……面料”不成搭配，“面料”指布料，与“深层”和哲学内容无关。"}, {"text": "账单", "is_correct": false, "explanation": "语义：“账单”指费用清单，不是涉及哲学思辨的交流，句意不通。"}, {"text": "对话", "is_correct": true, "explanation": "“对话”指两方或多方的交流讨论，与“深层”和后文的思想探讨相合。"}], "explanations": {"八卦": "语域：“八卦”指闲话，口语色彩强，与这段学术化的哲学论述不协调。", "面料": "搭配：“一场……面料”不成搭配，“面料”指布料，与“深层”和哲学内容无关。", "账单": "语义：“账单”指费用清单，不是涉及哲学思辨的交流，句意不通。", "对话": "“对话”指两方或多方的交流讨论，与“深层”和后文的思想探讨相合。"}, "sentence_index": 0, "correct_answer": "对话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "同学们在课堂上对话了这道数学题。", "explanation": "这里应该用〈讨论〉。“对话”指两人或多人互相谈话，不能直接带“这道数学题”这样的宾语。"}, {"text": "父母与孩子进行了一把对话，很有收获。", "explanation": "这里应该用〈场〉或〈次〉。“把”用于有柄的器具，不能用来计量“对话”。"}, {"text": "我们对话了学习的体会。", "explanation": "这里应该用〈交流〉。“对话”是互相谈话，不能直接带“学习的体会”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13439, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是视觉属性，不能用来解决问题，句意不通。"}, {"text": "字体", "is_correct": false, "explanation": "搭配：“通过字体”不能解决问题，“字体”只指字的形状。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：“闹钟”是器具，不能作为解决问题的方式，句意不通。"}, {"text": "对话", "is_correct": true, "explanation": "“对话”指交流沟通，双方通过它解决问题，符合句意。"}], "explanations": {"颜色": "语义：“颜色”是视觉属性，不能用来解决问题，句意不通。", "字体": "搭配：“通过字体”不能解决问题，“字体”只指字的形状。", "闹钟": "语义：“闹钟”是器具，不能作为解决问题的方式，句意不通。", "对话": "“对话”指交流沟通，双方通过它解决问题，符合句意。"}, "sentence_index": 6, "correct_answer": "对话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市民和政府的一幅对话明天举行。", "explanation": "这里应该用〈场〉或〈次〉。“幅”用于画或布，不能计量“对话”。"}, {"text": "两家公司正在对话这份合同。", "explanation": "这里应该用〈谈判〉。“对话”指两人或多人互相谈话，不能直接带“这份合同”作宾语。"}, {"text": "市民和政府的一只对话明天举行。", "explanation": "这里应该用〈场〉或〈次〉。“只”用于动物或成对的物品，不能计量“对话”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13439, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把对话的结果让双方都很满意。", "corrected_sentence": "这次对话的结果让双方都很满意。", "error_description": "量词错误：“对话”前应用“次”，不能用“把”。“把”用于有柄的器具，不能计量“对话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13439, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国的一座对话明天在北京举行。", "corrected_sentence": "两国的一次对话明天在北京举行。", "error_description": "量词错误：“对话”前应用“次”，不能用“座”。“座”用于建筑、山等大型固定之物，不能计量“对话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
