INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13441, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物发展所能达到的最高程度或最大范围。", "primary_collocate": null, "pronunciation": "jí xiàn", "ipa": "tɕi˧˥ ɕiɛn˥˩", "syllable_count": 2, "sentences": [{"text": "此后四十年间，材料科学的迭代推动光伏技术进入指数级进化：多结叠层电池突破光谱响应极限，钙钛矿材料以其低廉成本与柔性特质颠覆传统制造逻辑，而双面组件设计更通过地面反射光捕获使发电量提升20%以上。", "target_word": "极限", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这不仅是一场关于清洁技术的革新，更是一场涉及伦理、经济学与生态哲学的深层对话：在增长的极限与美的短暂性之间，人类是否能够构建一种既尊重自然律动又不失审美尊严的可持续美学？", "target_word": "极限", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "跑了十公里，他已经到了身体的极限。", "target_word": "极限", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆车的速度已经达到了极限。", "target_word": "极限", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想挑战自己的极限。", "target_word": "极限", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每个人的耐心都有极限。", "target_word": "极限", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "运动员用尽全力，想突破速度的极限。", "target_word": "极限", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他工作了三天三夜，已经超过了极限。", "target_word": "极限", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人的记忆力也有极限，别一次背太多。", "target_word": "极限", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气太热，他的体力快到极限了。", "target_word": "极限", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "事物发展所能达到的最高程度或最大范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07a53c-a9cf-4bf8-a96d-3c0a8dd8e503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13441, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "极限", "is_correct": true, "explanation": "正确。“突破光谱响应极限”指响应能达到的最高程度，与句意一致。"}, {"text": "体积", "is_correct": false, "explanation": "语义：“体积”指物体占据的空间大小，与光谱响应的范围无关，句中说的是最高程度。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”只用于人或拟人对象，不能说“光谱响应的性格”。"}, {"text": "底细", "is_correct": false, "explanation": "语域：“底细”是口语词，与本句的书面语体不合，且“光谱响应的底细”不成立。"}], "explanations": {"极限": "正确。“突破光谱响应极限”指响应能达到的最高程度，与句意一致。", "体积": "语义：“体积”指物体占据的空间大小，与光谱响应的范围无关，句中说的是最高程度。", "性格": "搭配：“性格”只用于人或拟人对象，不能说“光谱响应的性格”。", "底细": "语域：“底细”是口语词，与本句的书面语体不合，且“光谱响应的底细”不成立。"}, "sentence_index": 0, "correct_answer": "极限"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河是两个省的极限。", "explanation": "这里应该用〈界限〉。“极限”指能达到的最高程度，两省之间的分界要说“界限”。"}, {"text": "这场比赛的极限是下午三点。", "explanation": "这里应该用〈期限〉。“极限”指最高程度，不指规定的截止时间，截止时间要说“期限”。"}, {"text": "这份合同的极限是两年，到期要重新签。", "explanation": "这里应该用〈年限〉。“极限”指最高程度，合同有效的年数要说“年限”，不能说“极限”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13441, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "极限", "is_correct": true, "explanation": "正确。“想突破速度的极限”指速度能达到的最高程度，与句意一致。"}, {"text": "方向", "is_correct": false, "explanation": "语义：“方向”指朝向，句中突破的是能达到的最高程度，不能突破“方向”。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”只用于人或生物，不说“速度的年龄”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与速度无关，句中说的是运动员能达到的最高程度。"}], "explanations": {"极限": "正确。“想突破速度的极限”指速度能达到的最高程度，与句意一致。", "方向": "语义：“方向”指朝向，句中突破的是能达到的最高程度，不能突破“方向”。", "年龄": "搭配：“年龄”只用于人或生物，不说“速度的年龄”。", "颜色": "语义：“颜色”与速度无关，句中说的是运动员能达到的最高程度。"}, "sentence_index": 6, "correct_answer": "极限"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场演出的极限是晚上八点。", "explanation": "这里应该用〈开场〉。“极限”指最高程度，不指演出开始的时间，那要说“开场”。"}, {"text": "这次比赛的极限是一个金奖杯。", "explanation": "这里应该用〈奖杯〉。“极限”指最高程度或最大范围，不指比赛的奖品，奖品要说“奖杯”。"}, {"text": "这个房间的极限摆着一张桌子。", "explanation": "这里应该用〈中央〉。“极限”指最高程度，不指位置的正中间，那要说“中央”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13441, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器的负荷已经快到一只极限了。", "corrected_sentence": "这台机器的负荷已经快到极限了。", "error_description": "错误形式：“快到一只极限了”；正确形式：“快到极限了”。“极限”是抽象名词，计量时不用“只”，这里直接说“到极限”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13441, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台电脑的内存已经用到极限着。", "corrected_sentence": "这台电脑的内存已经用到极限了。", "error_description": "体标错误：“用到极限”表示完成时应用“了”，不能用“着”，应说“用到极限了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13443, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "永久性", "is_correct": true, "explanation": "反义：“永久性”指长久不变的特点，与“短暂性”的持续时间短正相反。"}, {"text": "体积", "is_correct": false, "explanation": "无关：“体积”指物体所占的空间，与时间长短无关。"}, {"text": "重量", "is_correct": false, "explanation": "无关：“重量”指物体的轻重，与时间长短无关。"}, {"text": "形状", "is_correct": false, "explanation": "无关：“形状”指物体的外形，与时间长短无关。"}], "correct_answer": "永久性", "explanations": {"永久性": "反义：“永久性”指长久不变的特点，与“短暂性”的持续时间短正相反。", "体积": "无关：“体积”指物体所占的空间，与时间长短无关。", "重量": "无关：“重量”指物体的轻重，与时间长短无关。", "形状": "无关：“形状”指物体的外形，与时间长短无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13443, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "永久性", "is_correct": true, "explanation": "反义：“永久性”指长久不变，与“短暂性”的持续时间短正相反。"}, {"text": "硬度", "is_correct": false, "explanation": "无关：“硬度”指物体抵抗压力的程度，与时间长短无关。"}, {"text": "温度", "is_correct": false, "explanation": "无关：“温度”指冷热的程度，与时间长短无关。"}, {"text": "亮度", "is_correct": false, "explanation": "无关：“亮度”指光线的明暗程度，与时间长短无关。"}], "correct_answer": "永久性", "explanations": {"永久性": "反义：“永久性”指长久不变，与“短暂性”的持续时间短正相反。", "硬度": "无关：“硬度”指物体抵抗压力的程度，与时间长短无关。", "温度": "无关：“温度”指冷热的程度，与时间长短无关。", "亮度": "无关：“亮度”指光线的明暗程度，与时间长短无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13443, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "表示某种状态或情况持续的时间很短。", "primary_collocate": null, "pronunciation": "duǎn zàn xìng", "ipa": "tuan˨˩˦ tsan˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这不仅是一场关于清洁技术的革新，更是一场涉及伦理、经济学与生态哲学的深层对话：在增长的极限与美的短暂性之间，人类是否能够构建一种既尊重自然律动又不失审美尊严的可持续美学？", "target_word": "短暂性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "花开的短暂性让人珍惜。", "target_word": "短暂性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她明白青春的短暂性。", "target_word": "短暂性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "烟花的短暂性正是它的美。", "target_word": "短暂性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想到疼痛的短暂性，他稍微安心了。", "target_word": "短暂性", "complexity_tier": "T3", "furigana": "xiǎng dào téng tòng de duǎnzàn xìng, tā shāowēi ānxīn le.", "sentence_source": "generated"}, {"text": "我们要接受生命的短暂性。", "target_word": "短暂性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影让人看到了幸福的短暂性。", "target_word": "短暂性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雪花落地就化，这说明了它的短暂性。", "target_word": "短暂性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他写了一首诗，说的是梦的短暂性。", "target_word": "短暂性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "彩虹出现的时间很短，这就是它的短暂性。", "target_word": "短暂性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "短暂性：某种状态或情况持续时间很短的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cad2001-2aa4-4510-ac23-f965c31811d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13443, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "短暂性", "is_correct": true, "explanation": "正确：“短暂性”指持续时间短的特点，与前文“增长的极限”形成对照，指美的转瞬即逝。"}, {"text": "货币", "is_correct": false, "explanation": "语义：“货币”指流通的钱，与“美”不能构成抽象的对照。"}, {"text": "劲头", "is_correct": false, "explanation": "语域：“劲头”是口语词，与这段哲学式书面论述的语域不协调。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”只说身体的重量，不能与抽象的“美”并列对比。"}], "explanations": {"短暂性": "正确：“短暂性”指持续时间短的特点，与前文“增长的极限”形成对照，指美的转瞬即逝。", "货币": "语义：“货币”指流通的钱，与“美”不能构成抽象的对照。", "劲头": "语域：“劲头”是口语词，与这段哲学式书面论述的语域不协调。", "体重": "体貌：“体重”只说身体的重量，不能与抽象的“美”并列对比。"}, "sentence_index": 0, "correct_answer": "短暂性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子的短暂性很大，住了很多人。", "explanation": "这里应该用〈面积〉。“短暂性”只说持续时间很短的特点，不能形容房屋的大小；说房子的大小要用“面积”。"}, {"text": "这根绳子的短暂性有两米。", "explanation": "这里的“短暂性”被用来指长度，但它只指持续时间很短，不能用来描述物体的长短。"}, {"text": "我想起那只短暂性，心里有些失落。", "explanation": "量词错误：“只”多用于动物或小件器物，“短暂性”是抽象性质，应搭配“种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13443, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "短暂性", "is_correct": true, "explanation": "正确：“短暂性”指幸福的持续时间短，与“看到了幸福的”搭配，语义相符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”只说人的高矮，不能用来描述“幸福”这样的抽象事物。"}, {"text": "声调", "is_correct": false, "explanation": "搭配：“声调”指语音的高低变化，不能与“幸福”搭配。"}, {"text": "口音", "is_correct": false, "explanation": "语义：“口音”指说话的地方特点，与幸福的时间长短无关。"}], "explanations": {"短暂性": "正确：“短暂性”指幸福的持续时间短，与“看到了幸福的”搭配，语义相符。", "身高": "体貌：“身高”只说人的高矮，不能用来描述“幸福”这样的抽象事物。", "声调": "搭配：“声调”指语音的高低变化，不能与“幸福”搭配。", "口音": "语义：“口音”指说话的地方特点，与幸福的时间长短无关。"}, "sentence_index": 6, "correct_answer": "短暂性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场演出的短暂性是两小时。", "explanation": "这里应该用〈时长〉。〈短暂性〉只说持续时间短的特点，不用来报告具体的时间数量。"}, {"text": "我们努力缩短这段友谊的短暂性。", "explanation": "搭配错误：〈短暂性〉是性质，不能被“缩短”，要缩短的是时间本身，而不是它的特点。"}, {"text": "这一颗短暂性让我想起了童年。", "explanation": "量词错误：“颗”多用于圆形的小物，“短暂性”是抽象性质，应搭配“种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13443, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部电影短暂性让人难忘。", "corrected_sentence": "这部电影的短暂性让人难忘。", "error_description": "助词错误：“短暂性”作定语时要用“的”连接，“这部电影短暂性”不成立，应说“这部电影的短暂性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13443, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在这首诗里发现了一条短暂性。", "corrected_sentence": "他在这首诗里发现了一种短暂性。", "error_description": "量词错误：“短暂性”是抽象性质名词，应搭配“种”，不能用“条”（“条”多用于细长的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13445, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
