INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13445, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指有节奏地运动或变化，常用来形容音乐、舞蹈或身体动作的韵律感。", "primary_collocate": null, "pronunciation": "lǜ dòng", "ipa": "ly˥˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这不仅是一场关于清洁技术的革新，更是一场涉及伦理、经济学与生态哲学的深层对话：在增长的极限与美的短暂性之间，人类是否能够构建一种既尊重自然律动又不失审美尊严的可持续美学？", "target_word": "律动", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这首歌的律动很强。", "target_word": "律动", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我喜欢海浪的律动。", "target_word": "律动", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "音乐的律动让人想跳舞。", "target_word": "律动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天里，大自然充满了律动。", "target_word": "律动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用身体表现出音乐的律动。", "target_word": "律动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市的夜晚有自己的律动。", "target_word": "律动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这幅画里有一种安静的律动。", "target_word": "律动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鼓声给这段音乐带来了律动。", "target_word": "律动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "舞者随着鼓点起伏，身体的律动十分自然。", "target_word": "律动", "complexity_tier": "T3", "furigana": "wǔ zhě suí zhe gǔ diǎn qǐ fú, shēn tǐ de lǜ dòng shí fēn zì rán.", "sentence_source": "generated"}, {"text": "舞蹈老师说要先感受音乐的律动。", "target_word": "律动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "律动感", "label": "复合"}], "register": "书面", "sense_fingerprint": "音乐、舞蹈或自然中有节奏的运动与变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f3ad525-ec43-4f5b-948b-9899e9b8bc3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13445, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "律动", "is_correct": true, "explanation": "正确：“自然律动”指自然界有节奏的运动与变化，与“生态哲学”“审美尊严”的语境相呼应。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：噪音是嘈杂杂乱的声音，与“审美尊严”“美学”的语境相抵触，“尊重自然噪音”说不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“尊重”的对象可以是自然，但“价格”是经济上的标价，“尊重自然价格”搭配不当。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与这句书面语体及学术语境不相称，“尊重自然玩意儿”也不通。"}], "explanations": {"律动": "正确：“自然律动”指自然界有节奏的运动与变化，与“生态哲学”“审美尊严”的语境相呼应。", "噪音": "语义：噪音是嘈杂杂乱的声音，与“审美尊严”“美学”的语境相抵触，“尊重自然噪音”说不通。", "价格": "搭配：“尊重”的对象可以是自然，但“价格”是经济上的标价，“尊重自然价格”搭配不当。", "玩意儿": "语域：“玩意儿”是口语说法，与这句书面语体及学术语境不相称，“尊重自然玩意儿”也不通。"}, "sentence_index": 0, "correct_answer": "律动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在台上露出一个漂亮的律动，大家都看呆了。", "explanation": "这里应该用〈笑容〉。“露出”搭配的是表情或神色，律动指有节奏的运动或韵律感，不能被“露出”。"}, {"text": "这把椅子的律动很牢固。", "explanation": "这里应该用〈牢固〉。律动指有节奏的运动或韵律感，椅子坚固的程度要用〈牢固〉，不能说“律动”。"}, {"text": "这段音乐有一块律动。", "explanation": "这里应该用〈种〉。“块”用于有形的块状物，不能用来数抽象的律动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13445, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "律动", "is_correct": true, "explanation": "正确：“有自己的律动”指夜晚城市特有的节奏与起伏，与“城市的夜晚”的语境吻合。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的体貌特征，不能用来描述城市的夜晚。"}, {"text": "户口", "is_correct": false, "explanation": "语义：“户口”是户籍登记，与夜晚的城市氛围无关，句子说不通。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“有自己的”后接的是属性或特点，“考试”是活动，搭配不当。"}], "explanations": {"律动": "正确：“有自己的律动”指夜晚城市特有的节奏与起伏，与“城市的夜晚”的语境吻合。", "身高": "体貌：“身高”是人的体貌特征，不能用来描述城市的夜晚。", "户口": "语义：“户口”是户籍登记，与夜晚的城市氛围无关，句子说不通。", "考试": "搭配：“有自己的”后接的是属性或特点，“考试”是活动，搭配不当。"}, "sentence_index": 6, "correct_answer": "律动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鼓手一直在打律动。", "explanation": "这里应该用〈节拍〉。“打节拍”是常见搭配，律动指有节奏的运动，不能被“打”。"}, {"text": "他是一个很高大的律动。", "explanation": "这里应该用〈人〉。律动指有节奏的运动或韵律感，是抽象的，不能用来指人。"}, {"text": "这段旋律里有一根律动。", "explanation": "这里应该用〈种〉。“根”用于细长的东西，不能用来数抽象的律动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13445, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海浪有一朵独特的律动。", "corrected_sentence": "海浪有一种独特的律动。", "error_description": "量词错误：“律动”是抽象的韵律，不能用“朵”（“朵”用于花、云等）来数，应说“一种独特的律动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13445, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这段低音让歌曲有了清晰的律动们。", "corrected_sentence": "这段低音让歌曲有了清晰的律动。", "error_description": "“律动”是抽象名词，不能加复数词尾“们”（“们”只用于指人）。应改为“清晰的律动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
