INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13446, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "表示不会失去或没有丧失", "primary_collocate": null, "pronunciation": "bù shī", "ipa": "pu˥˩ ʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "这不仅是一场关于清洁技术的革新，更是一场涉及伦理、经济学与生态哲学的深层对话：在增长的极限与美的短暂性之间，人类是否能够构建一种既尊重自然律动又不失审美尊严的可持续美学？", "target_word": "不失", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他输了比赛，但是不失风度。", "target_word": "不失", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她拒绝了我，可是说话不失礼貌。", "target_word": "不失", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师批评学生时，态度仍不失耐心。", "target_word": "不失", "complexity_tier": "T3", "furigana": "lǎoshī pīpíng xuésheng shí, tàidù réng bù shī nàixīn", "sentence_source": "generated"}, {"text": "他虽然很忙，却不失幽默。", "target_word": "不失", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她换了新工作，还是不失热情。", "target_word": "不失", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店很小，但服务不失水准。", "target_word": "不失", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人经历过很多事，依然不失童心。", "target_word": "不失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对失败，他依然不失信心。", "target_word": "不失", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他当了经理，却不失普通人的本色。", "target_word": "不失", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不失为", "label": "复合"}], "register": "书面语", "sense_fingerprint": "不失：后接风度、礼貌等好品质，表示保持着，没有丧失", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cad2001-2aa4-4510-ac23-f965c31811d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13446, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不失", "is_correct": true, "explanation": "bù shī：没有丧失，保持着某种好品质，是本题的目标词。"}, {"text": "不时", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，意思是常常、时常。"}, {"text": "不是", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，意思是否定判断，并非如此。"}, {"text": "不适", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，意思是身体或感觉不舒服。"}, {"text": "不死", "is_correct": false, "explanation": "sǐ（第三声）与 shī（第一声）声母不同（s 对 sh）、声调也不同，意思是不会死亡。"}, {"text": "不使", "is_correct": false, "explanation": "shǐ（第三声）与 shī（第一声）声调不同，意思是不用、不让。"}], "explanations": {"不失": "bù shī：没有丧失，保持着某种好品质，是本题的目标词。", "不时": "shí（第二声）与 shī（第一声）声调不同，意思是常常、时常。", "不是": "shì（第四声）与 shī（第一声）声调不同，意思是否定判断，并非如此。", "不适": "shì（第四声）与 shī（第一声）声调不同，意思是身体或感觉不舒服。", "不死": "sǐ（第三声）与 shī（第一声）声母不同（s 对 sh）、声调也不同，意思是不会死亡。", "不使": "shǐ（第三声）与 shī（第一声）声调不同，意思是不用、不让。"}, "sentence_index": null, "correct_answer": "不失"}, "level_3": {"options": [{"text": "不失", "is_correct": true, "explanation": "“不失”表示保持着好品质，与“既尊重…又…”的并列结构相合。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：“忽视”是不重视，与“既尊重自然律动”的并列语义相反，说“又忽视审美尊严”会与可持续美学的理想冲突。"}, {"text": "违背", "is_correct": false, "explanation": "搭配：“违背”多接原则、规律，接“审美尊严”别扭，且与“可持续”的追求相反。"}, {"text": "失去", "is_correct": false, "explanation": "语义：“失去”表示丢掉，与“可持续美学”的目标相悖，整句读来不成立。"}], "explanations": {"不失": "“不失”表示保持着好品质，与“既尊重…又…”的并列结构相合。", "忽视": "语义：“忽视”是不重视，与“既尊重自然律动”的并列语义相反，说“又忽视审美尊严”会与可持续美学的理想冲突。", "违背": "搭配：“违背”多接原则、规律，接“审美尊严”别扭，且与“可持续”的追求相反。", "失去": "语义：“失去”表示丢掉，与“可持续美学”的目标相悖，整句读来不成立。"}, "sentence_index": 0, "correct_answer": "不失"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很不失，大家都喜欢和他交朋友。", "explanation": "这里是词性错误：“不失”是动词，不能用“很”修饰作谓语来形容人；形容人应说“很有风度”。"}, {"text": "会议上他的不失让大家都很佩服。", "explanation": "这里是词性错误：“不失”是动词，不能加“的”变成名词作主语；应说“他的风度让大家都很佩服”。"}, {"text": "我们不失得很远。", "explanation": "这里是补语错误：“不失”是动词，不接程度补语“得”；说走得远要用“走”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13446, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不失", "is_correct": true, "explanation": "bù shī：没有丧失，保持着某种好品质，是本题的目标词。"}, {"text": "不知", "is_correct": false, "explanation": "zhī（第一声）与 shī（第一声）声母不同（zh 对 sh），意思是不晓得。"}, {"text": "不吃", "is_correct": false, "explanation": "chī（第一声）与 shī（第一声）声母不同（ch 对 sh），意思是不进食。"}, {"text": "不思", "is_correct": false, "explanation": "sī（第一声）与 shī（第一声）声母不同（s 对 sh），意思是不去想。"}, {"text": "补时", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）、shí（第二声）与 shī（第一声）声调都不同，意思是补充的时间，多指比赛中补加的时间。"}, {"text": "不识", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，意思是不认识。"}], "explanations": {"不失": "bù shī：没有丧失，保持着某种好品质，是本题的目标词。", "不知": "zhī（第一声）与 shī（第一声）声母不同（zh 对 sh），意思是不晓得。", "不吃": "chī（第一声）与 shī（第一声）声母不同（ch 对 sh），意思是不进食。", "不思": "sī（第一声）与 shī（第一声）声母不同（s 对 sh），意思是不去想。", "补时": "bǔ（第三声）与 bù（第四声）、shí（第二声）与 shī（第一声）声调都不同，意思是补充的时间，多指比赛中补加的时间。", "不识": "shí（第二声）与 shī（第一声）声调不同，意思是不认识。"}, "sentence_index": null, "correct_answer": "不失"}, "level_3": {"options": [{"text": "不失", "is_correct": true, "explanation": "“不失水准”表示没有降低标准，与“但”后面的正面转折相合。"}, {"text": "丢掉", "is_correct": false, "explanation": "语义：“丢掉”表示失去，与“但”引出的正面转折相反，句意不通。"}, {"text": "忽略", "is_correct": false, "explanation": "语义：“忽略”是不注意，与“服务”后面的评价不相符，无法体现转折语义。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”表示主动舍去，与“但”引出的正面转折相反，句意不通。"}], "explanations": {"不失": "“不失水准”表示没有降低标准，与“但”后面的正面转折相合。", "丢掉": "语义：“丢掉”表示失去，与“但”引出的正面转折相反，句意不通。", "忽略": "语义：“忽略”是不注意，与“服务”后面的评价不相符，无法体现转折语义。", "放弃": "语义：“放弃”表示主动舍去，与“但”引出的正面转折相反，句意不通。"}, "sentence_index": 6, "correct_answer": "不失"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支球队很不失，球迷都很满意。", "explanation": "这里是词性错误：“不失”是动词，不能用“很”修饰作谓语来评价球队；评价球队可说“很稳定”。"}, {"text": "这位医生很仔细，他的不失很让病人放心。", "explanation": "这里是词性错误：“不失”是动词，不能加“的”变成名词作主语；应说“他的态度很让病人放心”。"}, {"text": "他坚持每天跑步，心率很不失。", "explanation": "这里是词性错误：“不失”是动词，不能用“很”修饰心率；描述心率应说“很稳定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13446, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在争论中败下阵来，仍然不失了风度。", "corrected_sentence": "他在争论中败下阵来，仍然不失风度。", "error_description": "“不失”表示持续保持某种品质，后面不加动态助词“了”，此处多出“了”，应删去，写作“仍然不失风度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13446, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老人见过大风大浪，仍不失了童心。", "corrected_sentence": "这位老人见过大风大浪，仍不失童心。", "error_description": "“不失”表示持续保持某种品质，是状态动词，后面不接动态助词“了”；此处多出“了”，应删去，写作“仍不失童心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
