INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13447, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13447, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指对美的欣赏、鉴别和判断的能力或活动。", "primary_collocate": null, "pronunciation": "shěn měi", "ipa": "ʂən˨˩ meɪ˨˩", "syllable_count": 2, "sentences": [{"text": "这不仅是一场关于清洁技术的革新，更是一场涉及伦理、经济学与生态哲学的深层对话：在增长的极限与美的短暂性之间，人类是否能够构建一种既尊重自然律动又不失审美尊严的可持续美学？", "target_word": "审美", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "每个人的审美都不一样。", "target_word": "审美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的审美要从小培养。", "target_word": "审美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的审美很特别，穿衣服总是很好看。", "target_word": "审美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的设计符合年轻人的审美。", "target_word": "审美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个时代都有不同的审美。", "target_word": "审美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个国家的审美差别很大。", "target_word": "审美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的审美和我的完全不同，所以我们常常吵架。", "target_word": "审美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的审美变化得很快。", "target_word": "审美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买衣服时，我更相信自己的审美。", "target_word": "审美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种颜色不合我的审美。", "target_word": "审美", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "审美观", "label": "复合"}, {"form": "审美疲劳", "label": "复合"}], "register": "书面", "sense_fingerprint": "对美的欣赏、鉴别和判断的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f3ad525-ec43-4f5b-948b-9899e9b8bc3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13447, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "审美", "is_correct": true, "explanation": "正确：“审美尊严”指在鉴赏美的活动中应有的尊重与价值，与“美学”的语境吻合。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“尊严”前接的是人或文化的属性，“价格”是经济标价，“不失价格尊严”搭配不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指气象状况，与“尊严”“美学”的语义不相关，句子说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的体貌特征，与美学、尊严的语境不相容。"}], "explanations": {"审美": "正确：“审美尊严”指在鉴赏美的活动中应有的尊重与价值，与“美学”的语境吻合。", "价格": "搭配：“尊严”前接的是人或文化的属性，“价格”是经济标价，“不失价格尊严”搭配不通。", "天气": "语义：“天气”指气象状况，与“尊严”“美学”的语义不相关，句子说不通。", "身高": "体貌：“身高”是人的体貌特征，与美学、尊严的语境不相容。"}, "sentence_index": 0, "correct_answer": "审美"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的审美是画画和弹钢琴。", "explanation": "这里应该用〈爱好〉。“审美”指对美的鉴赏能力或标准，不指具体做的事，不能说“审美是画画”。"}, {"text": "她在审美一张发票，看看金额对不对。", "explanation": "这里应该用〈核对〉。审美指感受和判断美，不是核对票据的意思，不能用于发票。"}, {"text": "她有一条很特别的审美。", "explanation": "这里应该用〈种〉。“条”用于长条形的事物，不能用来数抽象的审美。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13447, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "审美", "is_correct": true, "explanation": "正确：“审美”指对美的鉴赏标准或能力，两国之间可以比较其差别，与语境吻合。"}, {"text": "心跳", "is_correct": false, "explanation": "语义：“心跳”是人体的生理活动，用来比较两个国家的差异不合逻辑。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”属于人的身体特征，不能用来比较国家之间的差别。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的温度，与国家之间的差异无关，句子说不通。"}], "explanations": {"审美": "正确：“审美”指对美的鉴赏标准或能力，两国之间可以比较其差别，与语境吻合。", "心跳": "语义：“心跳”是人体的生理活动，用来比较两个国家的差异不合逻辑。", "体重": "体貌：“体重”属于人的身体特征，不能用来比较国家之间的差别。", "体温": "语义：“体温”指身体的温度，与国家之间的差异无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "审美"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的审美很灵敏，一尝就能分出菜里的盐。", "explanation": "这里应该用〈味觉〉。审美指对美的鉴赏能力，分辨咸淡靠的是味觉，不能用“审美”。"}, {"text": "他有一把独特的审美。", "explanation": "这里应该用〈种〉。“把”用于有柄的器具，不能用来数抽象的审美。"}, {"text": "她挑选朋友的审美很准。", "explanation": "这里应该用〈眼光〉。“审美”指对美的鉴赏能力，挑选朋友看的是识人的眼力，不能用“审美”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13447, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她有一条细腻的审美。", "corrected_sentence": "她有一种细腻的审美。", "error_description": "“审美”是抽象名词，量词应用“种”，不用“条”。应改为“一种细腻的审美”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13447, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一代年轻人有自己的审美们。", "corrected_sentence": "这一代年轻人有自己的审美。", "error_description": "“审美”是抽象名词，不能加复数词尾“们”（“们”只用于指人）。应改为“自己的审美”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13448, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
