INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13450, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "隐藏、收存，不让别人发现或拿到。", "primary_collocate": null, "pronunciation": "cáng", "ipa": "tsʰɑŋ˧˥", "syllable_count": 1, "sentences": [{"text": "答案，或许就藏在对消费主义惯性的反思与对供应链正义的执着追求之中。", "target_word": "藏", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他把钱藏在床下。", "target_word": "藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫藏在桌子后面。", "target_word": "藏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们在门后藏着，等爸爸回来。", "target_word": "藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗把骨头藏起来了。", "target_word": "藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把过年的红包藏在书里。", "target_word": "藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道他把礼物藏在哪儿了。", "target_word": "藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有秘密，但不想让人知道，所以一直藏在心里。", "target_word": "藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能找到我藏的东西吗？", "target_word": "藏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小朋友玩游戏，一个藏，一个找。", "target_word": "藏", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "藏了", "label": "体标"}, {"form": "藏着", "label": "体标"}, {"form": "藏过", "label": "体标"}, {"form": "隐藏", "label": "复合"}, {"form": "躲藏", "label": "复合"}], "register": "中性", "sense_fingerprint": "藏：把人、物或心事隐蔽或收存起来，不让别人发现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cad2001-2aa4-4510-ac23-f965c31811d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13450, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "藏", "is_correct": true, "explanation": "正确：藏（cáng）表示隐藏、收存，与句中“藏在”一致。"}, {"text": "苍", "is_correct": false, "explanation": "cāng（第一声）与 cáng 声调不同，意思是青灰色、深绿色。"}, {"text": "长", "is_correct": false, "explanation": "cháng（第二声）与 cáng 声母不同（ch 与 c），意思是长短的长。"}, {"text": "蚕", "is_correct": false, "explanation": "cán（第二声）与 cáng 韵母不同（an 与 ang），意思是蚕虫。"}, {"text": "层", "is_correct": false, "explanation": "céng（第二声）与 cáng 韵母不同（eng 与 ang），意思是层次、层面。"}], "explanations": {"藏": "正确：藏（cáng）表示隐藏、收存，与句中“藏在”一致。", "苍": "cāng（第一声）与 cáng 声调不同，意思是青灰色、深绿色。", "长": "cháng（第二声）与 cáng 声母不同（ch 与 c），意思是长短的长。", "蚕": "cán（第二声）与 cáng 韵母不同（an 与 ang），意思是蚕虫。", "层": "céng（第二声）与 cáng 韵母不同（eng 与 ang），意思是层次、层面。"}, "sentence_index": null, "correct_answer": "藏"}, "level_3": {"options": [{"text": "藏", "is_correct": true, "explanation": "正确：“藏在……之中”表示隐蔽在某处，与抽象语境相合。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”指移动，答案不会跑到反思与追求之中。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不与“在……之中”搭配，不能说“唱在……之中”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能用于抽象的答案。"}], "explanations": {"藏": "正确：“藏在……之中”表示隐蔽在某处，与抽象语境相合。", "跑": "语义：“跑”指移动，答案不会跑到反思与追求之中。", "唱": "搭配：“唱”不与“在……之中”搭配，不能说“唱在……之中”。", "吃": "语义：“吃”指进食，不能用于抽象的答案。"}, "sentence_index": 0, "correct_answer": "藏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把秘密藏给了所有人。", "explanation": "这里应该用〈告诉〉。藏表示隐藏、不让别人知道，与“给所有人”的意思相矛盾。"}, {"text": "他藏开了老师的目光。", "explanation": "这里应该用〈躲〉。藏是把东西隐蔽起来；避开目光要说“躲开”，不能说“藏开”。"}, {"text": "他把礼物藏给了妈妈。", "explanation": "这里应该用〈送〉。藏表示隐蔽，不能用来表示把东西交给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13450, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "藏", "is_correct": true, "explanation": "正确：藏（cáng）表示隐藏，与句中“藏”的用法一致。"}, {"text": "仓", "is_correct": false, "explanation": "cāng（第一声）与 cáng 声调不同，意思是仓库。"}, {"text": "常", "is_correct": false, "explanation": "cháng（第二声）与 cáng 声母不同（ch 与 c），意思是经常。"}, {"text": "残", "is_correct": false, "explanation": "cán（第二声）与 cáng 韵母不同（an 与 ang），意思是残缺、残留。"}, {"text": "曾", "is_correct": false, "explanation": "céng（第二声）与 cáng 韵母不同（eng 与 ang），意思是曾经。"}], "explanations": {"藏": "正确：藏（cáng）表示隐藏，与句中“藏”的用法一致。", "仓": "cāng（第一声）与 cáng 声调不同，意思是仓库。", "常": "cháng（第二声）与 cáng 声母不同（ch 与 c），意思是经常。", "残": "cán（第二声）与 cáng 韵母不同（an 与 ang），意思是残缺、残留。", "曾": "céng（第二声）与 cáng 韵母不同（eng 与 ang），意思是曾经。"}, "sentence_index": null, "correct_answer": "藏"}, "level_3": {"options": [{"text": "藏", "is_correct": true, "explanation": "正确：“藏在哪儿”表示把东西隐蔽在某处，句意通顺。"}, {"text": "送", "is_correct": false, "explanation": "搭配：“送”后接“到哪儿”，不说“送在哪儿”。"}, {"text": "写", "is_correct": false, "explanation": "语义：礼物不能被“写”在某处，句意不通。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿，礼物不能被咬在某处。"}], "explanations": {"藏": "正确：“藏在哪儿”表示把东西隐蔽在某处，句意通顺。", "送": "搭配：“送”后接“到哪儿”，不说“送在哪儿”。", "写": "语义：礼物不能被“写”在某处，句意不通。", "咬": "语义：“咬”指用牙齿，礼物不能被咬在某处。"}, "sentence_index": 6, "correct_answer": "藏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用雨伞藏住了雨。", "explanation": "这里应该用〈挡住〉。藏是隐蔽、不让人发现；用伞遮挡雨要说“挡住”。"}, {"text": "他把门藏上了。", "explanation": "这里应该用〈锁〉。藏表示隐蔽，不能用来表示给门上锁。"}, {"text": "他把问题藏成了笑话。", "explanation": "这里应该用〈说〉。藏表示隐蔽，不能表示把问题描述成某种样子，应说“说成笑话”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13450, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把钥匙藏在抽屉了里。", "corrected_sentence": "我把钥匙藏在抽屉里了。", "error_description": "“了”误放在方位词“里”之前，应置于句末，写作“藏在抽屉里了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13450, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他手里藏了着一张纸条。", "corrected_sentence": "他手里藏着一张纸条。", "error_description": "体标错误：“了”和“着”不能同时使用；表示持续状态只用“着”，应说“藏着”，不说“藏了着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13451, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "邪恶", "is_correct": true, "explanation": "反义：“正义”指公平合理，“邪恶”指道德上极其恶劣，二者相反。"}, {"text": "语言", "is_correct": false, "explanation": "不是反义：“语言”是交流的工具，与“正义”的道理含义无关。"}, {"text": "季节", "is_correct": false, "explanation": "不是反义：“季节”指一年中气候的分段，与“正义”无关。"}, {"text": "皮鞋", "is_correct": false, "explanation": "不是反义：“皮鞋”是鞋类，与“正义”的道理含义无关。"}], "correct_answer": "邪恶", "explanations": {"邪恶": "反义：“正义”指公平合理，“邪恶”指道德上极其恶劣，二者相反。", "语言": "不是反义：“语言”是交流的工具，与“正义”的道理含义无关。", "季节": "不是反义：“季节”指一年中气候的分段，与“正义”无关。", "皮鞋": "不是反义：“皮鞋”是鞋类，与“正义”的道理含义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1249cc0b-e936-4f6d-a885-4bc9b9606521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13451, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "邪恶", "is_correct": true, "explanation": "反义：“正义”指公平合理，“邪恶”指道德上极其恶劣，二者相反。"}, {"text": "书本", "is_correct": false, "explanation": "不是反义：“书本”是印刷品，与“正义”的道理含义无关。"}, {"text": "冬天", "is_correct": false, "explanation": "不是反义：“冬天”指一年中的季节，与“正义”无关。"}, {"text": "石头", "is_correct": false, "explanation": "不是反义：“石头”是矿物，与“正义”的道理含义无关。"}], "correct_answer": "邪恶", "explanations": {"邪恶": "反义：“正义”指公平合理，“邪恶”指道德上极其恶劣，二者相反。", "书本": "不是反义：“书本”是印刷品，与“正义”的道理含义无关。", "冬天": "不是反义：“冬天”指一年中的季节，与“正义”无关。", "石头": "不是反义：“石头”是矿物，与“正义”的道理含义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1249cc0b-e936-4f6d-a885-4bc9b9606521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13451, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公平合理的道理或原则。", "primary_collocate": null, "pronunciation": "zhèng yì", "ipa": "ʈʂɤŋ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "答案，或许就藏在对消费主义惯性的反思与对供应链正义的执着追求之中。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "分配资源时，要讲正义和公平。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个判决违背了司法正义。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，正义是一种公平的原则。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "企业赚钱的同时，也要考虑环境正义。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哲学课上我们讨论了什么是正义。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "税收制度应该体现分配正义。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司对工人不公平，没有正义可言。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她研究的是国际贸易中的正义问题。", "target_word": "正义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们要求在医疗资源分配上实现正义。", "target_word": "正义", "complexity_tier": "T3", "furigana": "tā men yāo qiú zài yī liáo zī yuán fēn pèi shàng shí xiàn zhèng yì", "sentence_source": "generated"}], "morphological_forms": [{"form": "正义感", "label": "复合词"}, {"form": "正義", "label": "繁体"}], "register": "书面", "sense_fingerprint": "公平合理的原则（分配、司法、环境等领域的正义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23a895ae-04dc-425d-89b4-86e14f5ee5e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13451, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正义", "is_correct": true, "explanation": "正确答案：正义（zhèng yì），指公平合理的道理或原则。"}, {"text": "争议", "is_correct": false, "explanation": "zhēng（第一声）与 zhèng（第四声）声调不同，意思是争论、分歧。"}, {"text": "正式", "is_correct": false, "explanation": "shì 与 yì 的声母不同，意思是正规、符合规定。"}, {"text": "政治", "is_correct": false, "explanation": "zhì 与 yì 的声母不同，意思是政府管理国家的活动。"}], "explanations": {"正义": "正确答案：正义（zhèng yì），指公平合理的道理或原则。", "争议": "zhēng（第一声）与 zhèng（第四声）声调不同，意思是争论、分歧。", "正式": "shì 与 yì 的声母不同，意思是正规、符合规定。", "政治": "zhì 与 yì 的声母不同，意思是政府管理国家的活动。"}, "sentence_index": null, "correct_answer": "正义"}, "level_3": {"options": [{"text": "正义", "is_correct": true, "explanation": "正确：“供应链正义”指供应链中公平合理的分配，与句中的讨论相符。"}, {"text": "美食", "is_correct": false, "explanation": "语义：“对供应链美食的执着追求”说不通，与句中的公平讨论无关。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“供应链颜色”不成立，与句中讨论的对象不相符。"}, {"text": "距离", "is_correct": false, "explanation": "搭配：“执着追求”不能与“距离”搭配。"}], "explanations": {"正义": "正确：“供应链正义”指供应链中公平合理的分配，与句中的讨论相符。", "美食": "语义：“对供应链美食的执着追求”说不通，与句中的公平讨论无关。", "颜色": "语义：“供应链颜色”不成立，与句中讨论的对象不相符。", "距离": "搭配：“执着追求”不能与“距离”搭配。"}, "sentence_index": 0, "correct_answer": "正义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我小时候最大的正义是能去月球。", "explanation": "这里应该用〈愿望〉。正义指公平合理的道理或原则，不指心中的愿望；“最大的愿望”才能说“能去月球”。"}, {"text": "她对绘画有浓厚的正义。", "explanation": "这里应该用〈兴趣〉。“浓厚的兴趣”说的是爱好的程度；正义指公平合理的道理或原则，不能用来形容对绘画的喜爱。"}, {"text": "他的正义很高，一下就跳过了栏杆。", "explanation": "这里应该用〈弹跳〉。“弹跳很高”才是常用说法；正义指公平合理的道理或原则，不能用来形容跳得高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1249cc0b-e936-4f6d-a885-4bc9b9606521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13451, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "正义", "is_correct": true, "explanation": "正确答案：正义（zhèng yì），指公平合理的道理或原则。"}, {"text": "正宜", "is_correct": false, "explanation": "声调混淆：yí（第二声）与 yì（第四声）只差声调，意思是恰当、理应。"}, {"text": "正业", "is_correct": false, "explanation": "yè 与 yì 只差韵母，意思是正当的职业。"}, {"text": "中意", "is_correct": false, "explanation": "zhōng（第一声）与 zhèng（第四声）声调与韵母都不同，意思是满意、合心意。"}], "explanations": {"正义": "正确答案：正义（zhèng yì），指公平合理的道理或原则。", "正宜": "声调混淆：yí（第二声）与 yì（第四声）只差声调，意思是恰当、理应。", "正业": "yè 与 yì 只差韵母，意思是正当的职业。", "中意": "zhōng（第一声）与 zhèng（第四声）声调与韵母都不同，意思是满意、合心意。"}, "sentence_index": null, "correct_answer": "正义"}, "level_3": {"options": [{"text": "正义", "is_correct": true, "explanation": "正确：“分配正义”指资源分配中公平合理的原则，与“体现”相符。"}, {"text": "利润", "is_correct": false, "explanation": "语义：税收制度体现的是公平原则，不是利润。"}, {"text": "口号", "is_correct": false, "explanation": "搭配：“体现”不能与“分配口号”搭配，句子要说的是原则。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”与税收制度无关，句子讨论的是分配原则。"}], "explanations": {"正义": "正确：“分配正义”指资源分配中公平合理的原则，与“体现”相符。", "利润": "语义：税收制度体现的是公平原则，不是利润。", "口号": "搭配：“体现”不能与“分配口号”搭配，句子要说的是原则。", "体温": "语义：“体温”与税收制度无关，句子讨论的是分配原则。"}, "sentence_index": 6, "correct_answer": "正义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道数学题的答案很正义。", "explanation": "这里应该用〈正确〉。正义指道德上的公平，不能用来评价答案的对错。"}, {"text": "这次考试的正义很高。", "explanation": "这里应该用〈分数〉。“分数很高”才是常用说法；正义指公平合理的道理或原则，不能用来说成绩高低。"}, {"text": "他跑步的正义很快，大家都很佩服。", "explanation": "这里应该用〈速度〉。正义指公平合理的道理，不指动作的快慢；“速度很快”才是常用说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1249cc0b-e936-4f6d-a885-4bc9b9606521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13451, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们认为这是一块正义。", "corrected_sentence": "他们认为这是一种正义。", "error_description": "量词误用：正义是抽象概念，不能用“块”计量，应说“一种正义”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1249cc0b-e936-4f6d-a885-4bc9b9606521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13451, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们应该正义得做事。", "corrected_sentence": "他们应该正义地做事。", "error_description": "状语标记错误：修饰动词的状语要用“地”，不能用“得”，应说“正义地做事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1249cc0b-e936-4f6d-a885-4bc9b9606521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13452, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13452, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13452, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "坚持不懈，不轻易改变目标或想法。", "primary_collocate": null, "pronunciation": "zhí zhuó", "ipa": "ʈʂɻ̩˧˥ ʈʂwo˧˥", "syllable_count": 2, "sentences": [{"text": "答案，或许就藏在对消费主义惯性的反思与对供应链正义的执着追求之中。", "target_word": "执着", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他对梦想非常执着。", "target_word": "执着", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她执着地寻找失散多年的哥哥。", "target_word": "执着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做研究需要一种执着的精神。", "target_word": "执着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他执着于自己的想法，谁的话也不听。", "target_word": "执着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老人几十年来一直执着地保护这片森林。", "target_word": "执着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对音乐的执着让大家很佩服。", "target_word": "执着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很执着，一定要把这件事做完。", "target_word": "执着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正是因为执着，他才取得了成功。", "target_word": "执着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们都很佩服她执着的态度。", "target_word": "执着", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "执着地", "label": "状语形式"}, {"form": "执着的", "label": "定语形式"}, {"form": "执著", "label": "异体"}], "register": "中性", "sense_fingerprint": "对目标或想法坚持不懈、不轻易改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7728ca8c-cc31-47be-a40d-da0fcf2ae697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13452, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "轻浮", "is_correct": false, "explanation": "语义：“轻浮”与“反思”“正义”的严肃语境不符，不能修饰“追求”。"}, {"text": "执着", "is_correct": true, "explanation": "正确。“执着”修饰“追求”，表示坚持不懈，与“反思”“正义”的语境相合。"}, {"text": "散漫", "is_correct": false, "explanation": "语义：“散漫”指不集中、不坚持，与“追求正义”的意思相矛盾。"}, {"text": "草率", "is_correct": false, "explanation": "搭配：“草率”多修饰决定、处理等，不说“草率的追求”。"}], "explanations": {"轻浮": "语义：“轻浮”与“反思”“正义”的严肃语境不符，不能修饰“追求”。", "执着": "正确。“执着”修饰“追求”，表示坚持不懈，与“反思”“正义”的语境相合。", "散漫": "语义：“散漫”指不集中、不坚持，与“追求正义”的意思相矛盾。", "草率": "搭配：“草率”多修饰决定、处理等，不说“草率的追求”。"}, "sentence_index": 0, "correct_answer": "执着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做事很执着，每件事都只做一半就丢下。", "explanation": "这里应该用〈三心二意〉。“执着”指坚持不放弃，与“每件事都只做一半就丢下”相矛盾；做事不专一应说“三心二意”。"}, {"text": "他的想法很执着，今天一个样，明天又一个样。", "explanation": "这里应该用〈善变〉。“执着”指不轻易改变想法，与“今天一个样，明天又一个样”的变化相矛盾。"}, {"text": "他做事很执着，三天就换了一份工作。", "explanation": "这里应该用〈随便〉。“执着”指坚持不放弃，与“三天就换了一份工作”相矛盾；形容做事不认真，应用“随便”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13452, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷淡", "is_correct": false, "explanation": "语义：对音乐冷淡不会让人佩服，与句子的赞赏语气矛盾。"}, {"text": "执着", "is_correct": true, "explanation": "正确。“执着”作定语，指对音乐的坚持，与“让大家很佩服”相合。"}, {"text": "懒散", "is_correct": false, "explanation": "语义：懒散与“让大家很佩服”的赞赏相矛盾。"}, {"text": "随便", "is_correct": false, "explanation": "搭配：“对……的随便”不成立，不说“对音乐的随便”。"}], "explanations": {"冷淡": "语义：对音乐冷淡不会让人佩服，与句子的赞赏语气矛盾。", "执着": "正确。“执着”作定语，指对音乐的坚持，与“让大家很佩服”相合。", "懒散": "语义：懒散与“让大家很佩服”的赞赏相矛盾。", "随便": "搭配：“对……的随便”不成立，不说“对音乐的随便”。"}, "sentence_index": 6, "correct_answer": "执着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很执着，一会儿想学画画，一会儿又想学跳舞。", "explanation": "这里应该用〈善变〉。“执着”指不轻易改变目标，与“一会儿学画画，一会儿学跳舞”的反复相矛盾；此处应说“善变”。"}, {"text": "他很执着，对什么事都是一时兴起，过两天就忘了。", "explanation": "这里应该用〈浮躁〉。“执着”指坚持不放弃，与“一时兴起、过两天就忘了”的态度相矛盾；此处应说“浮躁”。"}, {"text": "他性格执着，一遇到困难就放弃。", "explanation": "这里应该用〈软弱〉。“执着”指坚持不放弃，与“一遇到困难就放弃”的态度相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13452, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他执着了坚持训练，从不间断。", "corrected_sentence": "他执着地坚持训练，从不间断。", "error_description": "体标错误：“执着”修饰动词作状语时不能带“了”，应用“地”。“执着了坚持”不通，应说“执着地坚持训练”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13452, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一种执着地精神，从不轻易放弃。", "corrected_sentence": "他有一种执着的精神，从不轻易放弃。", "error_description": "定语错误：“执着”修饰名词“精神”时要用“的”，不能用“地”。应说“执着的精神”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
