INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13462, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把水洒在植物或物体的表面，使它们湿润。", "primary_collocate": null, "pronunciation": "jiāo shuǐ", "ipa": "tɕjɑʊ˥ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "每天早上，人们带着小树苗和水桶来到公园，挖坑、种树、浇水。", "target_word": "浇水", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "大家挖土，放小树，浇水。", "target_word": "浇水", "complexity_tier": "T1", "sentence_source": "mined"}, {"text": "每天早上，我都给阳台的花浇水。", "target_word": "浇水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气很热，该给菜地浇水了。", "target_word": "浇水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈提着水壶去院子里浇水。", "target_word": "浇水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盆花一周只需要浇水两次。", "target_word": "浇水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "浇水太多，花的根会烂掉。", "target_word": "浇水", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他忘了浇水，小草都枯黄了。", "target_word": "浇水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，今天不用浇水。", "target_word": "浇水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶早晚都要给树浇水。", "target_word": "浇水", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "浇了水", "label": "体标（了）"}, {"form": "浇过水", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "浇水：把水洒到植物或物体上使其湿润", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94fd5d6a-ee47-45b7-8109-ed74731efdc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13462, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "浇水", "is_correct": true, "explanation": "正确。浇水指把水洒在植物或物体上使其湿润。"}, {"text": "交税", "is_correct": false, "explanation": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是缴纳税款。"}, {"text": "教书", "is_correct": false, "explanation": "shū 与 shuǐ 的韵母和声调都不同，意思是从事教学工作。"}, {"text": "江水", "is_correct": false, "explanation": "jiāng 与 jiāo 的韵母不同（-ang 与 -ao），意思是江河里的水。"}], "explanations": {"浇水": "正确。浇水指把水洒在植物或物体上使其湿润。", "交税": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是缴纳税款。", "教书": "shū 与 shuǐ 的韵母和声调都不同，意思是从事教学工作。", "江水": "jiāng 与 jiāo 的韵母不同（-ang 与 -ao），意思是江河里的水。"}, "sentence_index": null, "correct_answer": "浇水"}, "level_3": {"options": [{"text": "浇水", "is_correct": true, "explanation": "正确。“挖坑、种树、浇水”是种树的常见步骤。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：挖坑、种树之后接“跳舞”，与劳动动作的并列不合。"}, {"text": "收割", "is_correct": false, "explanation": "语义：树苗刚种下，不会接“收割”，与种树的过程矛盾。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“挖坑、种树”是并列的劳动动作，“睡觉”不能与之并列。"}], "explanations": {"浇水": "正确。“挖坑、种树、浇水”是种树的常见步骤。", "跳舞": "语义：挖坑、种树之后接“跳舞”，与劳动动作的并列不合。", "收割": "语义：树苗刚种下，不会接“收割”，与种树的过程矛盾。", "睡觉": "搭配：“挖坑、种树”是并列的劳动动作，“睡觉”不能与之并列。"}, "sentence_index": 0, "correct_answer": "浇水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他给客人浇水，沏了一壶茶。", "explanation": "这里应该用〈倒〉。给客人倒水要说“倒水”，“浇水”指把水洒在植物或物体上，不用于给人倒水。"}, {"text": "他给咖啡机浇水，煮了一杯咖啡。", "explanation": "这里应该用〈加〉。往咖啡机里加水要说“加水”，“浇水”不指注入机器。"}, {"text": "他用清水给伤口浇水，清洗了一下。", "explanation": "这里应该用〈冲洗〉。清洗伤口要说“冲洗”，“浇水”不用于清洗伤口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13462, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浇水", "is_correct": true, "explanation": "正确。“浇水太多，花的根会烂掉”指给花浇水过量导致伤害，与句意相符。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：打扫太多不会使花的根烂掉，与句中的因果关系不符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与花的根烂掉没有因果关系，句意不通。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步太多”不是会伤害花根的行为，搭配不成立。"}], "explanations": {"浇水": "正确。“浇水太多，花的根会烂掉”指给花浇水过量导致伤害，与句意相符。", "打扫": "语义：打扫太多不会使花的根烂掉，与句中的因果关系不符。", "唱歌": "语义：唱歌与花的根烂掉没有因果关系，句意不通。", "散步": "搭配：“散步太多”不是会伤害花根的行为，搭配不成立。"}, "sentence_index": 6, "correct_answer": "浇水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用抹布给桌子浇水，擦得很干净。", "explanation": "这里应该用〈清洁〉。清洁桌面要说“清洁”，“浇水”不用于清洁桌面。"}, {"text": "他给沙发浇水，把灰尘都去掉了。", "explanation": "这里应该用〈吸尘〉。清除沙发上的灰尘要说“吸尘”，“浇水”不指去除灰尘。"}, {"text": "他给门浇水，把锁装好了。", "explanation": "这里应该用〈安装〉。安装门锁要说“安装”，“浇水”不指安装物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈每天给浇水。", "corrected_sentence": "妈妈每天给花浇水。", "error_description": "宾语缺失：“给”后面须带受事对象，“给浇水”不成句，应补上“花”，说“妈妈每天给花浇水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一天浇水一次。", "corrected_sentence": "我一天浇一次水。", "error_description": "离合词位置错误。“浇水”是离合词，动量词“一次”应插在“浇”和“水”之间，说“浇一次水”，不能说“浇水一次”（与“洗澡”同理，应说“洗一次澡”）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
