INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13463, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指体型很小的昆虫或其他无脊椎动物，常用于口语中对小型虫类的统称。", "primary_collocate": null, "pronunciation": "xiǎo chóng zi", "ipa": "ɕjɑʊ˨˩˦ ʈʂʰʊŋ˧˥ tsɹ̩", "syllable_count": 3, "sentences": [{"text": "小鸟和小虫子也会来。", "target_word": "小虫子", "complexity_tier": "T1", "sentence_source": "mined"}, {"text": "草地上有很多小虫子。", "target_word": "小虫子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不怕小虫子，就怕蛇。", "target_word": "小虫子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灯一开，小虫子都飞过来了。", "target_word": "小虫子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天晚上，小虫子总爱往灯光那边飞。", "target_word": "小虫子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹用手指轻轻碰了碰小虫子。", "target_word": "小虫子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟早上起来找小虫子吃。", "target_word": "小虫子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "叶子上趴着一只小虫子。", "target_word": "小虫子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们蹲着看地上的小虫子。", "target_word": "小虫子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小虫子在土里爬来爬去。", "target_word": "小虫子", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "小蟲子", "label": "繁体"}], "register": "口语", "sense_fingerprint": "口语里对小型虫类的统称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '576e64ee-f9ee-4e44-b7e0-41b533bdad60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13463, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小虫子", "is_correct": true, "explanation": "正确：「小虫子」是会飞会爬的小动物，可以和小鸟并列说「也会来」。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能自己移动，与「也会来」对主语的要求不合。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：「会来」一般搭配能行动的主语，「窗户」不能这样搭配。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是静止的家具，不能说「也会来」。"}], "explanations": {"小虫子": "正确：「小虫子」是会飞会爬的小动物，可以和小鸟并列说「也会来」。", "石头": "语义：石头不能自己移动，与「也会来」对主语的要求不合。", "窗户": "搭配：「会来」一般搭配能行动的主语，「窗户」不能这样搭配。", "桌子": "语义：桌子是静止的家具，不能说「也会来」。"}, "sentence_index": 0, "correct_answer": "小虫子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "灯一开，一头小虫子都飞过来了。", "explanation": "这里应该用〈只〉。「头」用于牛、马等大型牲畜，小虫子要用量词「只」。"}, {"text": "草地上的小虫子比我还高，我都够不着它。", "explanation": "这里词义用错：「小虫子」指体型很小的虫类，不可能比人还高。"}, {"text": "窗台上趴着一座小虫子，一动不动。", "explanation": "这里应该用〈只〉。「座」用于山、楼房等大型建筑，小虫子要用「只」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13463, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不能吃，与「吃」对宾语的要求不合。"}, {"text": "小虫子", "is_correct": true, "explanation": "正确：「小虫子」是小鸟能吃的食物，符合「找……吃」的语境。"}, {"text": "剪刀", "is_correct": false, "explanation": "语义：剪刀不是食物，不能用来「吃」。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：「吃」的宾语应是食物，「雨伞」不能与「吃」搭配。"}], "explanations": {"钥匙": "语义：钥匙不能吃，与「吃」对宾语的要求不合。", "小虫子": "正确：「小虫子」是小鸟能吃的食物，符合「找……吃」的语境。", "剪刀": "语义：剪刀不是食物，不能用来「吃」。", "雨伞": "搭配：「吃」的宾语应是食物，「雨伞」不能与「吃」搭配。"}, "sentence_index": 6, "correct_answer": "小虫子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "土里有一枚小虫子在爬来爬去。", "explanation": "这里应该用〈只〉。「枚」用于硬币、奖章等小件物品，小虫子要用「只」。"}, {"text": "我家的小虫子是一台电脑，每天陪我写作业。", "explanation": "「小虫子」只指小型虫类，这里却用来指电脑，词义用错了。"}, {"text": "草地上飞来一幅小虫子。", "explanation": "这里应该用〈只〉。「幅」用于字画，小虫子要用「只」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13463, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗台上落了一本小虫子。", "corrected_sentence": "窗台上落了一只小虫子。", "error_description": "量词错误：「小虫子」是动物，应用量词「只」。「本」用于书籍，不能修饰小虫子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13463, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们发现了一朵小虫子。", "corrected_sentence": "我们发现了一只小虫子。", "error_description": "量词错误：「小虫子」是动物，应用量词「只」。「朵」用于花、云等，不能修饰小虫子。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
