INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13466, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "自己主动选择做某事，不是别人强迫的。", "primary_collocate": null, "pronunciation": "zì yuàn", "ipa": "tsɹ̩˥˩ ɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这个活动是居民自己组织的，大家自愿参加，没有人必须来。", "target_word": "自愿", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我自愿去山区学校教孩子们读书。", "target_word": "自愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人叫他来，他是自愿留下的。", "target_word": "自愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们自愿帮老师打扫教室。", "target_word": "自愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她自愿把自己的书送给别人。", "target_word": "自愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司不要求加班，同事们自愿留下来工作。", "target_word": "自愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些人自愿到医院照顾病人。", "target_word": "自愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家自愿捐钱，帮助生病的孩子。", "target_word": "自愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他自愿换到最后一排的座位。", "target_word": "自愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们自愿去公园捡垃圾。", "target_word": "自愿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自愿者", "label": "复合"}, {"form": "自愿的", "label": "复合"}, {"form": "自願", "label": "繁体"}], "register": "中性", "sense_fingerprint": "出于自己的主动意愿去做某事，没有受到强迫", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06416bc7-081c-4962-af33-9fe357ea7f64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13466, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自愿", "is_correct": true, "explanation": "自愿（zì yuàn）意思是自己主动选择去做，是本题的目标词。"}, {"text": "志愿", "is_correct": false, "explanation": "zhì（第四声）与 zì（第四声）声母不同（zh 与 z），意思是志向或志愿者。"}, {"text": "寺院", "is_correct": false, "explanation": "sì（第四声）与 zì（第四声）声母不同（s 与 z），意思是寺庙。"}, {"text": "资源", "is_correct": false, "explanation": "zī（第一声）与 zì（第四声）声调不同，意思是资源。"}], "explanations": {"自愿": "自愿（zì yuàn）意思是自己主动选择去做，是本题的目标词。", "志愿": "zhì（第四声）与 zì（第四声）声母不同（zh 与 z），意思是志向或志愿者。", "寺院": "sì（第四声）与 zì（第四声）声母不同（s 与 z），意思是寺庙。", "资源": "zī（第一声）与 zì（第四声）声调不同，意思是资源。"}, "sentence_index": null, "correct_answer": "自愿"}, "level_3": {"options": [{"text": "自愿", "is_correct": true, "explanation": "正确：自愿是副词，表示自己主动选择，与“没有人必须来”的语境相符。"}, {"text": "不得不", "is_correct": false, "explanation": "语义：“不得不”表示被迫，与“没有人必须来”矛盾。"}, {"text": "只好", "is_correct": false, "explanation": "语义：“只好”表示无可奈何，与“居民自己组织”的自主语境冲突。"}, {"text": "硬", "is_correct": false, "explanation": "语域：“硬”口语色彩强，且含强迫意味，与句子的说明语气不合。"}], "explanations": {"自愿": "正确：自愿是副词，表示自己主动选择，与“没有人必须来”的语境相符。", "不得不": "语义：“不得不”表示被迫，与“没有人必须来”矛盾。", "只好": "语义：“只好”表示无可奈何，与“居民自己组织”的自主语境冲突。", "硬": "语域：“硬”口语色彩强，且含强迫意味，与句子的说明语气不合。"}, "sentence_index": 0, "correct_answer": "自愿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他自愿醒了，所以今天不用闹钟。", "explanation": "这里应该用〈自然〉。自愿表示有意识地主动选择去做，醒来不是人主动选择的，应说“他自然醒了”。"}, {"text": "这扇门自愿打开了。", "explanation": "这里应该用〈自动〉。自愿要求有意志的人主动选择，门没有意志，应说“门自动打开”。"}, {"text": "他自愿撞到了桌子。", "explanation": "这里应该用〈无意〉。自愿表示有意地主动选择，撞到桌子是无意的，应说“他无意中撞到了桌子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13466, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自愿", "is_correct": true, "explanation": "正确：自愿是副词，表示主动选择，与“照顾病人”的主动性相符。"}, {"text": "独自", "is_correct": false, "explanation": "语义：“独自”指一个人单独做，与“这些人”的复数主语矛盾。"}, {"text": "无意", "is_correct": false, "explanation": "语义：“无意”指并非有意，与“照顾病人”这一有意的行为矛盾。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”指徒然、没有效果，与“照顾病人”的积极目的相悖。"}], "explanations": {"自愿": "正确：自愿是副词，表示主动选择，与“照顾病人”的主动性相符。", "独自": "语义：“独自”指一个人单独做，与“这些人”的复数主语矛盾。", "无意": "语义：“无意”指并非有意，与“照顾病人”这一有意的行为矛盾。", "白白": "语义：“白白”指徒然、没有效果，与“照顾病人”的积极目的相悖。"}, "sentence_index": 6, "correct_answer": "自愿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板强迫员工自愿加班。", "explanation": "这里不能用“自愿”。这句表示被迫去做，与自己选择的意思相反，应去掉“自愿”。"}, {"text": "同学们要自愿遵守纪律。", "explanation": "这里应该用〈自觉〉。自愿强调可以不做、自己选择，遵守纪律是义务，应说“自觉遵守纪律”。"}, {"text": "他很有自愿精神，常去帮助别人。", "explanation": "这里应该用〈志愿〉。自愿表示自己选择去做，与“志愿者、志愿精神”的志愿不同，应说“志愿精神”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他被自愿陪朋友去医院。", "corrected_sentence": "他自愿陪朋友去医院。", "error_description": "错误：“被自愿”；正确：“自愿”。“自愿”表示主动选择，与表示被动的“被”意义相反，二者不能连用，应去掉“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈自愿了去接孩子。", "corrected_sentence": "妈妈自愿去接孩子。", "error_description": "体标错误：副词“自愿”后不能加“了”，应说“妈妈自愿去接孩子”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
