INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13467, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "参与、加入某个活动或事件中。", "primary_collocate": null, "pronunciation": "cān jiā", "ipa": "tsʰan˥ tɕja˥", "syllable_count": 2, "sentences": [{"text": "这个活动是居民自己组织的，大家自愿参加，没有人必须来。", "target_word": "参加", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我明天要参加朋友的生日会。", "target_word": "参加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每年都参加学校的运动会。", "target_word": "参加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹参加了一个唱歌比赛。", "target_word": "参加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想参加我们的读书小组吗？", "target_word": "参加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请大家都来参加会议。", "target_word": "参加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸没有参加今天的家长会。", "target_word": "参加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她参加过三次汉语考试。", "target_word": "参加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加比赛前，他每天练习两个小时。", "target_word": "参加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的新同事也来参加聚会了。", "target_word": "参加", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "参加了", "label": "体标"}, {"form": "参加过", "label": "体标"}, {"form": "参加者", "label": "复合"}, {"form": "參加", "label": "繁体"}], "register": "中性", "sense_fingerprint": "加入并参与会议、比赛等活动或事件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06416bc7-081c-4962-af33-9fe357ea7f64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13467, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参加", "is_correct": true, "explanation": "正确：参加表示加入并参与活动，与“自愿”后面的活动语境相符。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”表示躲开、不愿面对，与居民组织活动的参与语境矛盾。"}, {"text": "罢工", "is_correct": false, "explanation": "语义：“罢工”指停止工作以表示抗议，与参加活动的语境无关。"}, {"text": "排队", "is_correct": false, "explanation": "语义：“排队”指按次序等候，与“参加活动”的语境无关。"}], "explanations": {"参加": "正确：参加表示加入并参与活动，与“自愿”后面的活动语境相符。", "逃避": "语义：“逃避”表示躲开、不愿面对，与居民组织活动的参与语境矛盾。", "罢工": "语义：“罢工”指停止工作以表示抗议，与参加活动的语境无关。", "排队": "语义：“排队”指按次序等候，与“参加活动”的语境无关。"}, "sentence_index": 0, "correct_answer": "参加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们参加了博物馆。", "explanation": "这里应该用〈参观〉。参加指参与活动，不能用于去看地方，应说“我们参观了博物馆”。"}, {"text": "详情请参加附录。", "explanation": "这里应该用〈参见〉。参加指加入活动，不能用于指查阅书中内容，应说“详情请参见附录”。"}, {"text": "请参加第三章。", "explanation": "这里应该用〈参阅〉。参加指加入活动，不能用于读书内容，应说“请参阅第三章”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13467, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参加", "is_correct": true, "explanation": "正确：参加表示出席或参与会议、活动，与“家长会”相符。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：“演奏”的宾语是乐曲，不能与“家长会”搭配。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与家长会的语境不符。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”是舞蹈活动，与开会的语境不符。"}], "explanations": {"参加": "正确：参加表示出席或参与会议、活动，与“家长会”相符。", "演奏": "搭配：“演奏”的宾语是乐曲，不能与“家长会”搭配。", "唱": "语义：“唱”指发出歌声，与家长会的语境不符。", "跳舞": "语义：“跳舞”是舞蹈活动，与开会的语境不符。"}, "sentence_index": 6, "correct_answer": "参加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们参加了这座城市，玩得很开心。", "explanation": "这里应该用〈游览〉。参加指参与活动，游览城市要用“游览”。"}, {"text": "他参加了这次的烦恼。", "explanation": "这里应该用〈承受〉。烦恼不是可以参与的活动，应说“承受烦恼”。"}, {"text": "他参加了一个电话。", "explanation": "这里应该用〈接〉。参加指参与活动，接电话要用“接”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13467, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我去年参加了过三次比赛。", "corrected_sentence": "我去年参加过三次比赛。", "error_description": "体标错误：“参加”后已有“过”，不能再加“了”，应说“参加过三次比赛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13467, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他下午参加了过一场婚礼。", "corrected_sentence": "他下午参加了一场婚礼。", "error_description": "体标错误：“参加了”已表示完成，“了”与“过”不能同时出现，应去掉“过”，说“参加了一场婚礼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
