INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13470, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水桶是一种圆柱形的容器，通常用塑料或金属制成，用来盛水。", "primary_collocate": null, "pronunciation": "shuǐ tǒng", "ipa": "ʂuei˨˩˦ tʰʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "每天早上，人们带着小树苗和水桶来到公园，挖坑、种树、浇水。", "target_word": "水桶", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "他提着一个红色的水桶。", "target_word": "水桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水桶里装满了水。", "target_word": "水桶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把水桶放在门后面。", "target_word": "水桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个水桶是塑料做的。", "target_word": "水桶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈用水桶洗车。", "target_word": "水桶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水桶太重了，我拿不动。", "target_word": "水桶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩在海边玩水桶和沙子。", "target_word": "水桶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家里有两个大水桶。", "target_word": "水桶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水桶破了一个洞，水都流出来了。", "target_word": "水桶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "用来盛水的圆桶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '116786dd-4fc5-43e5-bfd0-d8b11bf324a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13470, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水桶", "is_correct": true, "explanation": "正确：“水桶”能盛水，人们带着它去浇树，与“浇水”相符。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴带不去挖坑种树，也装不了水，句子不通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不能盛水，也不会随身带去挖坑种树，句子不通。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，不能带去公园挖坑种树，句子不通。"}], "explanations": {"水桶": "正确：“水桶”能盛水，人们带着它去浇树，与“浇水”相符。", "钢琴": "语义：钢琴带不去挖坑种树，也装不了水，句子不通。", "电脑": "语义：电脑不能盛水，也不会随身带去挖坑种树，句子不通。", "沙发": "语义：沙发是家具，不能带去公园挖坑种树，句子不通。"}, "sentence_index": 0, "correct_answer": "水桶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他戴上水桶，急忙出门去了。", "explanation": "这里应该用〈帽子〉。水桶是盛水的器具，不能戴在头上，出门要戴的是帽子。"}, {"text": "妈妈用菜刀把水桶切成了片。", "explanation": "这里应该用〈萝卜〉。水桶是金属或塑料做的容器，不能切片，切片的应是萝卜之类的食材。"}, {"text": "他中午把午饭装进水桶里带去学校。", "explanation": "这里应该用〈饭盒〉。午饭要装在饭盒里带去学校，水桶太大，不便携带。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a042ac0-83c9-468c-8309-cd1ec921210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水桶", "is_correct": true, "explanation": "正确：“水桶”有分量，“太重了，我拿不动”相合。"}, {"text": "羽毛", "is_correct": false, "explanation": "语义：羽毛很轻，说“太重了”与“拿不动”的意思相反。"}, {"text": "气球", "is_correct": false, "explanation": "语义：气球很轻，不会“太重”，与“拿不动”的意思不符。"}, {"text": "纸巾", "is_correct": false, "explanation": "搭配：“太重了”多形容有分量的实物，纸巾轻薄，不说“太重”。"}], "explanations": {"水桶": "正确：“水桶”有分量，“太重了，我拿不动”相合。", "羽毛": "语义：羽毛很轻，说“太重了”与“拿不动”的意思相反。", "气球": "语义：气球很轻，不会“太重”，与“拿不动”的意思不符。", "纸巾": "搭配：“太重了”多形容有分量的实物，纸巾轻薄，不说“太重”。"}, "sentence_index": 6, "correct_answer": "水桶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他躺在水桶里泡澡。", "explanation": "这里应该用〈浴缸〉。水桶太小，人躺不进去，泡澡要用浴缸。"}, {"text": "他在书房里把书放进水桶里收好。", "explanation": "这里应该用〈书架〉。水桶是盛水的器具，不是放书的地方，收好的书应放进书架。"}, {"text": "妈妈把粥盛进水桶里。", "explanation": "这里应该用〈碗〉。粥要盛在碗里，水桶太大，不用来盛粥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a042ac0-83c9-468c-8309-cd1ec921210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厨房里有一张水桶。", "corrected_sentence": "厨房里有一个水桶。", "error_description": "量词错误：“水桶”应用量词“个”，“张”用于纸张、桌面等平面的东西，不能用于水桶。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a042ac0-83c9-468c-8309-cd1ec921210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈买了一只红色的水桶。", "corrected_sentence": "妈妈买了一个红色的水桶。", "error_description": "量词错误：“水桶”应用量词“个”，“只”多用于动物或成对的东西，不能用于水桶。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a042ac0-83c9-468c-8309-cd1ec921210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13471, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离开", "is_correct": true, "explanation": "反义：“来到”指到达某处，“离开”指从某处离去，二者意义相反。"}, {"text": "观看", "is_correct": false, "explanation": "无反义关系：“观看”与“来到”意义无关，不构成反义词。"}, {"text": "散步", "is_correct": false, "explanation": "无反义关系：“散步”指慢慢地走，与“来到”不构成反义。"}, {"text": "休息", "is_correct": false, "explanation": "无反义关系：“休息”指停止活动，与“来到”不构成反义。"}], "correct_answer": "离开", "explanations": {"离开": "反义：“来到”指到达某处，“离开”指从某处离去，二者意义相反。", "观看": "无反义关系：“观看”与“来到”意义无关，不构成反义词。", "散步": "无反义关系：“散步”指慢慢地走，与“来到”不构成反义。", "休息": "无反义关系：“休息”指停止活动，与“来到”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a042ac0-83c9-468c-8309-cd1ec921210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13471, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离开", "is_correct": true, "explanation": "反义：“来到”指到达某处，“离开”指从某处离去，二者意义相反。"}, {"text": "写作", "is_correct": false, "explanation": "无反义关系：“写作”指写文章，与“来到”意义无关。"}, {"text": "睡觉", "is_correct": false, "explanation": "无反义关系：“睡觉”指入睡，与“来到”不构成反义。"}, {"text": "游泳", "is_correct": false, "explanation": "无反义关系：“游泳”指在水中活动，与“来到”不构成反义。"}], "correct_answer": "离开", "explanations": {"离开": "反义：“来到”指到达某处，“离开”指从某处离去，二者意义相反。", "写作": "无反义关系：“写作”指写文章，与“来到”意义无关。", "睡觉": "无反义关系：“睡觉”指入睡，与“来到”不构成反义。", "游泳": "无反义关系：“游泳”指在水中活动，与“来到”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a042ac0-83c9-468c-8309-cd1ec921210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13471, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "到达某处。", "primary_collocate": null, "pronunciation": "lái dào", "ipa": "laɪ̯˧˥ taʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "昨天晚上，我们终于来到了北京。", "target_word": "来到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次来到中国，什么都觉得新鲜。", "target_word": "来到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车慢慢停下，我们来到了一个小城市。", "target_word": "来到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，我们来到公园看花。", "target_word": "来到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跟着朋友来到一家很安静的咖啡店。", "target_word": "来到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走了两个小时，我们来到山脚下。", "target_word": "来到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们来到海边，马上跳进水里游泳。", "target_word": "来到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带学生们来到博物馆参观。", "target_word": "来到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从南方来到北方工作，不习惯这里的冬天。", "target_word": "来到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你来到这里以后，觉得生活怎么样？", "target_word": "来到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "来到了", "label": "体标"}, {"form": "来到过", "label": "体标"}], "register": "中性", "sense_fingerprint": "从别处移动并到达某个地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '116786dd-4fc5-43e5-bfd0-d8b11bf324a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13471, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "来到", "is_correct": true, "explanation": "正确：“来到”表示到达北京，与“昨天晚上终于”的语境相符。"}, {"text": "拜访", "is_correct": false, "explanation": "搭配：“拜访”的对象是人，不能说拜访一座城市。"}, {"text": "推翻", "is_correct": false, "explanation": "语义：“推翻”指颠覆政权或结论，与“终于到了北京”不符。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”用于房间、街道等具体场所，北京不是可以打扫的对象。"}], "explanations": {"来到": "正确：“来到”表示到达北京，与“昨天晚上终于”的语境相符。", "拜访": "搭配：“拜访”的对象是人，不能说拜访一座城市。", "推翻": "语义：“推翻”指颠覆政权或结论，与“终于到了北京”不符。", "打扫": "搭配：“打扫”用于房间、街道等具体场所，北京不是可以打扫的对象。"}, "sentence_index": 0, "correct_answer": "来到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他努力工作，终于来到了工资。", "explanation": "这里应该用〈拿到〉。“来到”指到达某个地点，工资要说“拿到”。"}, {"text": "他们经过多次谈判，终于来到了协议。", "explanation": "这里应该用〈达成〉。“来到”不能与“协议”搭配，要说“达成协议”。"}, {"text": "他一直努力，终于来到了梦想。", "explanation": "这里应该用〈实现〉。“来到”指到达地点，梦想要说“实现”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a042ac0-83c9-468c-8309-cd1ec921210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13471, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "来到", "is_correct": true, "explanation": "正确：“来到”表示游客到达海边，后面“马上跳进水里游泳”前后连贯。"}, {"text": "远离", "is_correct": false, "explanation": "语义：“远离海边”与后面“马上跳进水里游泳”矛盾，游客不会先远离海边再下水。"}, {"text": "避开", "is_correct": false, "explanation": "语义：“避开海边”与“跳进水里游泳”前后不一致。"}, {"text": "离开", "is_correct": false, "explanation": "语义：先“离开海边”又“马上跳进水里”，前后逻辑不通。"}], "explanations": {"来到": "正确：“来到”表示游客到达海边，后面“马上跳进水里游泳”前后连贯。", "远离": "语义：“远离海边”与后面“马上跳进水里游泳”矛盾，游客不会先远离海边再下水。", "避开": "语义：“避开海边”与“跳进水里游泳”前后不一致。", "离开": "语义：先“离开海边”又“马上跳进水里”，前后逻辑不通。"}, "sentence_index": 6, "correct_answer": "来到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的努力终于来到了奖金。", "explanation": "这里应该用〈领取〉。“来到”指到达某个地点，奖金要说“领取”。"}, {"text": "这件事终于来到了大家的关注。", "explanation": "这里应该用〈引起〉。“来到”不能与“关注”搭配，要说“引起关注”。"}, {"text": "他终于来到了一个奖励。", "explanation": "这里应该用〈得到〉。“来到”不与“奖励”搭配，表示获得奖励要说“得到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a042ac0-83c9-468c-8309-cd1ec921210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13471, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他明天来到了我们学校参加比赛。", "corrected_sentence": "他明天来到我们学校参加比赛。", "error_description": "时体错误：“明天”指将来，句中不能用“了”表示已完成，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a042ac0-83c9-468c-8309-cd1ec921210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13471, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们坐船来到在小岛。", "corrected_sentence": "我们坐船来到了小岛。", "error_description": "介词错误：“来到”后直接接处所宾语，不能再加“在”，这里应说“来到了小岛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a042ac0-83c9-468c-8309-cd1ec921210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
