INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13472, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或工具在地面挖出一个坑。", "primary_collocate": null, "pronunciation": "wā kēng", "ipa": "ua˥ kʰɤŋ˥", "syllable_count": 2, "sentences": [{"text": "每天早上，人们带着小树苗和水桶来到公园，挖坑、种树、浇水。", "target_word": "挖坑", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "爷爷拿着铁锹在院子里挖坑，准备种一棵桃树。", "target_word": "挖坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在花园里挖坑，把骨头埋了起来。", "target_word": "挖坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们在路边挖坑，要装新的电线杆。", "target_word": "挖坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在沙滩上挖坑，然后把水倒进去。", "target_word": "挖坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，农民在地里挖坑，再放进种子。", "target_word": "挖坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先挖坑，再放树苗，最后盖上土。", "target_word": "挖坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用小铲子在地上挖坑，想找到埋着的东西。", "target_word": "挖坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地很硬，挖坑要用很大的力气。", "target_word": "挖坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在树下挖坑，把落叶埋进去。", "target_word": "挖坑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "挖了坑", "label": "体标"}, {"form": "挖过坑", "label": "体标"}], "register": "中性", "sense_fingerprint": "用手或工具在地面挖出坑，常为种树、埋东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '116786dd-4fc5-43e5-bfd0-d8b11bf324a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13472, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挖坑", "is_correct": true, "explanation": "「挖坑」指用工具在地上挖出坑，与后面的「种树、浇水」相合。"}, {"text": "砍树", "is_correct": false, "explanation": "语义：「砍树」与「种树、浇水」的目的相反。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：「拆除」多用于房屋、设施，不能用于园地里的种树活动。"}, {"text": "挖河", "is_correct": false, "explanation": "语义：挖河规模太大，与小树苗、水桶的园艺场景不符。"}], "explanations": {"挖坑": "「挖坑」指用工具在地上挖出坑，与后面的「种树、浇水」相合。", "砍树": "语义：「砍树」与「种树、浇水」的目的相反。", "拆除": "搭配：「拆除」多用于房屋、设施，不能用于园地里的种树活动。", "挖河": "语义：挖河规模太大，与小树苗、水桶的园艺场景不符。"}, "sentence_index": 0, "correct_answer": "挖坑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人用钻机挖坑，打出了一口深井。", "explanation": "这里应该用〈钻孔〉。挖坑指用手或工具挖出浅坑，用钻机打深井要用钻孔。"}, {"text": "工匠用刻刀挖坑，刻出一尊佛像。", "explanation": "这里应该用〈雕〉。挖坑指在地面挖出小坑，用刻刀做佛像要用雕。"}, {"text": "这条河要挖坑拓宽。", "explanation": "这里应该用〈开挖〉。挖坑指挖出小坑，拓宽河道这类大范围工程要用开挖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a042ac0-83c9-468c-8309-cd1ec921210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13472, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挖坑", "is_correct": true, "explanation": "「挖坑」在前，与句中「再放树苗」的先后顺序相合。"}, {"text": "建坑", "is_correct": false, "explanation": "搭配：「建」不能与「坑」搭配，此处应说挖。"}, {"text": "拔树苗", "is_correct": false, "explanation": "语义：拔树苗与后面的「放树苗」矛盾。"}, {"text": "装电线", "is_correct": false, "explanation": "语义：装电线与前后的种树步骤毫无关系，句意不通。"}], "explanations": {"挖坑": "「挖坑」在前，与句中「再放树苗」的先后顺序相合。", "建坑": "搭配：「建」不能与「坑」搭配，此处应说挖。", "拔树苗": "语义：拔树苗与后面的「放树苗」矛盾。", "装电线": "语义：装电线与前后的种树步骤毫无关系，句意不通。"}, "sentence_index": 6, "correct_answer": "挖坑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在水面上挖坑，想种一棵睡莲。", "explanation": "这里应该用〈挖池塘〉。挖坑只能在地面上进行，水面上不能挖坑；要种睡莲应先挖池塘。"}, {"text": "他在大海中间挖坑，想找到沉船。", "explanation": "这里应该用〈打捞〉。挖坑只能在陆地上挖小坑，海里的沉船要用打捞。"}, {"text": "他在空中挖坑，想建一个小窝。", "explanation": "这里应该用〈搭〉。挖坑要在地面上进行，空中的小窝要用搭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a042ac0-83c9-468c-8309-cd1ec921210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民在地里挖坑着，准备种树。", "corrected_sentence": "农民在地里挖坑，准备种树。", "error_description": "体标错误：「着」应紧跟动词，「挖坑」是动宾结构，后面不能加「着」，这里应去掉「着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a042ac0-83c9-468c-8309-cd1ec921210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在地上挖坑的，想找一样东西。", "corrected_sentence": "他在地上挖坑，想找一样东西。", "error_description": "结构错误：句中的「的」没有可修饰的中心语，“挖坑的，”是残缺结构，应去掉「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a042ac0-83c9-468c-8309-cd1ec921210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13473, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难看", "is_correct": true, "explanation": "正确：“难看”与“漂亮”（好看）是反义词，指外表不好看。"}, {"text": "聪明", "is_correct": false, "explanation": "非反义：“聪明”说智力，与“漂亮”的外表义不相对。"}, {"text": "安静", "is_correct": false, "explanation": "非反义：“安静”说声音或环境，与“漂亮”的外表义无关。"}, {"text": "热闹", "is_correct": false, "explanation": "非反义：“热闹”说场面吵闹、人多，与“漂亮”的外表义不构成反义。"}], "correct_answer": "难看", "explanations": {"难看": "正确：“难看”与“漂亮”（好看）是反义词，指外表不好看。", "聪明": "非反义：“聪明”说智力，与“漂亮”的外表义不相对。", "安静": "非反义：“安静”说声音或环境，与“漂亮”的外表义无关。", "热闹": "非反义：“热闹”说场面吵闹、人多，与“漂亮”的外表义不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13473, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "丑", "is_correct": true, "explanation": "正确：“丑”与“漂亮”（好看）是反义词，指外表不好看。"}, {"text": "勇敢", "is_correct": false, "explanation": "非反义：“勇敢”说性格，与“漂亮”的外表义无关。"}, {"text": "沉重", "is_correct": false, "explanation": "非反义：“沉重”说重量或心情，与“漂亮”不构成反义。"}, {"text": "寒冷", "is_correct": false, "explanation": "非反义：“寒冷”说温度，与“漂亮”的外表义无关。"}], "correct_answer": "丑", "explanations": {"丑": "正确：“丑”与“漂亮”（好看）是反义词，指外表不好看。", "勇敢": "非反义：“勇敢”说性格，与“漂亮”的外表义无关。", "沉重": "非反义：“沉重”说重量或心情，与“漂亮”不构成反义。", "寒冷": "非反义：“寒冷”说温度，与“漂亮”的外表义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13473, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示好看、美观，令人赏心悦目。", "primary_collocate": null, "pronunciation": "piào liang", "ipa": "pʰiɑʊ˥˩ liɑŋ", "syllable_count": 2, "sentences": [{"text": "种树不只是让城市变漂亮，它对生态保护也很重要。", "target_word": "漂亮", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "她今天穿的裙子很漂亮。", "target_word": "漂亮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里的花开了，非常漂亮。", "target_word": "漂亮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市的夜景真漂亮。", "target_word": "漂亮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的新家布置得很漂亮。", "target_word": "漂亮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈给我买了一件漂亮的外套。", "target_word": "漂亮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湖边的房子又新又漂亮。", "target_word": "漂亮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张照片拍得太漂亮了。", "target_word": "漂亮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把房间打扫得干干净净，看起来很漂亮。", "target_word": "漂亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的秋天特别漂亮，很多人去拍照。", "target_word": "漂亮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "漂漂亮亮", "label": "重叠"}], "register": "口语", "sense_fingerprint": "形容人或事物外表好看、美观", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405dfc4a-6ee0-42e9-8dd9-f58f27602e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13473, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "漂亮", "is_correct": true, "explanation": "正确：“让城市变漂亮”指城市外观变美，符合种树带来的好处，句意通顺。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”指声音吵闹，与“不只是……也很重要”的正面语气相反，句子自相矛盾。"}, {"text": "荒凉", "is_correct": false, "explanation": "语义：“荒凉”指冷清、没有生气，与种树带来益处的语境矛盾。"}, {"text": "昏暗", "is_correct": false, "explanation": "体貌：“昏暗”说光线不足，不是城市外观变好的描述，放在句中意思相反。"}], "explanations": {"漂亮": "正确：“让城市变漂亮”指城市外观变美，符合种树带来的好处，句意通顺。", "嘈杂": "语义：“嘈杂”指声音吵闹，与“不只是……也很重要”的正面语气相反，句子自相矛盾。", "荒凉": "语义：“荒凉”指冷清、没有生气，与种树带来益处的语境矛盾。", "昏暗": "体貌：“昏暗”说光线不足，不是城市外观变好的描述，放在句中意思相反。"}, "sentence_index": 0, "correct_answer": "漂亮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的心地很漂亮。", "explanation": "这里应该用〈美丽〉。“漂亮”多指外表好看，形容心地、品德等抽象的美要用“美丽”。"}, {"text": "这碗汤的味道很漂亮。", "explanation": "这里应该用〈好喝〉。“漂亮”形容外表好看，形容汤的味道要用“好喝”。"}, {"text": "我们的未来很漂亮。", "explanation": "这里应该用〈美好〉。“漂亮”形容看得见的外表，形容未来这类抽象的前景要用“美好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13473, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "漂亮", "is_correct": true, "explanation": "正确：“又新又漂亮”并列描述房子的外观，符合句意。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：“陈旧”指老旧，与前面的“新”正好相反，句子自相矛盾。"}, {"text": "破烂", "is_correct": false, "explanation": "语义：“破烂”指残破，与“又新”相矛盾，不能和“新”并列。"}, {"text": "脏", "is_correct": false, "explanation": "体貌：“脏”说卫生状况，不是外观好看的描述，与“又新”的正面语气不协调。"}], "explanations": {"漂亮": "正确：“又新又漂亮”并列描述房子的外观，符合句意。", "陈旧": "语义：“陈旧”指老旧，与前面的“新”正好相反，句子自相矛盾。", "破烂": "语义：“破烂”指残破，与“又新”相矛盾，不能和“新”并列。", "脏": "体貌：“脏”说卫生状况，不是外观好看的描述，与“又新”的正面语气不协调。"}, "sentence_index": 6, "correct_answer": "漂亮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的性格很漂亮。", "explanation": "这里应该用〈温柔〉。“漂亮”形容外表，形容性格要用“温柔”等词。"}, {"text": "他的品格很漂亮。", "explanation": "这里应该用〈高尚〉。“漂亮”形容外表，品格是抽象的道德品质，要用“高尚”。"}, {"text": "这件衣服的重量很漂亮。", "explanation": "这里应该用〈轻〉。“漂亮”形容外表好看，形容衣服的重量要用“轻”或“重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13473, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只小狗长很漂亮。", "corrected_sentence": "这只小狗长得很漂亮。", "error_description": "错误：“长很漂亮”；正确：“长得很漂亮”。“长”后面要用“得”引出补语“很漂亮”，少了“得”句子就不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13473, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有一件很漂亮衣服。", "corrected_sentence": "她有一件很漂亮的衣服。", "error_description": "错误：“很漂亮衣服”；正确：“很漂亮的衣服”。“很漂亮”修饰名词时，中间要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13474, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13474, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13474, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "树木是木本植物的总称，包括各种乔木、灌木和木质藤本植物。", "primary_collocate": null, "pronunciation": "shù mù", "ipa": "ʂu˥˩ mu˥˩", "syllable_count": 2, "sentences": [{"text": "树木可以净化空气，减少噪音，还能帮助小动物和小鸟找到家。", "target_word": "树木", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "山上有很多高大的树木。", "target_word": "树木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天到了，树木都变绿了。", "target_word": "树木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里的树木长得很好。", "target_word": "树木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大风把一些树木吹倒了。", "target_word": "树木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该保护城市里的树木。", "target_word": "树木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天，树木的叶子慢慢变黄。", "target_word": "树木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河边种着很多树木，夏天很凉快。", "target_word": "树木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们去认识不同的树木。", "target_word": "树木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下大雪以后，树木上都是白色的雪。", "target_word": "树木", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "木本植物的总称，泛指各种树", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405dfc4a-6ee0-42e9-8dd9-f58f27602e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13474, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "树木", "is_correct": true, "explanation": "正确：“树木”作主语，能净化空气、帮助小动物，符合句意。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：“钢铁”是金属，不能净化空气，也帮不了小动物。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”没有生命，不能净化空气或帮助小鸟找家。"}, {"text": "公路", "is_correct": false, "explanation": "配价：“净化”“帮助”需要能动的主语，公路做主语不成立。"}], "explanations": {"树木": "正确：“树木”作主语，能净化空气、帮助小动物，符合句意。", "钢铁": "语义：“钢铁”是金属，不能净化空气，也帮不了小动物。", "石头": "语义：“石头”没有生命，不能净化空气或帮助小鸟找家。", "公路": "配价：“净化”“帮助”需要能动的主语，公路做主语不成立。"}, "sentence_index": 0, "correct_answer": "树木"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们院子里有一棵树木。", "explanation": "这里应该用〈树〉。“树木”是总称，不能用量词“棵”计数，单株的树应说“一棵树”。"}, {"text": "这张桌子是用树木做的。", "explanation": "这里应该用〈木头〉。“树木”指长在地上的植物，做家具的材料要说“木头”。"}, {"text": "小羊在草地上吃树木。", "explanation": "这里应该用〈青草〉或〈树叶〉。“树木”指整棵植物，不能说“吃树木”，羊吃的是草或树叶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13474, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "树木", "is_correct": true, "explanation": "正确：“树木的叶子”指树的叶子会在秋天变黄，符合句意。"}, {"text": "房屋", "is_correct": false, "explanation": "语义：“房屋”不是植物，没有叶子，句子不成立。"}, {"text": "河水", "is_correct": false, "explanation": "语义：“河水”是液体，不会长叶子，句子矛盾。"}, {"text": "砖块", "is_correct": false, "explanation": "搭配：“叶子”只和植物搭配，不说“砖块的叶子”。"}], "explanations": {"树木": "正确：“树木的叶子”指树的叶子会在秋天变黄，符合句意。", "房屋": "语义：“房屋”不是植物，没有叶子，句子不成立。", "河水": "语义：“河水”是液体，不会长叶子，句子矛盾。", "砖块": "搭配：“叶子”只和植物搭配，不说“砖块的叶子”。"}, "sentence_index": 6, "correct_answer": "树木"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人把树木钉在墙上。", "explanation": "这里应该用〈木板〉。“树木”是长在地上的植物，不能钉在墙上，钉的是木板。"}, {"text": "奶奶每天去山上捡树木当柴火。", "explanation": "这里应该用〈树枝〉。“树木”指整棵植物，捡来当柴火的是树枝。"}, {"text": "秋天，树木一片片地落下来。", "explanation": "这里应该用〈树叶〉。一片片落下来的是树叶，“树木”是整棵植物，不会这样落下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13474, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些树木们都长得很高。", "corrected_sentence": "这些树木都长得很高。", "error_description": "错误：“树木们”；正确：“树木”。“树木”本身已经是总称，不能再加“们”表示复数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13474, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "台风把路边的树木倒吹了。", "corrected_sentence": "台风把路边的树木吹倒了。", "error_description": "错误：“倒吹了”；正确：“吹倒了”。结果补语“倒”要紧跟动词“吹”之后，不能放在“吹”前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
