INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13477, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不同生物在同一个环境中共同存在和互动", "primary_collocate": null, "pronunciation": "shēng huó", "ipa": "ʂəŋ˥ xuo˧˥", "syllable_count": 2, "sentences": [{"text": "她的意思是，不同种类的植物和动物可以一起生活，大自然才会健康。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼在水里生活，鸟在树上生活。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熊猫喜欢在竹林里生活。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些小动物在草地上生活着。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北极熊不能在热的地方生活。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人和动物应该好好地一起生活。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多鸟和鱼在这个湖边生活。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里生活着很多不同的动物。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂们在同一个蜂巢里生活。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青蛙小时候在水里生活，长大后也能在地上生活。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生活着", "label": "体标"}, {"form": "生活过", "label": "体标"}], "register": "中性", "sense_fingerprint": "生物在某个环境中共同存在、一起生活", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405dfc4a-6ee0-42e9-8dd9-f58f27602e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13477, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生活", "is_correct": true, "explanation": "正确：“一起生活”指不同生物共处于同一环境，符合句意。"}, {"text": "学习", "is_correct": false, "explanation": "语义：植物和动物不会“学习”，句中是说它们共处于一个环境。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”要求有话题或对象，不能与“植物和动物”搭配。"}, {"text": "玩耍", "is_correct": false, "explanation": "语义：“玩耍”是游戏活动，与“大自然才会健康”的语境不合。"}], "explanations": {"生活": "正确：“一起生活”指不同生物共处于同一环境，符合句意。", "学习": "语义：植物和动物不会“学习”，句中是说它们共处于一个环境。", "讨论": "搭配：“讨论”要求有话题或对象，不能与“植物和动物”搭配。", "玩耍": "语义：“玩耍”是游戏活动，与“大自然才会健康”的语境不合。"}, "sentence_index": 0, "correct_answer": "生活"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "湖底生活着很多石头。", "explanation": "这里应该用〈存在〉。生活只用于有生命的生物，石头不能说生活。"}, {"text": "这台电脑在桌上生活着。", "explanation": "这里应该用〈放〉。生活只用于生物，电脑没有生命，不能说生活。"}, {"text": "这台机器在车间里生活了三年。", "explanation": "这里应该用〈工作〉。生活指生物的生存活动，机器不是生物，不能说生活。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13477, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生活", "is_correct": true, "explanation": "正确：“在湖边生活”指鸟和鱼在此处存在，符合句意。"}, {"text": "工作", "is_correct": false, "explanation": "语义：鸟和鱼不会“工作”，句子读来不通。"}, {"text": "修建", "is_correct": false, "explanation": "配价：“修建”需要带受事宾语，句中缺少宾语，不能直接用在这里。"}, {"text": "考试", "is_correct": false, "explanation": "语义：鸟和鱼不会“考试”，与句中的湖边环境不合。"}], "explanations": {"生活": "正确：“在湖边生活”指鸟和鱼在此处存在，符合句意。", "工作": "语义：鸟和鱼不会“工作”，句子读来不通。", "修建": "配价：“修建”需要带受事宾语，句中缺少宾语，不能直接用在这里。", "考试": "语义：鸟和鱼不会“考试”，与句中的湖边环境不合。"}, "sentence_index": 6, "correct_answer": "生活"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张沙发在客厅里生活了很久。", "explanation": "这里应该用〈摆〉。生活只用于生物，沙发不能说生活。"}, {"text": "这座桥在河上生活了百年。", "explanation": "这里应该用〈矗立〉。生活指生物的生存，桥不是生物，不能说生活。"}, {"text": "那幅画在墙上生活了二十年。", "explanation": "这里应该用〈挂〉。生活只用于有生命的生物，画不能说生活。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13477, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些鸟在山上生活了着。", "corrected_sentence": "这些鸟在山上生活着。", "error_description": "体标错误：持续体标“着”不能与“了”叠用，应说“生活着”，不能说“生活了着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13477, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小鱼池塘里生活。", "corrected_sentence": "小鱼在池塘里生活。", "error_description": "介词错误：地点前缺少介词“在”，应说“小鱼在池塘里生活”，不能说“小鱼池塘里生活”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
