INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13479, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "空着的地面，没有建筑物或物体占据。", "primary_collocate": null, "pronunciation": "kòng dì", "ipa": "kʰʊŋ˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "它从小小的一块空地开始，现在已经扩展到五个小区。", "target_word": "空地", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "学校后面有一块空地，孩子们常去踢球。", "target_word": "空地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块空地很大，可以停三十辆车。", "target_word": "空地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们在空地上盖了一座新楼。", "target_word": "空地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家楼下的空地变成了小花园。", "target_word": "空地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打算在这片空地种一些树。", "target_word": "空地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那块空地以前是个停车场，现在没有车了。", "target_word": "空地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，空地上到处都是水。", "target_word": "空地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人每天早上在空地上打太极拳。", "target_word": "空地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校旁边的空地上长满了野草。", "target_word": "空地", "complexity_tier": "T3", "furigana": "xué xiào páng biān de kōng dì shàng zhǎng mǎn le yě cǎo", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "片", "label": "量词"}], "register": "中性", "sense_fingerprint": "没有建筑物或物体占据的空着的地面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d3a53-a647-4a3c-868c-246e143d7708') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13479, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空地", "is_correct": true, "explanation": "空地：没有建筑物占据的地面，正好从它开始扩展成五个小区，符合语境。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不能扩展成五个小区，与“扩展到五个小区”不符。"}, {"text": "木板", "is_correct": false, "explanation": "搭配：“扩展到……小区”说的是地面或范围，不说木板扩展成居住区。"}, {"text": "布", "is_correct": false, "explanation": "语义：布是织物，不会从一块布扩展成居住区，与语境冲突。"}], "explanations": {"空地": "空地：没有建筑物占据的地面，正好从它开始扩展成五个小区，符合语境。", "蛋糕": "语义：蛋糕是食物，不能扩展成五个小区，与“扩展到五个小区”不符。", "木板": "搭配：“扩展到……小区”说的是地面或范围，不说木板扩展成居住区。", "布": "语义：布是织物，不会从一块布扩展成居住区，与语境冲突。"}, "sentence_index": 0, "correct_answer": "空地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋楼还有两块空地，可以再住两户人家。", "explanation": "这里应该用〈空房〉。没有住户、可以入住的房屋要说空房，空地指地面，不能用来住人。"}, {"text": "车上还有一块空地，你坐那里吧。", "explanation": "这里应该用〈空位〉。空地指地面，车上没人坐的座位要说空位。"}, {"text": "表格上还有一块空地，请你填上名字。", "explanation": "这里应该用〈空格〉。表格里待填写的格子要说空格，空地指地面，不指表格中的格子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13479, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空地", "is_correct": true, "explanation": "空地：没有建筑的地面，指那片以前是停车场、现在没有车的地方，符合语境。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不可能以前是个停车场，与语境不符。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是教室里的用具，不能用作停车场，与语境冲突。"}, {"text": "肥皂", "is_correct": false, "explanation": "搭配：“是个停车场”说的是场地，不能说肥皂以前是停车场。"}], "explanations": {"空地": "空地：没有建筑的地面，指那片以前是停车场、现在没有车的地方，符合语境。", "面包": "语义：面包是食物，不可能以前是个停车场，与语境不符。", "黑板": "语义：黑板是教室里的用具，不能用作停车场，与语境冲突。", "肥皂": "搭配：“是个停车场”说的是场地，不能说肥皂以前是停车场。"}, "sentence_index": 6, "correct_answer": "空地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张试卷的最后有一大片空地，你可以在那里写答案。", "explanation": "这里应该用〈空白〉。空地指户外的地面，纸面上留出的空处要说空白。"}, {"text": "下午有一块空地，我们可以去开会。", "explanation": "这里应该用〈空档〉。空地是地面，一段时间的空余要说空档。"}, {"text": "这个岗位还有一块空地，欢迎大家来应聘。", "explanation": "这里应该用〈空缺〉。空地是地面，职位没人的情况要说空缺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13479, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把这只空地改成了停车场。", "corrected_sentence": "我们把这块空地改成了停车场。", "error_description": "量词错误：“空地”应该用“块”或“片”，不用“只”。改为：这块空地。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13479, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们把这块空地上盖了一座新楼。", "corrected_sentence": "工人们在这块空地上盖了一座新楼。", "error_description": "介词错误：盖楼的地点要用“在……上”，不能用“把”带出空地。改为：在这块空地上盖了一座新楼。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
