INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13480, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指城市里由多栋住宅楼组成的、有围墙和物业管理的居住区域。", "primary_collocate": null, "pronunciation": "xiǎo qū", "ipa": "ɕjɑʊ˨˩˦ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "它从小小的一块空地开始，现在已经扩展到五个小区。", "target_word": "小区", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我家住在一个很安静的小区。", "target_word": "小区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区有一个大门和很多树。", "target_word": "小区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区门口有一家便宜的超市。", "target_word": "小区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安每天晚上在小区里走一走。", "target_word": "小区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们新买的房子在城东的小区。", "target_word": "小区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区里的孩子常常一起玩。", "target_word": "小区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区的物业很负责，楼道总是很干净。", "target_word": "小区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在这个小区的人都认识他。", "target_word": "小区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面的人没有卡，不能进小区。", "target_word": "小区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "城市里有围墙和物业管理的住宅楼居住区", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d3a53-a647-4a3c-868c-246e143d7708') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13480, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小区", "is_correct": true, "explanation": "小区 xiǎoqū：城市里由多栋住宅楼组成、有围墙和物业的居住区，即本词的正确读音和意思。"}, {"text": "校区", "is_correct": false, "explanation": "xiào（第四声）与 xiǎo（第三声）声调不同，意思是学校的校园范围。"}, {"text": "小曲", "is_correct": false, "explanation": "qǔ（第三声）与 qū（第一声）声调不同，意思是小段的曲子。"}, {"text": "小渠", "is_correct": false, "explanation": "qú（第二声）与 qū（第一声）声调不同，意思是小水渠。"}], "explanations": {"小区": "小区 xiǎoqū：城市里由多栋住宅楼组成、有围墙和物业的居住区，即本词的正确读音和意思。", "校区": "xiào（第四声）与 xiǎo（第三声）声调不同，意思是学校的校园范围。", "小曲": "qǔ（第三声）与 qū（第一声）声调不同，意思是小段的曲子。", "小渠": "qú（第二声）与 qū（第一声）声调不同，意思是小水渠。"}, "sentence_index": null, "correct_answer": "小区"}, "level_3": {"options": [{"text": "小区", "is_correct": true, "explanation": "小区：城市里有住宅楼的居住区，它从一块空地扩展出五个小区，符合语境。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是居住区，“扩展到五个手机”说不通。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不能扩展成五个居住区。"}, {"text": "钢笔", "is_correct": false, "explanation": "搭配：“扩展到”后面接地点或范围，不接钢笔这类物品。"}], "explanations": {"小区": "小区：城市里有住宅楼的居住区，它从一块空地扩展出五个小区，符合语境。", "手机": "语义：手机不是居住区，“扩展到五个手机”说不通。", "面包": "语义：面包是食物，不能扩展成五个居住区。", "钢笔": "搭配：“扩展到”后面接地点或范围，不接钢笔这类物品。"}, "sentence_index": 0, "correct_answer": "小区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校的小区很大，有很多操场。", "explanation": "这里应该用〈校区〉。学校的范围要说校区，小区指城市中由住宅楼组成的居住区。"}, {"text": "这个小区有三十层，站在楼顶可以看到很远。", "explanation": "这里应该用〈大楼〉。小区是多栋住宅楼组成的居住区，不能说它有几层。"}, {"text": "这个小区里有很多游客在拍照。", "explanation": "这里应该用〈景区〉。游客游览拍照的地方要说景区，小区是供人居住的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13480, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小区", "is_correct": true, "explanation": "小区：供住户居住的区域，孩子们在这里一起玩，符合语境。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，孩子不会在里面一起玩。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的袋子，不是孩子们玩耍的地方。"}, {"text": "抽屉", "is_correct": false, "explanation": "搭配：“一起玩”需要活动场地，抽屉装不下一群玩耍的孩子。"}], "explanations": {"小区": "小区：供住户居住的区域，孩子们在这里一起玩，符合语境。", "冰箱": "语义：冰箱是家用电器，孩子不会在里面一起玩。", "书包": "语义：书包是装东西的袋子，不是孩子们玩耍的地方。", "抽屉": "搭配：“一起玩”需要活动场地，抽屉装不下一群玩耍的孩子。"}, "sentence_index": 6, "correct_answer": "小区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个软件小区里有很多公司，每天上班的人很多。", "explanation": "这里应该用〈园区〉。上班的企业聚集地要说园区，小区是住宅居住区。"}, {"text": "这个小区有两百个房间，每天都住满了客人。", "explanation": "这里应该用〈酒店〉。提供住宿、住满客人的地方要说酒店，小区是住宅区。"}, {"text": "这个小区有很多科室，每天病人很多。", "explanation": "这里应该用〈医院〉。有科室、接诊病人的地方要说医院，小区不设科室。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13480, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我朋友搬进了一只新小区。", "corrected_sentence": "我朋友搬进了一个新小区。", "error_description": "量词错误：“小区”应该用“个”，不用“只”。改为：一个新小区。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13480, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人每天早上在小区上锻炼身体。", "corrected_sentence": "老人每天早上在小区里锻炼身体。", "error_description": "方位词错误：小区是一片范围，要用“里”，不说“上”。改为：小区里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
