INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13481, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指童年时期，幼年的时候。", "primary_collocate": null, "pronunciation": "xiǎo shí hou", "ipa": "ɕjɑʊ˨˩˦ ʂɻ̩˧˥ xoʊ", "syllable_count": 3, "sentences": [{"text": "有一位老人说：“我小时候这里有很多树，现在我们正在把绿色还给城市。”", "target_word": "小时候", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "小时候，我最喜欢和奶奶一起睡。", "target_word": "小时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候住在一个小村子里。", "target_word": "小时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候不爱吃青菜。", "target_word": "小时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小时候的朋友，现在还常常联系。", "target_word": "小时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说我小时候很爱哭。", "target_word": "小时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小时候，每个周末爸爸都带我去公园。", "target_word": "小时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你小时候想当什么？", "target_word": "小时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我小时候学过画画，现在都忘了。", "target_word": "小时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候家里很穷，但是我们很开心。", "target_word": "小时候", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小時候", "label": "繁体"}], "register": "中性", "sense_fingerprint": "童年、幼年的时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d3a53-a647-4a3c-868c-246e143d7708') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13481, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小时候", "is_correct": true, "explanation": "正确。“小时候”指童年，与后文“现在”形成对照，符合句意。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来，与“这里有很多树”这种过去的情况矛盾。"}, {"text": "刚才", "is_correct": false, "explanation": "搭配：“刚才”只指不久前的一段时间，不能与“有很多树”这种长期存在的状态搭配。"}, {"text": "上周", "is_correct": false, "explanation": "语义：“上周”指一周内的时间，不能表示过去长时间里这里一直有很多树。"}], "explanations": {"小时候": "正确。“小时候”指童年，与后文“现在”形成对照，符合句意。", "明天": "语义：“明天”指将来，与“这里有很多树”这种过去的情况矛盾。", "刚才": "搭配：“刚才”只指不久前的一段时间，不能与“有很多树”这种长期存在的状态搭配。", "上周": "语义：“上周”指一周内的时间，不能表示过去长时间里这里一直有很多树。"}, "sentence_index": 0, "correct_answer": "小时候"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我小时候在北京上过大学。", "explanation": "这里应该用〈以前〉。“小时候”只指童年，不能指成年后上大学的经历；“以前”可泛指任何过去的时期。"}, {"text": "你等我小时候，我就回来。", "explanation": "“小时候”指童年，不表示一小段时间。这句把它当成了“很快”的意思，与句意不符。"}, {"text": "我小时候明年要去北京。", "explanation": "这里应该用〈以后〉。小时候只指过去的童年，不能指将来；〈以后〉才泛指将来的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13481, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小时候", "is_correct": true, "explanation": "正确。“小时候”指童年，与“我”的年龄和“爸爸带我去公园”的情境相符。"}, {"text": "深夜", "is_correct": false, "explanation": "搭配：“深夜”指一个具体的夜间时段，不能与“每个周末”的习惯性时间搭配。"}, {"text": "春节", "is_correct": false, "explanation": "语义：“春节”是一年一次的节日，不能说每个周末都发生。"}, {"text": "那个星期天", "is_correct": false, "explanation": "语义：“那个星期天”指某一个特定的日子，与“每个周末”的反复性矛盾。"}], "explanations": {"小时候": "正确。“小时候”指童年，与“我”的年龄和“爸爸带我去公园”的情境相符。", "深夜": "搭配：“深夜”指一个具体的夜间时段，不能与“每个周末”的习惯性时间搭配。", "春节": "语义：“春节”是一年一次的节日，不能说每个周末都发生。", "那个星期天": "语义：“那个星期天”指某一个特定的日子，与“每个周末”的反复性矛盾。"}, "sentence_index": 6, "correct_answer": "小时候"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小时候是我最好的朋友。", "explanation": "这里问题在词义：“小时候”是时间，指不了人，不能作“朋友”。应说“我小时候的朋友是我最好的朋友”，用“小时候”修饰人。"}, {"text": "妈妈把小时候搬到了厨房。", "explanation": "这里应该用〈玩具〉之类的具体物品。〈小时候〉表示时间，不能被“搬”，应说“妈妈把玩具搬到了厨房”。"}, {"text": "我们吃完饭，小时候就去睡觉了。", "explanation": "这里应该用〈随后〉。〈小时候〉指童年，不能指刚吃完饭之后的当下时刻，时间与前后文冲突；〈随后〉才表示紧接着的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13481, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候了住在乡下。", "corrected_sentence": "我小时候住在乡下。", "error_description": "“小时候”后面不能直接接“了”，“了”应去掉；正确说法是“我小时候住在乡下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13481, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我小时候的很爱笑。", "corrected_sentence": "我小时候很爱笑。", "error_description": "“小时候”后面不能加“的”再接副词“很”，“的”应去掉；正确说法是“我小时候很爱笑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
