INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13482, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指将原本属于别人的东西或地方归还给对方。", "primary_collocate": null, "pronunciation": "huán gěi", "ipa": "xwan˧˥ kei˨˩˦", "syllable_count": 2, "sentences": [{"text": "有一位老人说：“我小时候这里有很多树，现在我们正在把绿色还给城市。”", "target_word": "还给", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "请把这本书还给图书馆。", "target_word": "还给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把借来的钱还给了朋友。", "target_word": "还给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把作业还给了我们。", "target_word": "还给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我借的那本字典，下周一定要还给老师。", "target_word": "还给", "complexity_tier": "T3", "furigana": "wǒ jiè de nà běn zì diǎn , xià zhōu yí dìng yào huán gěi lǎo shī 。", "sentence_source": "generated"}, {"text": "我们要把安静还给这座老城。", "target_word": "还给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把捡到的手机还给了失主。", "target_word": "还给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你明天把雨伞还给我。", "target_word": "还给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把借来的椅子还给了学校。", "target_word": "还给", "complexity_tier": "T3", "furigana": "tā men bǎ jiè lái de yǐ zi huán gěi le xué xiào 。", "sentence_source": "generated"}, {"text": "她想把自由还给那只小鸟。", "target_word": "还给", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "还给了", "label": "体标"}, {"form": "还给过", "label": "体标"}, {"form": "還給", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把原本属于别人的东西或地方归还给对方，也可用于抽象事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d3a53-a647-4a3c-868c-246e143d7708') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13482, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "还给", "is_correct": true, "explanation": "正确。“还给”表示把原属城市的绿色归还给城市，与“小时候这里有很多树”相呼应。"}, {"text": "卖给", "is_correct": false, "explanation": "语义：“卖给”是出售，与绿色原本属于城市、需要归还的语义相反。"}, {"text": "借给", "is_correct": false, "explanation": "语义：“借给”是暂时借出，与“还”所表示的最终归还不符。"}, {"text": "送出", "is_correct": false, "explanation": "配价：“送出”的方向是离开城市，不能接“城市”作为归还的对象。"}], "explanations": {"还给": "正确。“还给”表示把原属城市的绿色归还给城市，与“小时候这里有很多树”相呼应。", "卖给": "语义：“卖给”是出售，与绿色原本属于城市、需要归还的语义相反。", "借给": "语义：“借给”是暂时借出，与“还”所表示的最终归还不符。", "送出": "配价：“送出”的方向是离开城市，不能接“城市”作为归还的对象。"}, "sentence_index": 0, "correct_answer": "还给"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把亲手做的饼干还给了妈妈。", "explanation": "这里应该用〈送给〉。还给表示归还原本属于对方的东西；饼干是我亲手做的，妈妈从未拥有过，应说“送给妈妈”。"}, {"text": "他把刚买的新自行车还给了邻居。", "explanation": "这里应该用〈送给〉。还给要求东西原属对方；这辆车是他刚买的，邻居从未拥有过，应说“送给邻居”。"}, {"text": "我把旧衣服还给了孤儿院。", "explanation": "这里应该用〈捐给〉。还给要求东西原属对方；旧衣服是捐给孤儿院的，应说“捐给孤儿院”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13482, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "还给", "is_correct": true, "explanation": "正确。“还给”表示把捡到的失物归还给原主，与“捡到的手机”“失主”相符。"}, {"text": "卖给", "is_correct": false, "explanation": "语义：“卖给”是出售，与把捡到的手机归还原主的语境相反。"}, {"text": "藏给", "is_correct": false, "explanation": "语义：“藏给”是隐藏，与归还失主的语境相反。"}, {"text": "偷给", "is_correct": false, "explanation": "语义：“偷给”是非法取得，与把捡到的手机归还原主相矛盾。"}], "explanations": {"还给": "正确。“还给”表示把捡到的失物归还给原主，与“捡到的手机”“失主”相符。", "卖给": "语义：“卖给”是出售，与把捡到的手机归还原主的语境相反。", "藏给": "语义：“藏给”是隐藏，与归还失主的语境相反。", "偷给": "语义：“偷给”是非法取得，与把捡到的手机归还原主相矛盾。"}, "sentence_index": 6, "correct_answer": "还给"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她想把新买的小米还给那只小鸟。", "explanation": "这里应该用〈喂给〉。还给要求东西原属对方；小米是刚买的，小鸟从未拥有过，应说“喂给小鸟”。"}, {"text": "她想把这把伞还给那只小鸟。", "explanation": "这里应该用〈送给〉。还给要求东西原属对方，小鸟从未拥有过这把伞，应说“送给小鸟”。"}, {"text": "她想把房子还给学生。", "explanation": "这里应该用〈出租给〉。还给表示归还原属对方的东西，学生从未拥有这套房子，应说“出租给学生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天伞还给你。", "corrected_sentence": "我明天把伞还给你。", "error_description": "“还给”带受事宾语时，宾语前要用“把”引出；漏掉“把”的“伞还给你”不成立，应说“我明天把伞还给你”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把那本字典没还给了老师。", "corrected_sentence": "我把那本字典还给了老师。", "error_description": "“没”与“了”不能同时用在“还给”前：“了”表示已完成，不能再加否定“没”；应去掉“没”，说“我把那本字典还给了老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13484, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
