INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13484, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人或集体能够产生的作用或影响", "primary_collocate": null, "pronunciation": "lì liàng", "ipa": "li˥˩ liɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "虽然一个人的力量很小，但是大家一起努力，就能带来大的改变。", "target_word": "力量", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "团结起来，我们的力量就大了。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都可以为社会贡献一份力量。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的力量不大，不能做这么大的事。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青年人是国家发展的重要力量。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者的力量帮了很多人。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用自己的力量改变这个小城市。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的力量合在一起，问题很快解决了。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个小小的团队也有改变世界的力量。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别小看孩子，他们也是一支重要的力量。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股", "label": "量词"}, {"form": "一支", "label": "量词"}], "register": "中性", "sense_fingerprint": "个人或集体能产生的作用和影响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b46a45-2baa-4fa4-b1e2-7adacd8bb984') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13484, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "力量", "is_correct": true, "explanation": "正确。lì liàng，指个人或集体能产生的作用和影响。"}, {"text": "质量", "is_correct": false, "explanation": "zhì 与 lì 声母不同（zh / l），意思是事物的好坏程度，不是作用和影响。"}, {"text": "技量", "is_correct": false, "explanation": "jì 与 lì 声母不同（j / l），意思是技艺水平，不是作用和影响。"}, {"text": "体量", "is_correct": false, "explanation": "tǐ 与 lì 声母及声调都不同，意思是体积或规模，不是作用和影响。"}], "explanations": {"力量": "正确。lì liàng，指个人或集体能产生的作用和影响。", "质量": "zhì 与 lì 声母不同（zh / l），意思是事物的好坏程度，不是作用和影响。", "技量": "jì 与 lì 声母不同（j / l），意思是技艺水平，不是作用和影响。", "体量": "tǐ 与 lì 声母及声调都不同，意思是体积或规模，不是作用和影响。"}, "sentence_index": null, "correct_answer": "力量"}, "level_3": {"options": [{"text": "力量", "is_correct": true, "explanation": "正确。力量指个人或集体能产生的作用，与“大家一起努力”“带来大的改变”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是视觉属性，不能产生作用，不能带来改变。"}, {"text": "形状", "is_correct": false, "explanation": "语义：形状是外观，不能带来大的改变。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”不能与“带来大的改变”搭配，它不表示能产生的作用。"}], "explanations": {"力量": "正确。力量指个人或集体能产生的作用，与“大家一起努力”“带来大的改变”相合。", "颜色": "语义：颜色是视觉属性，不能产生作用，不能带来改变。", "形状": "语义：形状是外观，不能带来大的改变。", "体重": "搭配：“体重”不能与“带来大的改变”搭配，它不表示能产生的作用。"}, "sentence_index": 0, "correct_answer": "力量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的力量很多，十个部门都有人。", "explanation": "这里应该用〈人手〉。“力量”不能用“很多”来形容人员数量，说人手多要用“人手”。"}, {"text": "这台机器的力量很快，一天能做三千个零件。", "explanation": "这里应该用〈效率〉。「力量」指作用或影响，不能用「快」来形容；机器工作的快慢要说「效率」。"}, {"text": "这些志愿者是一把重要的力量。", "explanation": "这里应该用〈股〉。“把”用于有柄的器具，力量应说“一股”或“一种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13484, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "力量", "is_correct": true, "explanation": "正确。这里指个人能产生的作用，可以用来改变城市。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指岁数，不能用来改变城市。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指身体的高矮，不能用来改变城市。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“用……改变城市”不说“用体积”，体积不能作为改变的手段。"}], "explanations": {"力量": "正确。这里指个人能产生的作用，可以用来改变城市。", "年龄": "语义：年龄指岁数，不能用来改变城市。", "身高": "语义：身高指身体的高矮，不能用来改变城市。", "体积": "搭配：“用……改变城市”不说“用体积”，体积不能作为改变的手段。"}, "sentence_index": 6, "correct_answer": "力量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次活动的力量很多，两百人都来了。", "explanation": "这里应该用〈人数〉。“力量”不能用“很多”来计数人，说人多要用“人数”。"}, {"text": "这条河的力量有几百公里。", "explanation": "这里应该用〈长度〉。“力量”指作用或影响，不能用来说河的长短；说河有多长要用“长度”。"}, {"text": "这群年轻人是一块重要的力量。", "explanation": "这里应该用〈股〉。“块”多用于片状或块状的东西，力量应说“一股”或“一种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13484, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次活动汇聚了一只强大的力量。", "corrected_sentence": "这次活动汇聚了一股强大的力量。", "error_description": "量词错误：“力量”应搭配“股”或“种”，“只”用于动物或成对的东西，不能修饰力量。正确说法是“一股强大的力量”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13484, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们用自己力量解决了问题。", "corrected_sentence": "他们用自己的力量解决了问题。", "error_description": "错误在于“力量”前的修饰成分漏了“的”。正确说法是“自己的力量”，代词修饰名词时要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13485, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "很大", "is_correct": true, "explanation": "正确：“大”与“小”互为反义，“影响力很小”的反义是“影响力很大”。"}, {"text": "漂亮", "is_correct": false, "explanation": "无反义关系：“漂亮”形容外貌，与影响力无关。"}, {"text": "热情", "is_correct": false, "explanation": "无反义关系：“热情”形容态度，与影响力的大小无关。"}, {"text": "快速", "is_correct": false, "explanation": "无反义关系：“快速”形容速度，与影响力的大小无关。"}], "correct_answer": "很大", "explanations": {"很大": "正确：“大”与“小”互为反义，“影响力很小”的反义是“影响力很大”。", "漂亮": "无反义关系：“漂亮”形容外貌，与影响力无关。", "热情": "无反义关系：“热情”形容态度，与影响力的大小无关。", "快速": "无反义关系：“快速”形容速度，与影响力的大小无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13485, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大", "is_correct": true, "explanation": "正确：“大”与“小”互为反义，“作用很小”的反义是“作用很大”，这里取“大”。"}, {"text": "活泼", "is_correct": false, "explanation": "无反义关系：“活泼”形容性格或动作，与作用大小无关。"}, {"text": "友好", "is_correct": false, "explanation": "无反义关系：“友好”形容关系或态度，与作用大小无关。"}, {"text": "整齐", "is_correct": false, "explanation": "无反义关系：“整齐”形容排列或状态，与作用大小无关。"}], "correct_answer": "大", "explanations": {"大": "正确：“大”与“小”互为反义，“作用很小”的反义是“作用很大”，这里取“大”。", "活泼": "无反义关系：“活泼”形容性格或动作，与作用大小无关。", "友好": "无反义关系：“友好”形容关系或态度，与作用大小无关。", "整齐": "无反义关系：“整齐”形容排列或状态，与作用大小无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13485, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示力量或作用微弱，不足以产生明显影响", "primary_collocate": null, "pronunciation": "hěn xiǎo", "ipa": "xən˨˩ ɕjɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "虽然一个人的力量很小，但是大家一起努力，就能带来大的改变。", "target_word": "很小", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这点雨对河水的影响很小，水位没有变化。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一杯水的作用很小，火还是没有灭。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是新人，在公司的影响力很小。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药的效果很小，吃了也没有用。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很小，树叶几乎不动。", "target_word": "很小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次比赛我的作用很小，主要靠队友。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法的帮助很小，问题还在。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的力气很小，推不开这扇门。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人的努力作用很小，所以我们要合作。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "力量、作用或影响微弱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '144bdcb8-b634-4814-93d5-bb47c40a03fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13485, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "很小", "is_correct": true, "explanation": "正确答案：很小（hěn xiǎo），形容力量或作用微弱。"}, {"text": "很想", "is_correct": false, "explanation": "xiǎng 与 xiǎo 只差韵母（ang 与 ao），意思是“非常想念”。"}, {"text": "很响", "is_correct": false, "explanation": "xiǎng 与 xiǎo 只差韵母（ang 与 ao），意思是“声音大”。"}, {"text": "很险", "is_correct": false, "explanation": "xiǎn 与 xiǎo 只差韵母（an 与 ao），意思是“情况危险”。"}], "explanations": {"很小": "正确答案：很小（hěn xiǎo），形容力量或作用微弱。", "很想": "xiǎng 与 xiǎo 只差韵母（ang 与 ao），意思是“非常想念”。", "很响": "xiǎng 与 xiǎo 只差韵母（ang 与 ao），意思是“声音大”。", "很险": "xiǎn 与 xiǎo 只差韵母（an 与 ao），意思是“情况危险”。"}, "sentence_index": null, "correct_answer": "很小"}, "level_3": {"options": [{"text": "很小", "is_correct": true, "explanation": "正确：“很小”与“虽然……但是……”的让步关系相符，说明个人力量弱。"}, {"text": "很干净", "is_correct": false, "explanation": "语义：“力量”不能用“干净”来描述。"}, {"text": "很热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面或气氛，不能修饰“力量”。"}, {"text": "很清楚", "is_correct": false, "explanation": "搭配：“清楚”说明是否明白或可见，不用来说力量的状态。"}], "explanations": {"很小": "正确：“很小”与“虽然……但是……”的让步关系相符，说明个人力量弱。", "很干净": "语义：“力量”不能用“干净”来描述。", "很热闹": "搭配：“热闹”形容场面或气氛，不能修饰“力量”。", "很清楚": "搭配：“清楚”说明是否明白或可见，不用来说力量的状态。"}, "sentence_index": 0, "correct_answer": "很小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的价格很小，学生也买得起。", "explanation": "〈很低〉。说价格的高低要用“很低”，“很小”不用于形容价格。"}, {"text": "他的汉语很小，老师都夸他。", "explanation": "〈很流利〉。说语言水平要用“很流利”，“很小”不用于形容汉语。"}, {"text": "现在已经很小了，大家该回家了。", "explanation": "〈很晚〉。说时间的早晚要用“很晚”，“很小”不用于表示时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13485, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很小", "is_correct": true, "explanation": "正确：“很小”与“主要靠队友”相合，说明我个人的作用不大。"}, {"text": "很甜", "is_correct": false, "explanation": "语义：“作用”不能用味道来形容。"}, {"text": "很安静", "is_correct": false, "explanation": "搭配：“安静”不能修饰“作用”。"}, {"text": "很热情", "is_correct": false, "explanation": "语义：“热情”描写人的态度，不能修饰“作用”。"}], "explanations": {"很小": "正确：“很小”与“主要靠队友”相合，说明我个人的作用不大。", "很甜": "语义：“作用”不能用味道来形容。", "很安静": "搭配：“安静”不能修饰“作用”。", "很热情": "语义：“热情”描写人的态度，不能修饰“作用”。"}, "sentence_index": 6, "correct_answer": "很小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试很小，大家都没考好。", "explanation": "〈很难〉。说考试的难度要用“很难”，“很小”不用于形容考试。"}, {"text": "他的成绩很小，每次考试都是第一名。", "explanation": "〈很好〉。说成绩好坏要用“很好”，“很小”不用于形容成绩。"}, {"text": "这辆车的速度很小，一小时能到。", "explanation": "〈很快〉。说速度快慢要用“很快”，“很小”不用于形容速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13485, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的一句话作用很很小，没人在意。", "corrected_sentence": "他的一句话作用很小，没人在意。", "error_description": "错误：“很很小”。正确：“很小”。程度副词“很”不能重叠使用，应只用一个“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13485, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这点帮助很小小的，问题还没解决。", "corrected_sentence": "这点帮助很小，问题还没解决。", "error_description": "错误：“很小小的”。正确：“很小”。“很”与重叠形式“小小的”不能同时用，应去掉“小的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
