INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13487, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "种植树木，即在土地上栽种树苗。", "primary_collocate": null, "pronunciation": "zhí shù", "ipa": "ʈʂɨ˧˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "志愿者们不再将植树视为季节性任务，而是一种持续性的本地行动，他们记录树苗存活率，轮值巡护林带，甚至建立了民间监测站，用简易设备追踪地下水位与鸟类迁徙轨迹。", "target_word": "植树", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个植树项目告诉我们，保护地球可以从身边的小事做起。", "target_word": "植树", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "春天来了，学校组织同学们去河边植树。", "target_word": "植树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷每年春天都在山坡上植树。", "target_word": "植树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "植树的时候，我负责挖坑，哥哥负责浇水。", "target_word": "植树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天我们在公园植树，大家都很开心。", "target_word": "植树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "植树可以让空气变得更干净。", "target_word": "植树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们去年在村子后面植树，现在树已经长高了。", "target_word": "植树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植树前，老师给每个人发了一棵树苗。", "target_word": "植树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我想和朋友一起去植树。", "target_word": "植树", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "植了树", "label": "体标（了）"}, {"form": "植过树", "label": "体标（过）"}, {"form": "植树节", "label": "复合"}], "register": "中性", "sense_fingerprint": "植树：把树苗栽种到土地里的行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3370b77-fb49-4e42-b46b-5b0a583e1654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
